const e="prerelease-c3a2b96a",t=["1b","2a","2b","3","4","5a","5b"],a={tests:{under18:{questions:46,pass:38},adult:{questions:36,pass:30}},areas:{signs_and_signals:{under18:16,adult:13},roadway_rules:{under18:11,adult:9},driving_safety:{under18:7,adult:5},legal_and_liability:{under18:3,adult:3},california_specific:{under18:6,adult:5},environment:{under18:3,adult:1}}},o=JSON.parse(`[{"id":"q-1b-001","fact_id":"s4-10","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"Which of these license-record changes must go through the DMV's own change process?","options":["Getting a new phone number","Switching to a different car insurer","Buying a different car","Changing your legal name"],"correct":3},{"id":"q-1b-002","fact_id":"s4-10","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"Marisol marries and takes a new surname. Her license still shows the old one. What should she do?","options":["Start the DMV's name-change process with her documents","Tell her insurer, which updates the DMV for her","Wait until the license expires and renew it","Keep driving, since the photo still looks like her"],"correct":0},{"id":"q-1b-003","fact_id":"s4-10","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Two license updates: a new home address, and a changed legal name. Which statement is right?","options":["Both are only done when the license is renewed","The address has a day limit; the name has its own DMV process","The address change is optional, but the name change has a deadline","Both can be ignored if the card is still valid"],"correct":1},{"id":"q-1b-004","fact_id":"s6_p11_roadway-008","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"On a narrow mountain road, two cars meet nose to nose. Which one has the right of way?","options":["The one going downhill","The faster one","The one that arrived first","The one going uphill"],"correct":3},{"id":"q-1b-005","fact_id":"s6_p11_roadway-008","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are driving down a one-lane mountain road. A car comes up toward you and there is no room to pass. What should you do?","options":["Squeeze past on the shoulder edge","Flash your lights and stay put","Wait for the other driver to reverse","Back up to a place where it can pass"],"correct":3},{"id":"q-1b-006","fact_id":"s6_p11_roadway-008","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which driver gives way on a steep, one-lane road with no room to pass?","options":["The driver going uphill","The driver going downhill","Both back up a little each","The driver with the heavier vehicle, whichever way it faces"],"correct":1},{"id":"q-1b-007","fact_id":"s6_p11_run2-025","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A slow vehicle is climbing a mountain pass with cars lined up behind it. Where should it let them by?","options":["Only after a driver behind it honks","By moving into the oncoming lane for a moment","Nowhere; it has the right of way","At a marked turnout, when it is safe"],"correct":3},{"id":"q-1b-008","fact_id":"s6_p11_run2-025","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive a camper up a winding grade. Six cars follow you. You see a turnout ahead. What is best?","options":["Ignore them; the speed limit is your only duty","Speed up until they stop following","Stop in the lane and wave them round","Pull into the turnout when safe and let them pass"],"correct":3},{"id":"q-1b-009","fact_id":"s6_p11_run2-025","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for mountain roads?","options":["Uphill cars give way to all downhill cars","Uphill cars back up; slow cars never stop","Slow cars wait for the first long straight section, then pull over","Downhill cars back up; slow vehicles use turnouts when safe"],"correct":3},{"id":"q-1b-010","fact_id":"s6_p11_run3-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the closest you may leave your car to a fire hydrant?","options":["10 feet away","20 feet away","15 feet away","5 feet away"],"correct":2},{"id":"q-1b-011","fact_id":"s6_p11_run3-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You need a quick errand and see a space with a hydrant at the near end. Roughly how much clear space must be left?","options":["About two car lengths","None if you stay in the car","About one car length","About half a car length"],"correct":2},{"id":"q-1b-012","fact_id":"s6_p11_run3-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing of no-parking distances is right for a fire hydrant and a crosswalk?","options":["Hydrant 20, crosswalk 15","Both are 20 feet","Hydrant 15, crosswalk 20","Both are 15 feet"],"correct":2},{"id":"q-1b-013","fact_id":"s6_p11_run3-002","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How far back from a crosswalk's approach side must you stay when you park?","options":["10 feet","30 feet","5 feet","20 feet"],"correct":3},{"id":"q-1b-014","fact_id":"s6_p11_run3-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A corner has no painted lines, but people clearly cross there. You are looking for a spot on the side you approach from. Which is OK?","options":["A spot at the corner during daylight only","A spot right at the corner, if you stay in the car","A spot 10 feet back from the corner","A spot 25 feet back from the corner"],"correct":3},{"id":"q-1b-015","fact_id":"s6_p11_run3-002","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which stops are OK to park at?","options":["Inside the 20-foot zone with hazard lights on","25 feet back from an unmarked crosswalk","Directly on the approach side of a crosswalk","12 feet from a fire hydrant"],"correct":1},{"id":"q-1b-016","fact_id":"s6_p11_run3-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At an intersection with no painted crosswalk, a person steps off the curb. Who has the right of way?","options":["The pedestrian, as at a painted crosswalk","Whoever is first to the corner","The driver, since there is no paint","The larger vehicle"],"correct":0},{"id":"q-1b-017","fact_id":"s6_p11_run3-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You turn onto a quiet side street with no crosswalk lines. A woman is already crossing. What do you do?","options":["Go ahead because there is no marking","Honk so she hurries","Edge forward slowly so she sees you are waiting","Stop and let her finish crossing"],"correct":3},{"id":"q-1b-018","fact_id":"s6_p11_run3-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement is true about crosswalks?","options":["Marked and unmarked crosswalks give people the same priority","Unmarked crosswalks only matter at night","Painted lines must be present before a driver has to yield to people","Only school crosswalks give people priority"],"correct":0},{"id":"q-1b-019","fact_id":"s6_p11_run3-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What must you do when a person crosses with a white cane or a guide dog?","options":["Sound your horn to warn them","Move slowly past them","Wait only if the signal is red","Yield and let them cross"],"correct":3},{"id":"q-1b-020","fact_id":"s6_p11_run3-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are waiting to turn right. A man with a white cane steps into the crosswalk. What now?","options":["Tap the horn once so he knows you are waiting","Creep forward to show you are there","Turn once he passes your front bumper","Stay stopped until he has crossed"],"correct":3},{"id":"q-1b-021","fact_id":"s6_p11_run3-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about drivers and a person using a guide dog in a crosswalk is right?","options":["A short tap of the horn is fine, to let them know a car is near","Drivers yield only until the pair passes the front bumper","Drivers yield and wait until the pair is fully across","Drivers yield only when the pedestrian signal shows walk"],"correct":2},{"id":"q-1b-022","fact_id":"s6_p11_run3-008","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a white curb mean?","options":["Loading goods only","Passenger pick-up and drop-off only","Parking for disabled drivers only","Parking for short errands"],"correct":1},{"id":"q-1b-023","fact_id":"s6_p11_run3-008","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You need to leave your car for an hour outside a post office. The only open space is next to a white curb. What now?","options":["Park there with the engine running so you can move if asked","The post office is public, so parking there is fine","Leave the car there for five minutes only, then move it","Find another space instead"],"correct":3},{"id":"q-1b-024","fact_id":"s6_p11_run3-008","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Match colors to purposes. Which line is right?","options":["Red: loading. Blue: passengers","White: loading. Yellow: passengers","White: passengers. Yellow: loading","White: time-limited parking. Green: loading"],"correct":2},{"id":"q-1b-025","fact_id":"s6_p11_run3-009","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a green curb mean?","options":["Parking is for buses","Parking is free all day","Parking is limited to a posted time","Only electric cars may stop"],"correct":2},{"id":"q-1b-026","fact_id":"s6_p11_run3-009","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You pull up at a green curb to run into a shop. How do you learn how long you may stay?","options":["Ask the shop owner to tell you the rule","Assume it is 24 hours unless told otherwise","Read the sign posted at that curb","Leave a note on the dash with your return time"],"correct":2},{"id":"q-1b-027","fact_id":"s6_p11_run3-009","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which curb allows ordinary short-term parking, with the limit shown on a sign?","options":["White","Red","Yellow","Green"],"correct":3},{"id":"q-1b-028","fact_id":"s6_p11_run3-010","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What may you do at a yellow curb?","options":["Leave the car there all day","Stay up to an hour while you shop","Use it if you have a disabled plate","Load or unload during the posted hours"],"correct":3},{"id":"q-1b-029","fact_id":"s6_p11_run3-010","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A shop assistant pulls up at a yellow curb to unload boxes. Is that fine?","options":["No, only trucks may use yellow curbs","Yes, during the hours posted for loading","Yes, but she must also buy a permit","No, yellow means stopping is banned"],"correct":1},{"id":"q-1b-030","fact_id":"s6_p11_run3-010","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which is correct?","options":["Red means loading is allowed","Yellow means loading, red means no stopping","White means loading, yellow means short parking","Yellow means no stopping at any time"],"correct":1},{"id":"q-1b-031","fact_id":"s6_p11_run3-014","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How long may you stop at a white curb?","options":["As long as a passenger stays in the car with the engine off","Up to ten minutes, if you stay close","As long as the engine is running","Just the time it takes for people to get in or out"],"correct":3},{"id":"q-1b-032","fact_id":"s6_p11_run3-014","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drop off your grandmother at a white curb. She asks you to wait while she goes in for an appointment. What should you do?","options":["Leave the white curb and park somewhere legal","Wait there with the engine off","Stay in the driver's seat the whole time","Wait there with your hazards on"],"correct":0},{"id":"q-1b-033","fact_id":"s6_p11_run3-014","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which action at a white curb is allowed?","options":["Loading a van for twenty minutes","Letting a passenger step out, then driving on","Parking with a time-limit ticket","Leaving the car while you shop"],"correct":1},{"id":"q-1b-034","fact_id":"s6_p11_run3-016","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A car ahead of you has stopped at a crosswalk. What do you do?","options":["Stop behind it, and do not pass","Slow down and pass if you see no one crossing","Pass it slowly on the left","Honk once so it moves along"],"correct":0},{"id":"q-1b-035","fact_id":"s6_p11_run3-016","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are in the left lane. The car in the right lane has stopped just before a crosswalk, and you cannot see why. What do you do?","options":["Slow slightly and pass if nobody is visible","Move over behind it and honk","Stop too, since a person may be crossing","Drive past it at the same speed"],"correct":2},{"id":"q-1b-036","fact_id":"s6_p11_run3-016","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which driver is right at a crosswalk where the car ahead is stopped?","options":["The one who waits until it moves","The one who passes on the right","The one who tailgates to hurry it up","The one who passes if the road looks empty"],"correct":0},{"id":"q-1b-037","fact_id":"s6_p11_run3-017","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a red curb mean?","options":["No parking, but stopping is OK","No stopping, standing or parking","Parking for a limited time","Parking for emergency vehicles only"],"correct":1},{"id":"q-1b-038","fact_id":"s6_p11_run3-017","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are late and want to dash into a shop for 30 seconds. The only space is a red curb. What is the right call?","options":["Hazard lights on, engine off, and be quick","Find a legal space instead","Stop if you stay in the car with the engine off","Stop only at the very end of the red curb, away from traffic"],"correct":1},{"id":"q-1b-039","fact_id":"s6_p11_run3-017","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair describes red and white curbs correctly?","options":["Red: quick passenger stop. White: no stopping","Red: no stopping. White: quick passenger stop","Red: loading. White: parking","Red: parking. White: no stopping"],"correct":1},{"id":"q-1b-040","fact_id":"s6_p11_run3-018","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Who may use a blue curb space?","options":["Drivers with a disabled person's permit","Anyone for ten minutes","Drivers with a residential parking permit","Delivery vehicles"],"correct":0},{"id":"q-1b-041","fact_id":"s6_p11_run3-018","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Every nearby space is full except one blue space. You will be gone only two minutes, and you have no disabled placard or plate. What do you do?","options":["Take it, since two minutes is brief","Switch on your hazards and take it only if no permit holder is waiting","A friend with a placard is on the way, so it is fine","Leave it for permit holders and find another space"],"correct":3},{"id":"q-1b-042","fact_id":"s6_p11_run3-018","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Blue and white curbs differ. Which is right?","options":["White is for disabled permit holders, blue is for quick passenger stops","Both mean no stopping, but white allows exceptions","Blue is for anyone stopping briefly","Blue is for permit holders, white is for quick passenger stops"],"correct":3},{"id":"q-1b-043","fact_id":"s6_p11_run3-019","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Your signal must run continuously for how much of the approach to a turn?","options":["The last 50 feet before the turn","The last 200 feet before the turn","Only while other cars are close","The last 100 feet before the turn"],"correct":3},{"id":"q-1b-044","fact_id":"s6_p11_run3-019","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Your right turn is 250 feet ahead. By what point must your signal be on?","options":["By the time you are about 50 feet from the turn","By the time you are 100 feet from the turn","Only if another car is close behind you","As you start the turn"],"correct":1},{"id":"q-1b-045","fact_id":"s6_p11_run3-019","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about signalling for a turn is right?","options":["You may skip the signal on an empty road","Signal for the last 100 feet, and keep it on until you turn","Signal for the last 100 feet, then switch it off before you start turning","Signal only when you change lanes, not when you turn"],"correct":1},{"id":"q-1b-046","fact_id":"s7_p11_run2-015","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the speed limit in a residential area unless a sign says otherwise?","options":["15 mph","45 mph","35 mph","25 mph"],"correct":3},{"id":"q-1b-047","fact_id":"s7_p11_run2-015","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You turn into a neighborhood with houses and children's bikes on the lawns. No speed sign is visible. How fast may you go?","options":["30 mph at most","25 mph at most","20 mph is the legal minimum","Any speed that feels safe"],"correct":1},{"id":"q-1b-048","fact_id":"s7_p11_run2-015","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which limits are right when nothing else is posted?","options":["Residential 15, alley 25","Both are 15 mph","Residential 25, alley 15","Both are 25 mph"],"correct":2},{"id":"q-1b-049","fact_id":"s7_p11_run2-017","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the highest speed allowed in an alley when no other limit is posted?","options":["10 mph","15 mph","25 mph","20 mph"],"correct":1},{"id":"q-1b-050","fact_id":"s7_p11_run2-017","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You cut through a narrow alley behind a row of shops. A delivery truck is unloading ahead. How fast should you be going, at most?","options":["25 mph","Whatever the traffic allows","15 mph","35 mph"],"correct":2},{"id":"q-1b-051","fact_id":"s7_p11_run2-017","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which place has the lowest default speed limit?","options":["A school road","A residential street","An alley","A quiet cul-de-sac"],"correct":2},{"id":"q-1b-052","fact_id":"s7_p11_run3-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A person is crossing ahead of you at a crosswalk. What must you do?","options":["Slow down or stop for them","Stop only once they are in front of your car","Speed up to clear it before they step out","Keep your speed and steer round"],"correct":0},{"id":"q-1b-053","fact_id":"s7_p11_run3-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You approach a corner with no painted lines. A child is beginning to cross. What do you do?","options":["Slow a little and edge past in front of the child","Speed up to pass before the child gets there","Slow down and stop if needed","Keep going since there is no paint"],"correct":2},{"id":"q-1b-054","fact_id":"s7_p11_run3-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How does a crosswalk driver's duty change at night?","options":["It is the same: slow or stop for people","It only applies when streetlights are on","It gets stricter: you must stop fully for any person at night","It is only for marked crosswalks at night"],"correct":0},{"id":"q-1b-055","fact_id":"s7_p11_run3-013","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A car is approaching a crosswalk. What is the pedestrian's duty?","options":["Stay out of the path of a car that is too close to stop","Step out at once, since drivers must always be able to stop","Wait until every car has stopped before stepping out","Stop in the crosswalk to make the car slow down"],"correct":0},{"id":"q-1b-056","fact_id":"s7_p11_run3-013","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A man runs into the crosswalk right in front of your moving car, far too close for you to stop. Who has broken a rule?","options":["The pedestrian, who entered the path too close","You, for not stopping in time","Neither, because it was a short distance","Nobody, because crosswalks give priority"],"correct":0},{"id":"q-1b-057","fact_id":"s7_p11_run3-013","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about pedestrian rights is right?","options":["Pedestrians must yield to any car that is already moving","In a crosswalk, drivers give way to any person who has stepped off the curb","Pedestrians may step out at a crosswalk once they have looked toward the driver","People have priority in crosswalks, but not in front of a car that cannot stop"],"correct":3},{"id":"q-1b-058","fact_id":"s7_p11_run3-014","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"While crossing in a crosswalk, which duty does a pedestrian have toward traffic?","options":["Stop and wave each car through before you start to cross","Wait until the road is empty of cars","Let drivers go first at a marked crosswalk","Not hold up traffic by stopping or lingering"],"correct":3},{"id":"q-1b-059","fact_id":"s7_p11_run3-014","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A man stands in the middle of a crosswalk chatting on his phone while cars wait. What does the rule say?","options":["Drivers may honk until he moves","He may stay put, because drivers must yield in a crosswalk","He should not hold up traffic without reason","Drivers may drive round him"],"correct":2},{"id":"q-1b-060","fact_id":"s7_p11_run3-014","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which is true about crosswalks?","options":["Drivers must yield; pedestrians must not hold up traffic needlessly","Drivers must yield, and pedestrians may stay as long as they like","Pedestrians yield to drivers except at school crosswalks","A slow pedestrian may be passed when the lane beside is clear"],"correct":0},{"id":"q-1b-061","fact_id":"signs-015","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a red octagon with a stop sign on it. What does it warn about?","options":["You must stop at this sign and give way to traffic","Traffic will merge from the right","A stop sign is coming up, so slow down","A school zone is ahead"],"correct":2},{"id":"q-1b-062","fact_id":"signs-015","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are rolling down a country road and see this diamond with a stop sign symbol. The road ahead is clear. What is best?","options":["Wait to slow until you see cars stopped ahead","Keep your speed until you see the stop line","Brake hard now and stop in the lane","Ease off the gas and get ready to stop"],"correct":3},{"id":"q-1b-063","fact_id":"signs-016","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond with a downward triangle inside it warns of what?","options":["A one-way street begins","A yield sign is ahead","A no-parking zone starts","A stop sign is ahead"],"correct":1},{"id":"q-1b-064","fact_id":"signs-016","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which sign warns that a yield sign is ahead?","options":["A yellow diamond with a red octagon inside","A yellow diamond with a plus sign inside","A yellow diamond with two lines joining into one","A yellow diamond with a downward-pointing triangle inside"],"correct":3},{"id":"q-1b-065","fact_id":"signs-017","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows red, yellow and green lights. What does it mean?","options":["Signals are broken ahead","A railroad crossing is ahead","A traffic signal is ahead","You must stop at the next light"],"correct":2},{"id":"q-1b-066","fact_id":"signs-017","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"It is dusk and you see the signal-ahead sign on a long straight road. You cannot yet see the light. What do you do?","options":["Ignore it until you can see the lights","Stop in the lane and wait until it turns green","Speed up to make the green","Watch for the signal and be ready to slow"],"correct":3},{"id":"q-1b-067","fact_id":"signs-018","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a curved arrow pointing right. What does it warn of?","options":["A one-way street to the right","A right turn only lane","A right-hand exit","A curve in the road to the right"],"correct":3},{"id":"q-1b-068","fact_id":"signs-018","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a right-bend sign at a high speed. What should you do?","options":["Move to the left lane edge and speed up","Brake hard in the middle of the curve","Slow down before the curve","Stay at your speed because the road is dry"],"correct":2},{"id":"q-1b-069","fact_id":"signs-019","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond has an arrow that bends to the left. What does it warn of?","options":["A left turn lane","A left-hand merge","A bend in the road to the left","Traffic going the other way"],"correct":2},{"id":"q-1b-070","fact_id":"signs-019","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which sign matches 'the road bends left ahead'?","options":["A diamond with a snake-like line","A diamond with two arrows pointing apart","A diamond with a right-curving arrow","A diamond with a left-curving arrow"],"correct":3},{"id":"q-1b-071","fact_id":"signs-020","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows an S-shaped arrow. What does it mean?","options":["Several bends in a row","A sharp left, then a right turn lane","A slippery road","A stretch of road works"],"correct":0},{"id":"q-1b-072","fact_id":"signs-020","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the winding-road sign at the start of a hill. What should your speed plan be?","options":["Brake hard as you enter each bend","Use the middle of the road to cut the curves","Slow to a pace that handles each bend","Take the first bend fast and slow later"],"correct":2},{"id":"q-1b-073","fact_id":"signs-021","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a lane curving in to join a straight lane. What should you expect?","options":["A crossroad, with traffic from both sides","Other traffic merging into your lane","A traffic signal at the junction","Your lane ends ahead"],"correct":1},{"id":"q-1b-074","fact_id":"signs-021","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are on a main road and see the merging-traffic sign. A car appears on the on-ramp beside you. What is a good move?","options":["Speed up so it cannot enter","Brake hard in your lane","Be ready to make room for it","Honk so it waits"],"correct":2},{"id":"q-1b-075","fact_id":"signs-022","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows two lanes narrowing to one. What does it warn of?","options":["Your lane ends ahead","A new lane begins","Traffic from the side","A road splitting into two"],"correct":0},{"id":"q-1b-076","fact_id":"signs-022","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Merging-traffic and lane-ends signs both show lines joining. What is the difference for you?","options":["Lane ends: cars beside you move over. Merging: your lane ends","Lane ends: other cars must let you in. Merging: you move over","Lane ends: your lane widens. Merging: others leave your lane","Lane ends: your lane stops. Merging: others join your lane"],"correct":3},{"id":"q-1b-077","fact_id":"signs-023","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows two arrows pointing in opposite directions. What does it say?","options":["Traffic goes both ways ahead","The road splits ahead","A U-turn is allowed","Passing is allowed here"],"correct":0},{"id":"q-1b-078","fact_id":"signs-023","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You leave a divided road and see the two-way-traffic sign. What changes for you?","options":["Oncoming cars now share the road, so stay in your own lane","The road is now one-way, so you may pick the lane you prefer","You may now use the left lane to pass other cars","Slow to a crawl until the sign ends"],"correct":0},{"id":"q-1b-079","fact_id":"signs-024","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A fluorescent yellow-green diamond shows a walking figure. What does it tell you?","options":["A school is ahead","Bicycles may cross here","People may cross here","A pedestrian bridge is ahead"],"correct":2},{"id":"q-1b-080","fact_id":"signs-024","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which color is used for pedestrian, bicycle and school crossing signs?","options":["Fluorescent yellow-green","Plain white","Bright orange","Stop-sign red"],"correct":0},{"id":"q-1b-081","fact_id":"signs-025","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a plus sign. What is ahead?","options":["A railroad crossing","A lane merge","A hospital","A road crosses yours"],"correct":3},{"id":"q-1b-082","fact_id":"signs-025","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the crossroad-ahead sign on a quiet road. What is wise?","options":["Look both ways before you reach it","Stop 100 feet before it","Assume nobody can come from the sides","Speed up so you clear it fast"],"correct":0},{"id":"q-1b-083","fact_id":"signs-026","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a car with wavy skid marks behind it. What is the warning?","options":["A speed bump is ahead","The road may be slippery when wet","Loose gravel is on the road","A sharp bend is ahead"],"correct":1},{"id":"q-1b-084","fact_id":"signs-026","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"Rain is falling and you see this sign. A red light ahead is turning. How do you slow?","options":["Brake as hard as you can","Ease off and brake gently","Downshift hard and release the clutch","Steer sharply to the side"],"correct":1},{"id":"q-1b-085","fact_id":"signs-027","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a road with a barrier in the middle, splitting into two. What does it warn of?","options":["A lane ends","A divided highway begins","A median ends ahead","A bridge ahead"],"correct":1},{"id":"q-1b-086","fact_id":"signs-027","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You pass the divided-highway sign. Where should you drive?","options":["Use either side of the median, whichever has less traffic","Keep to the right of the median","Drive on the left of the median","Use the median as a passing lane when the road is empty"],"correct":1},{"id":"q-1b-087","fact_id":"signs-028","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a leaping deer. What should you watch for?","options":["A forest ranger","Animals crossing the road","A hunting zone","A nature park exit"],"correct":1},{"id":"q-1b-088","fact_id":"signs-028","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"At dusk you see the animal-crossing sign. What should you do?","options":["Drive faster to get through quickly","Slow down and scan the sides of the road","Keep your eyes on the lane ahead only","Switch on your high beams and keep your speed"],"correct":1},{"id":"q-1b-089","fact_id":"signs-029","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"You see an orange diamond warning sign. What does the orange color tell you?","options":["A rest area is ahead","Slippery road ahead","A school zone begins","Road work is ahead"],"correct":3},{"id":"q-1b-090","fact_id":"signs-029","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which color of diamond means a work zone?","options":["Yellow-green","Blue","Orange","Red"],"correct":2},{"id":"q-1b-091","fact_id":"signs-030","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow circle with a black X and two letters R means what?","options":["A road crossing is ahead","You must stop at the next crossing","A railroad crossing is ahead","A railway station is near"],"correct":2},{"id":"q-1b-092","fact_id":"signs-030","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the round railroad warning sign. The road ahead is clear. What do you do?","options":["Stop on the tracks to look","Slow down and be ready to stop","Speed up to beat any train","Stop well before the tracks and wait"],"correct":1},{"id":"q-1b-093","fact_id":"signs-031","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A fluorescent yellow-green pentagon (five sides) shows two children walking. What does it warn of?","options":["A school crossing","A hospital","A bus stop","A playground"],"correct":0},{"id":"q-1b-094","fact_id":"signs-031","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which shape is only used for the school crossing sign?","options":["Pentagon","Circle","Diamond","Octagon"],"correct":0},{"id":"q-1b-095","fact_id":"signs-032","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow sign shaped like a pennant (a long triangle) sits on the left side of the road. What does it mean?","options":["A parking area is ahead","A school is nearby","Passing is not allowed in this zone","A lane ends ahead"],"correct":2},{"id":"q-1b-096","fact_id":"signs-032","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are stuck behind a slow truck and see the pennant sign on the left. What do you do?","options":["Pass if the oncoming lane looks empty","Tailgate closely so the truck speeds up","Pass only after checking twice for oncoming cars","Stay behind it; no passing here"],"correct":3},{"id":"q-1b-097","fact_id":"signs-036","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a truck on a steep slope. What does it tell you?","options":["A steep hill is ahead","Trucks must stop here","A truck lane begins","A weigh station is ahead"],"correct":0},{"id":"q-1b-098","fact_id":"signs-036","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the steep-hill sign at the top of a long grade. How should you go down?","options":["Drive fast to build momentum","Brake hard all the way down","Coast in neutral to save fuel","Use a low gear to control your speed"],"correct":3},{"id":"q-1b-099","fact_id":"signs-037","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows an arrow pointing at a bar over the road, with a height number. What is the warning?","options":["A low bridge or wire is ahead","A weight limit applies","A tall building is ahead","A narrow lane begins"],"correct":0},{"id":"q-1b-100","fact_id":"signs-037","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive a tall moving van and see the low-clearance sign. You are not sure the van fits. What should you do?","options":["Speed up to pass quickly","Pull up beside the bridge and judge the gap by eye","Stop and find another route","Follow the car ahead, since it got through"],"correct":2},{"id":"q-1b-101","fact_id":"signs-038","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"An orange diamond shows a person holding a sign. What does it warn of?","options":["A flagger controls traffic ahead","A traffic signal fault","A school guard","A police stop"],"correct":0},{"id":"q-1b-102","fact_id":"signs-038","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A flagger in a work zone shows STOP, but the road beyond looks clear. What do you do?","options":["Creep past at walking speed","Stay stopped until the flagger signals you on","Go ahead once you see no workers in the road","Stay stopped and sound your horn to ask the flagger to wave you on"],"correct":1},{"id":"q-1b-103","fact_id":"signs-039","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A fluorescent yellow-green diamond shows a bicycle. What does it tell you?","options":["Bicycles must stop here","A bike lane ends","Bicycles are not allowed","Bicycles may cross here"],"correct":3},{"id":"q-1b-104","fact_id":"signs-039","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which pair of signs share the fluorescent yellow-green color?","options":["School crossing and flagger","Bicycle crossing and road work","Pedestrian crossing and railroad crossing","Bicycle crossing and pedestrian crossing"],"correct":3},{"id":"q-2a-001","fact_id":"p14_gaps-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When is it legal to pass another vehicle on its right side?","options":["Only when it is safe, and without leaving the paved road","Whenever the lane on your left is moving slower than you","Any time you can use the shoulder and the shoulder is wide enough","Only on freeways, because city streets never allow it"],"correct":0},{"id":"q-2a-002","fact_id":"p14_gaps-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A car ahead on a two-lane road slows to turn left. Past its right side there is only a dirt strip. What do you do?","options":["Steer onto the dirt strip and drive around its right side","Stay on the pavement and slow down behind it until it moves","Slow down, then ease onto the dirt strip just far enough to pass","Speed up and pass on the right before it finishes turning"],"correct":1},{"id":"q-2a-003","fact_id":"p14_gaps-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Two drivers argue. Ana says passing on the right is always illegal. Ben says it is fine if you use the shoulder. Who is right?","options":["Ana; the law bans every pass on the right, safe or not","Ben; the shoulder counts as a lane for passing","Neither; it is allowed only when safe and on the pavement","Neither; it is allowed on freeways only, never on city streets"],"correct":2},{"id":"q-2a-004","fact_id":"p14_gaps-006","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What should you do about the striped area painted beside a disabled parking space?","options":["Park there if your car is small enough to fit","Use it only for a few minutes if you stay in the car","Leave it empty, as it is kept for access","Park there if you hold a disabled placard"],"correct":2},{"id":"q-2a-005","fact_id":"p14_gaps-006","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"The lot is full. You see a striped patch next to a blue space, with no car in it. You only need two minutes. What is right?","options":["Park in it with your hazard lights on","Park in it, since nobody is using it right now","Wait in the striped patch until a regular space opens up","Keep looking for another space"],"correct":3},{"id":"q-2a-006","fact_id":"p14_gaps-006","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A blue space has a striped area next to it. Who may park where?","options":["Eligible permit holders in the blue space; nobody in the stripes","Permit holders in both the blue space and the stripes","Anyone in the stripes, but only permit holders in the blue space","Anyone in the blue space for short stops, nobody in the stripes"],"correct":0},{"id":"q-2a-007","fact_id":"p14_gaps-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Traffic is slow. Before you enter an intersection on a green light, what must be true?","options":["The cross traffic is stopped and waiting for you","Room is open on the far side for your whole car","Your front bumper can clear the crosswalk","The cars ahead of you have their brake lights off"],"correct":1},{"id":"q-2a-008","fact_id":"p14_gaps-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You have a green light. Cars are stopped bumper to bumper past the intersection, with space for half your car. What do you do?","options":["Wait before the intersection until there is room","Pull in and stop in the middle, since you have the green","Creep forward so the cars behind stop honking","Move up into the crosswalk and wait there"],"correct":0},{"id":"q-2a-009","fact_id":"p14_gaps-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Many drivers think a green light always means go. Which statement fixes that idea?","options":["Green means go whenever no cross traffic is in sight","Green means go, and you may wait inside the crosswalk if needed","Green means go, but only for the first car in the line","Green means go only if your whole car can clear the far side"],"correct":3},{"id":"q-2a-010","fact_id":"p15_changes-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How close to a crosswalk may you park, where there is no curb extension?","options":["Never closer than 20 feet","Never closer than 10 feet","Never closer than 5 feet","Never closer than 30 feet"],"correct":0},{"id":"q-2a-011","fact_id":"p15_changes-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You want to park next to an intersection. The crosswalk has no paint at all. How far back do you stay?","options":["Right up to the corner, since the crosswalk is not marked","At least 20 feet, since an unmarked crosswalk still counts","About 10 feet, because only painted lines need more room","At least 15 feet, the same gap as a fire hydrant"],"correct":1},{"id":"q-2a-012","fact_id":"p15_changes-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A curb extension sticks out at a crosswalk. You stop 17 feet back from the crosswalk. What is true?","options":["It is illegal, because the limit is always 20 feet","It is legal, because the limit is 15 feet at a curb extension","It is legal, because the limit is only 10 feet there","It is illegal, because a curb extension adds 5 feet to the usual 20"],"correct":1},{"id":"q-2a-013","fact_id":"p15_changes-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing of parking distances is right?","options":["Crosswalk 20 feet (15 with a curb extension); fire hydrant 15 feet","Crosswalk 15 feet (20 with a curb extension); fire hydrant 20 feet","Crosswalk 15 feet; fire hydrant 15 feet","Crosswalk 20 feet; fire hydrant needs no distance if the curb is not red"],"correct":0},{"id":"q-2a-014","fact_id":"p15_changes-005","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When did drivers start to get tickets for parking too close to a crosswalk?","options":["On the first day of 2024, with no warning period","In 2025, after a warning period in 2024","In 2026, after two years of warnings","In 2025, with no warning period before it"],"correct":1},{"id":"q-2a-015","fact_id":"p15_changes-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"In mid-2024, a parking officer leaves a warning on a car parked 8 feet from a crosswalk. What does that mean?","options":["The warning was a mistake, since 8 feet is far enough","The driver broke no rule, since rules apply only once fines start","The car was parked wrongly, but fines had not started yet","The driver now owes a ticket by mail"],"correct":2},{"id":"q-2a-016","fact_id":"p15_changes-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Today you park 12 feet before an unmarked crosswalk and walk away. What can happen?","options":["Nothing, because a warning period still protects drivers","Nothing, because only marked crosswalks bring a ticket","A ticket, but only if a pedestrian is waiting at that moment","A ticket, since tickets for this have been allowed since 2025"],"correct":3},{"id":"q-2a-017","fact_id":"p15_changes-005","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement keeps apart the date the rule began and the date tickets began?","options":["The rule began in 2024 and tickets followed in 2025","The rule began in 2025, and tickets began the same day","Tickets began in 2024, and the rule came a year later","Both began in 2024, and tickets were issued from the first day"],"correct":0},{"id":"q-2a-018","fact_id":"p15_changes-010","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Since 2023, what happens to a pedestrian who safely crosses mid-block, outside a crosswalk?","options":["They get a ticket every time","They get no ticket if the crossing is safe","They get a ticket only if a driver has to brake","They get a written warning, never a ticket"],"correct":1},{"id":"q-2a-019","fact_id":"p15_changes-010","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are driving. A pedestrian steps off the curb mid-block, outside any crosswalk. What should you do?","options":["Keep your speed; they must wait for a gap","Slow down and stop only if they are in your lane","Speed up and pass before they reach your lane","Slow down and let them cross"],"correct":3},{"id":"q-2a-020","fact_id":"p15_changes-010","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"After the 2023 change, which statement about crosswalks and mid-block crossings is right?","options":["Mid-block crossing is still a ticket; only crosswalks are legal","A safe mid-block crossing is not ticketed, and drivers must still yield","Mid-block pedestrians have no right to cross, so drivers owe them nothing","The ticket still applies, but only on streets over 25 mph"],"correct":1},{"id":"q-2a-021","fact_id":"s6-28","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Under what condition may you turn right at a red light?","options":["After slowing to a crawl, if the cross street looks empty","Only when a sign says right turns on red are allowed","After a complete stop, unless a sign bans the turn","Only when a green arrow is showing"],"correct":2},{"id":"q-2a-022","fact_id":"s6-28","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait at a red light in the right lane. A No Turn on Red sign is posted and the cross street is empty. What do you do?","options":["Stop fully, then turn right since nothing is coming","Slow down and turn, because the sign only bans fast turns","Signal, then turn right with care","Wait for the green light before you turn"],"correct":3},{"id":"q-2a-023","fact_id":"s6-28","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You come up to a red light with no sign. The road is empty, so you roll through the turn at about 5 mph. Which statement fits?","options":["It was legal, since a right turn on red needs no stop","It was illegal, since you did not make a complete stop first","It was illegal, since you should have waited for a green arrow","It was illegal, since right turns are banned at every red light"],"correct":1},{"id":"q-2a-024","fact_id":"s6-29","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When may you turn left at a red light?","options":["From any street, after a stop, if no cars are near","From one one-way street into another, after a full stop","From the left-turn lane of any two-way street, after a stop","Never; a red light always forbids a left turn"],"correct":1},{"id":"q-2a-025","fact_id":"s6-29","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait in the left-turn lane of a two-way street, turning onto another two-way street. The light is red, nothing is coming and you have stopped. What do you do?","options":["Turn when clear, since you made a complete stop","Turn when clear, if you yield to anyone in the crossing","Wait for a green light or green arrow","Wait until the cross-street light turns yellow, then turn"],"correct":2},{"id":"q-2a-026","fact_id":"s6-29","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive on a one-way street that meets another one-way street. The light is red and no sign bans the turn. You stop completely. What may you do?","options":["Turn left when it is clear, after your full stop","Turn right only; a left turn on red is never allowed","Turn left only if a green arrow is also showing","Turn left only after sitting at the line for three seconds"],"correct":0},{"id":"q-2a-027","fact_id":"s6-29","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a red light, which turns are ever allowed after a complete stop?","options":["Right turns only; left turns are never allowed","Right turns; left turns only from a marked turn lane","Both turns anywhere when the road is clear","Right turns; left turns only one-way into one-way"],"correct":3},{"id":"q-2a-028","fact_id":"s6_p11_roadway-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At a four-way stop, which vehicle has the right to go first?","options":["The vehicle on your right, whatever the order","The vehicle that stopped first","The vehicle that is going straight","The vehicle that signals its turn first"],"correct":1},{"id":"q-2a-029","fact_id":"s6_p11_roadway-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You stop at a four-way stop. A moment later a car on the cross street stops on your right. Nobody else is there. Who goes first?","options":["The other car, since it is on your right","You do, since you stopped first","Whoever starts to move first","The car that is turning, since it needs more room"],"correct":1},{"id":"q-2a-030","fact_id":"s6_p11_roadway-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of rules is right for a four-way stop?","options":["The car on the right always goes first, even if it came later","The first car to stop goes first; in a tie the left car yields to the right","The car going straight always goes first, whatever the order","The first car to stop goes first; in a tie the right car yields to the left"],"correct":1},{"id":"q-2a-031","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Two cars on adjacent roads stop at a four-way stop at the very same moment. Which one must wait?","options":["The one on the right","The one driving the larger vehicle","The one on the left","The one on the busier road"],"correct":2},{"id":"q-2a-032","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You head north and reach a four-way stop at the same moment as a car coming from the east, on your right. Who goes first?","options":["You, since you are heading north","You, since you are going straight and not turning","Whoever signals first","The car from the east, on your right"],"correct":3},{"id":"q-2a-033","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You head south and reach a four-way stop at the same moment as a car from the east, on your left. Who goes first?","options":["You do, since the other car is on your left","The other car, since it is on a cross street","The other car, since it came from your left","Both cars together, since both stopped at once"],"correct":0},{"id":"q-2a-034","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement is right? A: at a four-way stop in a tie, left yields to right. B: at a T-intersection with no signals, who yields?","options":["A is right, and at the T the side street yields to the through road","A is right, and at the T the left car yields to the right car","A is wrong; at both places the first to arrive goes","A is right, and at the T the wider road has the right of way"],"correct":0},{"id":"q-2a-035","fact_id":"s6_p11_roadway-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At a T-intersection with no signals, which vehicles have the right of way?","options":["The first car to reach the corner","Vehicles on the road that continues past the T","Vehicles on the street that ends at the T","Vehicles on the road with more lanes"],"correct":1},{"id":"q-2a-036","fact_id":"s6_p11_roadway-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive along the straight road of a T. A car waits at the end of the side street. Who goes first?","options":["The waiting car, because it has been there longer","You do, because your road continues","The car on the right, as at a four-way stop","You take turns, one car each"],"correct":1},{"id":"q-2a-037","fact_id":"s6_p11_roadway-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a four-way stop, the order of stopping decides who goes. What decides it at a T with no signals?","options":["The order of arrival, as at the four-way stop","Which car is on the right","Which road continues straight","Which driver has the higher speed"],"correct":2},{"id":"q-2a-038","fact_id":"s6_p11_roadway-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"You turn from the side street onto the through road at a T-intersection. Whom must you yield to?","options":["Traffic from your left only, since it reaches you first","Vehicles on the through road within about one block","No one, if you arrived at the corner first","Every vehicle on the through road, from both directions"],"correct":3},{"id":"q-2a-039","fact_id":"s6_p11_roadway-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait to turn left from a side street at a T. The road is clear on your left, but a car comes from your right. What do you do?","options":["Go, since the left is clear and the right car can slow down","Wait until the car from the right has passed","Pull out halfway and wait for the car to pass","Go, if you signal first"],"correct":1},{"id":"q-2a-040","fact_id":"s6_p11_roadway-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Some drivers think a right turn from a side street needs no yielding. At a T with no signals, is that right?","options":["Yes, since right turns are never covered by yield rules","Yes, if you are quicker than the cars on the through road","No, you still yield to the through road, whatever way you turn","No, but only when the through road has more than one lane"],"correct":2},{"id":"q-2a-041","fact_id":"s6_p11_roadway-005","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What must you do at a stop sign?","options":["Slow down and go on if the way is clear","Stop fully only when other vehicles are visible","Stop fully, then look every way before you enter","Stop and look only toward traffic from your left"],"correct":2},{"id":"q-2a-042","fact_id":"s6_p11_roadway-005","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"At night you come to a quiet stop sign. No cars are in sight in any direction. What should you do?","options":["Slow to a walking pace and keep rolling","Make a full stop, look all ways, then go","Skip the stop, because it is late and quiet","Stop only if you hear a car"],"correct":1},{"id":"q-2a-043","fact_id":"s6_p11_roadway-005","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about stop signs and yield signs is right?","options":["A stop sign always needs a full stop; a yield sign only if needed","Both need a full stop, whether or not other cars are near","A yield sign always needs a full stop; a stop sign only when cars are near","Neither sign needs a stop when the road looks clear to you"],"correct":0},{"id":"q-2a-044","fact_id":"s6_p11_roadway-006","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a yield sign ask of you?","options":["Come to a full stop every time","Speed up to merge before the other traffic arrives","Give way to cars only, not to cyclists or pedestrians","Slow down and give way to anyone in your path"],"correct":3},{"id":"q-2a-045","fact_id":"s6_p11_roadway-006","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a yield sign. A cyclist is crossing ahead of you. What do you do?","options":["Slow down, and stop if needed, to let the cyclist go","Keep going, since cyclists must yield to cars","Slow down, then go first, since you are in a car","Stop only if the cyclist is in a bike lane"],"correct":0},{"id":"q-2a-046","fact_id":"s6_p11_roadway-006","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a stop sign differ from a yield sign in what it asks of you?","options":["Stop: full stop. Yield: slow down and give way","The yield sign needs the full stop; the stop sign needs slowing","Both signs need the same full stop, with no exceptions","Only the stop sign applies to bicyclists and pedestrians in your path"],"correct":0},{"id":"q-2a-047","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Two cars reach an intersection with no signs or signals at the same time. Which must yield?","options":["The one that has the other car on its right","The car on the larger of the two streets","The car that is moving at the lower speed","The car that is turning, even if the other goes straight"],"correct":0},{"id":"q-2a-048","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You reach a plain residential crossing with no signs. A car arrives from your right at the same moment. What do you do?","options":["Go first, because your street looks wider than theirs","Wait, because the larger of the two vehicles has priority","Wait, because the car on your right has the right of way","Go first, if you are going straight and the other car is turning"],"correct":2},{"id":"q-2a-049","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You reach a crossing with no signs or signals. A car arrives from your left at the same moment. What do you do?","options":["Wait, since the other car arrived with you","Go ahead without checking, since you have the right of way","Go ahead, but watch the other car","Stop and wave the other car on"],"correct":2},{"id":"q-2a-050","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"One car stopped well before the other at a four-way stop. Another pair arrives together at a crossing with no signs. Which is right?","options":["Four-way stop: first to stop goes. No signs: left yields to right","Four-way stop: left yields to right. No signs: first to arrive goes","Both: first to arrive goes","Both: the right car goes, whoever arrived first"],"correct":0},{"id":"q-2a-051","fact_id":"s6_p11_roadway-009","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a steady yellow light tell you to do?","options":["Speed up so that you cross before it turns red","Treat it as a green light for a few more seconds","Cross only if you can do it safely before red; otherwise stop","Stop at once, even if you are already in the intersection"],"correct":2},{"id":"q-2a-052","fact_id":"s6_p11_roadway-009","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are far back from an intersection when the light turns yellow. What do you do?","options":["Brake smoothly and stop before the line, since you have room","Accelerate to make it, since yellow means hurry","Brake hard, even if you stop over the line, as red is next","Slow a little and cross anyway, because the light is still not red"],"correct":0},{"id":"q-2a-053","fact_id":"s6_p11_roadway-009","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive at 35 mph and reach the limit line just as the light turns yellow. A car follows close behind. What fits the yellow-light rule?","options":["Cross with care, if you judge you can clear the crossing before red","Slam on the brakes, since yellow always means stop","Accelerate hard so you are sure to be through before red","Stop only if a pedestrian is waiting to cross"],"correct":0},{"id":"q-2a-054","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a yellow arrow signal tell you?","options":["Protected turn time is ending; finish only if already in the crossing","Your protected turn time is just starting, so you may go","You may turn at once without yielding to anyone","The signal is broken and you should treat it as a stop sign"],"correct":0},{"id":"q-2a-055","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You wait at the line for a left turn. The green arrow turns yellow before you have entered. What do you do?","options":["Go quickly through the turn, since the arrow is still lit","Stay behind the line and prepare to stop","Enter and stop at the middle of the crossing","Turn only if no oncoming car is in sight"],"correct":1},{"id":"q-2a-056","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are in the middle of a left turn when the green arrow turns yellow. What do you do?","options":["Stop where you are and wait for the next green","Slow to a crawl and let oncoming cars go by first","Finish the turn and clear the crossing","Speed through the turn so you beat the red light"],"correct":2},{"id":"q-2a-057","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a steady yellow circle differ from a yellow arrow?","options":["They mean the same; both warn that red is next","The circle ends a protected turn; the arrow warns that red is next","The circle warns that red is next; the arrow ends a protected turn","The arrow means a protected turn has begun; the circle means red is next"],"correct":2},{"id":"q-2a-058","fact_id":"s6_p11_roadway-012","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the smallest gap allowed between a parked car and a crosswalk at an intersection with no curb extension?","options":["Five feet","Ten feet","Twenty feet","Thirty feet"],"correct":2},{"id":"q-2a-059","fact_id":"s6_p11_roadway-012","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You park beside a side-street corner. There is no paint, but the sidewalk ramp shows a crosswalk. You stop 18 feet from it. What is true?","options":["You parked too close; a crosswalk needs 20 feet even unpainted","You are fine, since only crosswalks with paint count for this rule","You are fine, since 18 feet is over the 15-foot rule for crosswalks","You parked too close; a crosswalk needs 25 feet, painted or not"],"correct":0},{"id":"q-2a-060","fact_id":"s6_p11_roadway-012","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which parking spot breaks the crosswalk rule? Assume no curb extension.","options":["25 feet back from a painted crosswalk at a corner","18 feet back from an unpainted crosswalk at a corner","21 feet back from a painted crosswalk at a corner","30 feet back from an unpainted crosswalk at a corner"],"correct":1},{"id":"q-2a-061","fact_id":"s6_p11_roadway-013","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How near to a fire hydrant may you park?","options":["No closer than 5 feet","No closer than 15 feet","No closer than 3 feet","No closer than 20 feet"],"correct":1},{"id":"q-2a-062","fact_id":"s6_p11_roadway-013","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A curb has no paint. A hydrant stands there, and you plan to park 10 feet from it. What is right?","options":["Go ahead, since only a red curb is a no-parking curb","Go ahead, since the hydrant is not in use","Move back, since the rule needs 20 feet from a hydrant","Move back, since you must be at least 15 feet away"],"correct":3},{"id":"q-2a-063","fact_id":"s6_p11_roadway-013","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for parking gaps?","options":["Fire hydrant 3 feet; sidewalk ramp 15 feet","Fire hydrant 15 feet; sidewalk ramp 3 feet","Fire hydrant 20 feet; sidewalk ramp 15 feet","Both need 15 feet"],"correct":1},{"id":"q-2a-064","fact_id":"s6_p11_roadway-014","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How near to a fire station driveway may you park?","options":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 20 feet"],"correct":2},{"id":"q-2a-065","fact_id":"s6_p11_roadway-014","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You want to park on the street beside a fire station. The driveway entrance is 8 feet from your spot. What do you do?","options":["Park there, since the driveway is not blocked","Park there, since the station doors are shut","Find a spot at least 15 feet from the entrance","Find a spot at least 5 feet from the entrance"],"correct":2},{"id":"q-2a-066","fact_id":"s6_p11_roadway-014","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which comparison is right for a fire station driveway?","options":["It needs 20 feet, the same as a crosswalk","It needs 3 feet, the same as a sidewalk ramp","It needs 10 feet, half the gap for a crosswalk","It needs 15 feet, the same as a fire hydrant"],"correct":3},{"id":"q-2a-067","fact_id":"s6_p11_roadway-015","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a red curb mean?","options":["No stopping, standing or parking","No parking, but you may stop to load","Parking for a limited time","Emergency vehicles may park, others may stop briefly"],"correct":0},{"id":"q-2a-068","fact_id":"s6_p11_roadway-015","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You need to drop a parcel and will be out of your car for only 30 seconds. The only open curb is red. What do you do?","options":["Pull up with hazard lights on and run the parcel over","Stop just long enough, because 30 seconds is too short to matter","Drive on and double-park beside a parked car for 30 seconds","Drive on and stop at a legal curb"],"correct":3},{"id":"q-2a-069","fact_id":"s6_p11_roadway-015","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which curb color bans all stopping, standing and parking?","options":["Yellow","Red","White","Green"],"correct":1},{"id":"q-2a-070","fact_id":"s6_p11_roadway-016","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What is a white curb for?","options":["Short passenger pick-up and drop-off","Parking for as long as you like","Loading freight from a truck","Disabled persons with a placard"],"correct":0},{"id":"q-2a-071","fact_id":"s6_p11_roadway-016","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drop a friend at a white curb. Then you walk into a shop and leave the car for an hour. Which statement is right?","options":["That is fine, since your friend got out of the car first","A white curb is for passengers, not for parking","The white curb needs a permit that you lack","You should have used the yellow curb for this stop"],"correct":1},{"id":"q-2a-072","fact_id":"s6_p11_roadway-016","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A white curb and a yellow curb both allow brief stops. How do they differ?","options":["White is for passengers; yellow is for commercial loading","White is for freight; yellow is for passengers","White needs a permit; yellow is open to any driver","They are the same; both serve any driver stopping briefly"],"correct":0},{"id":"q-2a-073","fact_id":"s6_p11_roadway-017","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a green curb mean?","options":["Limited-time parking; the limit varies by place","Parking for as long as you like, day or night","A fixed 15-minute limit at every green curb","Loading for commercial trucks and vans only"],"correct":0},{"id":"q-2a-074","fact_id":"s6_p11_roadway-017","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A green curb has a sign that says 30 minutes. You want to park for two hours. What do you do?","options":["Park for two hours, since a green curb is free parking","Park for two hours, since the sign limit is only a suggestion","Stay no longer than 30 minutes, or go elsewhere","Stay 30 minutes, then move one space ahead and park again"],"correct":2},{"id":"q-2a-075","fact_id":"s6_p11_roadway-017","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about green and white curbs is right?","options":["Green is for passenger drop-off; white is for limited parking","Green is limited-time parking; white is for passenger loading","Both are loading zones for passengers","Both are limited-time parking"],"correct":1},{"id":"q-2a-076","fact_id":"s6_p11_roadway-018","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a yellow curb mean?","options":["Commercial loading, within posted time limits","All-day parking for local residents only","Parking for any driver who pays a meter","No stopping or standing at any time"],"correct":0},{"id":"q-2a-077","fact_id":"s6_p11_roadway-018","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A plumber unloads pipes at a yellow curb. A sign shows a 20-minute limit. How long may the van stay?","options":["As long as the job takes, since work vehicles are exempt","Up to 20 minutes, since the posted sign sets the limit","All day, if the plumber is working in the building","Up to 30 minutes, since a loading zone allows a standard half hour"],"correct":1},{"id":"q-2a-078","fact_id":"s6_p11_roadway-018","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which is the right match of curb color and use?","options":["Yellow: passenger pick-up; white: commercial loading","Yellow: limited parking; green: commercial loading","Yellow: commercial loading; green: limited parking","Yellow: no stopping; red: commercial loading"],"correct":2},{"id":"q-2a-079","fact_id":"s6_p11_roadway-019","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"Who may park at a blue curb?","options":["Anyone making a short stop of a few minutes","Drivers with a disabled placard or special plates","Any driver who pays the meter fee","Delivery drivers who are loading goods"],"correct":1},{"id":"q-2a-080","fact_id":"s6_p11_roadway-019","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You run into a shop for one minute and find the only free space has a blue curb. You have no placard. What do you do?","options":["Park there for one minute","Park there with your hazard lights on","Wait in the lane until a regular space opens up","Find a different space"],"correct":3},{"id":"q-2a-081","fact_id":"s6_p11_roadway-019","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which curb color is reserved for disabled drivers, and which allows loading for passengers?","options":["Blue is for disabled drivers; white is for passenger loading","White is for disabled drivers; blue is for passenger loading","Green is for disabled drivers; white is for loading","Blue is for disabled drivers; yellow is for passenger loading"],"correct":0},{"id":"q-2a-082","fact_id":"s6_p11_roadway-020","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"You park facing uphill with no curb. Which way do you turn the front wheels?","options":["To the right, toward the road edge","To the left, toward the road","Straight ahead","It does not matter if the brake is set"],"correct":0},{"id":"q-2a-083","fact_id":"s6_p11_roadway-020","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You park facing uphill on a country road with no curb and set the brake. Why do you also turn the front wheels right?","options":["So the wheels grip better on loose gravel","So a rolling car heads for the road edge","So the front tires dig into the slope and stop the car","So a rolling car turns left and stops against the slope"],"correct":1},{"id":"q-2a-084","fact_id":"s6_p11_roadway-020","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which setup matches parking uphill with no curb?","options":["Wheels left, toward traffic","Wheels toward the curb, as for downhill with a curb","Wheels straight","Wheels right, toward the road edge"],"correct":3},{"id":"q-2a-085","fact_id":"s6_p11_roadway-021","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"You park facing downhill next to a curb. Which way do you turn the steering wheel?","options":["Away from the curb, as you would when facing uphill","Toward the curb, so the front tire catches it if the car rolls","Straight ahead, because the parking brake alone holds the car","Toward the street, so a rolling car is easy to see"],"correct":1},{"id":"q-2a-086","fact_id":"s6_p11_roadway-021","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You park downhill beside a curb, with the brake on. A friend asks what to do with the wheels. What do you say?","options":["Point them toward the curb","Leave them straight, since the brake is set","Point them toward the street","Point them toward the curb only if the hill is steep"],"correct":0},{"id":"q-2a-087","fact_id":"s6_p11_roadway-021","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of slope and wheel direction is right when you park beside a curb?","options":["Downhill: toward the curb. Uphill: away from it","Downhill: wheels away from the curb. Uphill: toward it","Both: wheels toward the curb, whatever the slope","Both: wheels straight, with the brake set"],"correct":0},{"id":"q-2a-088","fact_id":"s6_p11_roadway-022","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"How close to a wheelchair access ramp at the curb may you park?","options":["Right up against it","No closer than 3 feet","No closer than 15 feet","No closer than 20 feet"],"correct":1},{"id":"q-2a-089","fact_id":"s6_p11_roadway-022","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"At a corner, a ramp lets wheelchair users reach the street. You leave one foot between your bumper and the ramp. What is the result?","options":["It is illegal; you must stay at least 3 feet away","It is legal, since a foot leaves some space","It is legal, since the curb is not painted","It is illegal, because a ramp needs 15 feet of clear curb"],"correct":0},{"id":"q-2a-090","fact_id":"s6_p11_roadway-022","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for parking gaps near a ramp and a driveway to a fire station?","options":["Ramp 15 feet; station driveway 3 feet","Ramp 3 feet; station driveway 15 feet","Ramp 3 feet; station driveway 3 feet","Ramp 15 feet; station driveway 15 feet"],"correct":1},{"id":"q-2a-091","fact_id":"s6_p11_roadway-027","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which step belongs before you start to move into the passing lane?","options":["Signal your plan and check your blind spot","Speed up to match the car ahead, then signal as you move out","Move over first, then signal the car behind","Turn on your high beams to warn others"],"correct":0},{"id":"q-2a-092","fact_id":"s6_p11_roadway-027","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A slow truck is ahead. The oncoming lane looks clear. What do you do before you steer into the passing lane?","options":["Check only your mirror, then pull out and signal as you pass","Signal, check your blind spot, then pull out","Close in on the truck's bumper so you can pull out fast","Flash your lights to warn the truck, then pull out"],"correct":1},{"id":"q-2a-093","fact_id":"s6_p11_roadway-027","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver says: I signal once I'm already in the passing lane. Which reply is right?","options":["That is fine, since the signal is optional","The signal belongs before you begin the pass","That is fine, as long as you signal before you return","Passing needs a horn, not a signal"],"correct":1},{"id":"q-2a-094","fact_id":"s6_p11_roadway-029","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When may you not pass near a crossroad or driveway?","options":["When you cannot see traffic that may approach","When the crossroad has a stop sign on your side","When the car ahead is going slower than the limit","Only when a sign says No Passing is posted"],"correct":0},{"id":"q-2a-095","fact_id":"s6_p11_roadway-029","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are behind a slow car near the top of a hill. A side road joins just ahead and you cannot see it. What do you do?","options":["Pass now, since the other driver will see you","Drift toward the center line to look, then pass if it seems clear","Pass now, if you flash your lights","Stay behind until you can see well"],"correct":3},{"id":"q-2a-096","fact_id":"s6_p11_roadway-029","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which place is the safest for a pass?","options":["Just before a crossroad, so you finish before the junction","A long, straight stretch, where no side road hides a car","Beside a driveway, because few cars use a driveway","A junction where the road is wide enough for two cars"],"correct":1},{"id":"q-2a-097","fact_id":"s6_p11_roadway-030","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How much open road must you have ahead before you start to pass?","options":["A few car lengths past the vehicle you pass","Enough to finish and return to your lane safely","Whatever you can see at the moment you pull out","Enough to reach the speed limit while passing"],"correct":1},{"id":"q-2a-098","fact_id":"s6_p11_roadway-030","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You follow a slow van on a winding hill road. You can see only a short way past the next curve. What do you do?","options":["Pass now, since the lane looks empty at this moment","Stay behind until a long, clear stretch appears","Pass and speed up, to get back before the curve","Stay close behind it and pull out as the curve ends"],"correct":1},{"id":"q-2a-099","fact_id":"s6_p11_roadway-030","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver checks that the opposite lane is empty as she pulls out to pass. What did she forget?","options":["To check that it stays clear long enough to finish the pass","To check that the road is straight for a quarter mile","To check that the car ahead has seen her signal","To check her speed against the limit before pulling out"],"correct":0},{"id":"q-2a-100","fact_id":"s6_p11_roadway-031","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"You have passed a vehicle. What do you do before you move back to your lane?","options":["Signal only once your wheels are across the line","Signal, then return once you are clear","Honk once instead of using a signal","Nothing, since the other driver can see you"],"correct":1},{"id":"q-2a-101","fact_id":"s6_p11_roadway-031","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You have just passed a truck. You can see its front bumper in your mirror. What is the next step?","options":["Cut back at once, since you are ahead","Signal to move back, then return smoothly","Wait until the truck honks, then return","Stay in the passing lane for several miles"],"correct":1},{"id":"q-2a-102","fact_id":"s6_p11_roadway-031","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which describes the signals in a pass?","options":["One signal at the start covers the whole pass","A signal when you return, since leaving the lane needs none","Signal to pull out, and again to return","Flash your headlights to pull out, then signal to return"],"correct":2},{"id":"q-2a-103","fact_id":"s6_p11_roadway-032","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which crosswalks give pedestrians the right of way?","options":["Only crosswalks with painted lines","Marked and unmarked crosswalks alike","Signal-controlled crosswalks and school crosswalks","Crosswalks on streets with a 25 mph limit or lower"],"correct":1},{"id":"q-2a-104","fact_id":"s6_p11_roadway-032","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You approach a quiet corner with no paint on the road. A pedestrian steps off the curb to cross. What do you do?","options":["Go on, since there is no marked crosswalk","Speed up to pass before they reach the road","Stop and let them cross","Slow down and edge past them on the open side"],"correct":2},{"id":"q-2a-105","fact_id":"s6_p11_roadway-032","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A friend says only painted crosswalks protect pedestrians. How do you reply?","options":["Agree; paint is what creates the right of way","Unmarked crosswalks protect pedestrians too","Only crosswalks with lights protect pedestrians","Pedestrians have the right of way everywhere on the road"],"correct":1},{"id":"q-2a-106","fact_id":"s6_p11_roadway-033","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A vehicle is stopped at a crosswalk. Why must you not pass it?","options":["It may be stopping for a pedestrian you cannot see","It has the right of way over every car behind it","It may be about to turn across your path","It may be waiting for the light ahead to change"],"correct":0},{"id":"q-2a-107","fact_id":"s6_p11_roadway-033","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive in the left lane. A car in the next lane stops short of a crosswalk. The road ahead looks clear. What do you do?","options":["Go past it, since your lane is clear","Hold back and check for pedestrians","Honk so the car moves on out of the way","Go past it slowly, ready to brake"],"correct":1},{"id":"q-2a-108","fact_id":"s6_p11_roadway-033","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"The driver of a car stopped at a crosswalk waves you around. What is the right call?","options":["Go around, since the driver told you it was fine","Go around, if you slow down first","Stay behind, and honk so the stopped car moves on","Stay behind; you still cannot see the crosswalk"],"correct":3},{"id":"q-2a-109","fact_id":"s6_p11_run2-017","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What should you do as you enter a roundabout?","options":["Come to a full stop at the entrance every time","Slow down and yield to traffic in the circle","Speed up to merge with the circle","Enter first if you are going straight on"],"correct":1},{"id":"q-2a-110","fact_id":"s6_p11_run2-017","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You come up to a roundabout. A car is already circling and about to pass your entry. What do you do?","options":["Enter and trust the circling car to slow down","Speed up to enter ahead of the circling car","Wait at the entry until it has passed","Roll in slowly, so the circling car steers around you"],"correct":2},{"id":"q-2a-111","fact_id":"s6_p11_run2-017","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How does a roundabout entry differ from a stop sign?","options":["A roundabout: slow down and yield. A stop sign: full stop","Both ask only for a slow-down and a yield, never a stop","A roundabout needs a full stop; a stop sign only if cars are near","A roundabout gives you the right of way; a stop sign does not"],"correct":0},{"id":"q-2a-112","fact_id":"s6_p11_run2-018","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"When you leave a roundabout, what should you do with your signal?","options":["Signal in advance of your exit","Signal after you have left the circle","Use no signal, since all traffic goes the same way","Flash your lights instead of signaling"],"correct":0},{"id":"q-2a-113","fact_id":"s6_p11_run2-018","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are in a roundabout and your exit is the next one. A car waits at that entry. What do you do?","options":["Signal before your exit so the waiting driver knows","Leave without signaling, since the driver can see your path","Brake hard at the exit and then signal","Wave at the waiting driver"],"correct":0},{"id":"q-2a-114","fact_id":"s6_p11_run2-018","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A learner says signals are pointless in a circle since everyone drives the same way. Which reply is best?","options":["Agree; drivers can read your path from inside the circle","Signals are needed only on entry","Signals are needed to show where you will leave","Signals are needed only if you change lanes in the circle"],"correct":2},{"id":"q-2a-115","fact_id":"s6_p11_run2-026","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What can happen if you turn from the wrong lane?","options":["Nothing, if you signal early enough","A violation, and a risk to other drivers","It is allowed if the cross street is empty","A warning only, never a fine"],"correct":1},{"id":"q-2a-116","fact_id":"s6_p11_run2-026","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive in the center lane of three. Your right turn is at this corner, and you are too close to change lanes safely. What do you do?","options":["Cut over to the right lane at the last second and turn","Turn from where you are, since the way is clear","Go on to the next turn and change lanes in good time","Slow to a crawl in your lane and wait for a gap to turn from it"],"correct":2},{"id":"q-2a-117","fact_id":"s6_p11_run2-026","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which is the real risk of a turn from an incorrect lane?","options":["It mostly risks a ticket, since other drivers can see you coming","It can cut across a driver's path in the right lane","It is a problem only when you forget to signal first","It matters mainly at night, when lane lines are hard to see"],"correct":1},{"id":"q-2a-118","fact_id":"s6_p11_run2-027","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At an intersection with several lanes, from which lane do you make a left turn?","options":["The left lane","The right lane","Any lane that has no cars","The middle lane only"],"correct":0},{"id":"q-2a-119","fact_id":"s6_p11_run2-027","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You plan a right turn at the next corner but you are in the left lane. The right lane looks emptier. What do you do?","options":["Turn right from the left lane to save time","Move to the right lane in good time, then turn","Wait until the corner and then cut across","Stop in the left lane until traffic clears"],"correct":1},{"id":"q-2a-120","fact_id":"s6_p11_run2-027","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing of turn and lane is right?","options":["Left turn from the left lane; right turn from whichever lane has least traffic","Right turn from the right lane; left turn from the center lane","Right turn from the right lane; left turn from the left lane","Either lane for either turn when it is empty"],"correct":2},{"id":"q-2a-121","fact_id":"s6_p11_run3-005","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How is a two-way left-turn lane marked?","options":["Solid yellow outside, dashed yellow inside","Two solid white lines on both sides","Dashed white lines on the outside, solid on the inside","A single dashed yellow line down the center"],"correct":0},{"id":"q-2a-122","fact_id":"s6_p11_run3-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A lane in the middle of a road has a solid yellow line on each outer side and a dashed yellow line on each inner side. What is it for?","options":["Passing slower cars","Left turns from either direction","Parking for deliveries","A lane for emergency vehicles only"],"correct":1},{"id":"q-2a-123","fact_id":"s6_p11_run3-005","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which marking shows a left-turn lane, not a no-passing zone?","options":["Two solid yellow lines side by side","A solid yellow line with a dashed line on the outside","A single broken white line down the middle","Dashed yellow inside, solid yellow outside"],"correct":3},{"id":"q-2a-124","fact_id":"s6_p11_run3-006","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How far may you drive in a two-way left-turn lane while you prepare for the turn?","options":["No more than 50 feet","No more than 100 feet","No more than 200 feet","No more than 500 feet"],"correct":2},{"id":"q-2a-125","fact_id":"s6_p11_run3-006","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Your driveway is a quarter mile ahead. You enter the center turn lane now so you can skip the traffic. Which statement is right?","options":["That is fine, since the lane is open to all","That is wrong, since you stay in the lane too far","That is fine, if you signal for 100 feet first","That is fine, if you are the only car using the lane"],"correct":1},{"id":"q-2a-126","fact_id":"s6_p11_run3-006","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which use of a center turn lane is right?","options":["Use it as a passing lane to get around a slow car ahead","Drive in it for a mile to skip a slow queue of cars","Wait in it for a few hundred feet before you turn left","Enter it close to your turn and leave within 200 feet"],"correct":3},{"id":"q-2a-127","fact_id":"s6_p11_run3-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How do you treat a flashing red traffic light?","options":["Slow down and go on if the road is clear","Stop fully first, as at a stop sign","Treat it as a yield sign and roll through","Treat it as a flashing yellow and slow down"],"correct":1},{"id":"q-2a-128","fact_id":"s6_p11_run3-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"At night you reach a signal that is flashing red in all directions. No cars are in sight. What do you do?","options":["Slow down to a walking pace and go on","Stop fully, look all ways, then go","Go on at speed, since the road is empty","Wait until it changes to green"],"correct":1},{"id":"q-2a-129","fact_id":"s6_p11_run3-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How do a flashing red and a flashing yellow light differ?","options":["Red: full stop. Yellow: slow and take care","Flashing red: slow down; flashing yellow: full stop","Both need a full stop before you go on","Both mean the signal is out of order"],"correct":0},{"id":"q-2a-130","fact_id":"s7-15","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a flashing yellow arrow pointing left mean?","options":["You may turn left after yielding to oncoming traffic","You have a protected left turn with no oncoming traffic","You must stop and wait for the next green light","You may turn left only if the oncoming lane is empty for a full block"],"correct":0},{"id":"q-2a-131","fact_id":"s7-15","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You wait at a light with a flashing yellow left arrow. A car is coming straight toward you. What do you do?","options":["Turn left at once, since you have the arrow","Wait for the oncoming car to pass, then turn","Speed up and turn before it gets to you","Turn left slowly, so the oncoming car can brake for you"],"correct":1},{"id":"q-2a-132","fact_id":"s7-15","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a flashing yellow left arrow differ from a steady green left arrow?","options":["Flashing yellow: protected turn; green arrow: yield first","Flashing: yield first. Green arrow: protected","Both are protected turns with no yielding","Flashing yellow: stop first; green arrow: yield first"],"correct":1},{"id":"q-2a-133","fact_id":"s7-16","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A traffic signal is completely dark. How do you treat the crossing?","options":["Like a four-way stop","Like a yield sign for the busier road","Like an open road, since no signal shows","Like a flashing yellow, slowing only"],"correct":0},{"id":"q-2a-134","fact_id":"s7-16","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A power cut turns off the signal at a crossing. You stop, and a car on the cross street stops at the same moment on your right. What do you do?","options":["Go first, since you are on the bigger road","Let the car on your right go first","Go first if you are going straight and they are turning","Wait for a police officer before moving"],"correct":1},{"id":"q-2a-135","fact_id":"s7-16","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A friend says a signal that has gone dark works like a flashing yellow: slow down and carry on. What is the better rule?","options":["Stop first, then go when it is your turn, as at a four-way stop","Slow down, and go through if no other car is close","Stay stopped until the power comes back and the signal works","Give way to the cross street, because it has the right of way"],"correct":0},{"id":"q-2b-001","fact_id":"s7_p11_roadway-006","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"At a red light, where should your car stop in relation to a marked crosswalk?","options":["On the near stripes, so you can see the cross traffic","Just past the crosswalk, at the edge of the intersection","Wherever the bumper ends up, if nobody is crossing yet","Behind the crosswalk, with the stripes clear in front of you"],"correct":3},{"id":"q-2b-002","fact_id":"s7_p11_roadway-006","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Traffic ahead is crawling. The gap in front of you is short, and moving up would leave your car sitting on the crosswalk. What do you do?","options":["Stay back until your whole car can clear the crosswalk","Move up anyway, because walkers can step around you","Stay back, then creep onto the crosswalk once the car ahead moves a little","Honk to make the car ahead pull forward"],"correct":0},{"id":"q-2b-003","fact_id":"s7_p11_roadway-006","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A stop sign has no painted line, but a crosswalk lies just beyond it. A driver stops with her front wheels on the first stripes. Which statement is right?","options":["She is fine, because the sign only asks for a stop","She is fine, if no one is crossing at that moment","She stopped too far forward and should be short of the crosswalk","She should stop beyond the crosswalk to watch the cross street"],"correct":2},{"id":"q-2b-004","fact_id":"s7_p11_roadway-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which people on foot should you give extra time to cross the street?","options":["Adults who look at a phone or wear headphones while they cross","Older adults, parents with children, and people with disabilities","Walkers who cross in groups of three or more people at a time","Walkers who are dressed in dark clothes or cross after sunset"],"correct":1},{"id":"q-2b-005","fact_id":"s7_p11_roadway-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait to turn right. An older man with a cane crosses slowly, and the cars behind you start honking. What do you do?","options":["Roll forward slowly to nudge him along","Wait until he reaches the middle of the road, then turn behind him","Keep waiting until he is well clear of your path","Wave him back so the cars behind you can go"],"correct":2},{"id":"q-2b-006","fact_id":"s7_p11_roadway-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Your light turns green while a walker with two small children is still crossing your lane. Which is right?","options":["Go at once, because green gives you priority over anyone in the road","Honk once to warn them, then drive on","Wait only until the children pass, then go while the adult is still crossing","Wait until the family has cleared your lane, then go"],"correct":3},{"id":"q-2b-007","fact_id":"s7_p11_run3-002","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a flashing yellow traffic light tell you to do?","options":["Stop fully, then go when the way is clear","Slow down, check for traffic, and go through with care","Keep your speed, because the flashing light gives you the right of way","Get ready to stop, because the light is about to turn red"],"correct":1},{"id":"q-2b-008","fact_id":"s7_p11_run3-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You approach a signal that is flashing yellow, and you can see no other cars. What is your best action?","options":["Ease off, look both ways, then continue through","Hold your speed, since nothing is coming","Come to a full stop and wait for a green light","Speed up to be through before the light changes"],"correct":0},{"id":"q-2b-009","fact_id":"s7_p11_run3-002","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How does a flashing red light at an intersection differ from a flashing yellow one?","options":["Red means slow down and look; yellow means stop first, then go on","Red means stop first, then go when clear; yellow means slow and look","Both mean stop completely and wait for a steady green light","Both mean slow down and look; only the light's color differs"],"correct":1},{"id":"q-2b-010","fact_id":"s7c-10","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"Red lights are flashing at a railroad crossing ahead. What must you do?","options":["Stop and stay stopped until it is safe to go","Slow down and cross if you see no train","Stop only if you can actually see the train","Slow down and cross if the gate is still up"],"correct":0},{"id":"q-2b-011","fact_id":"s7c-10","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You reach a crossing with no gate arm. Red lights flash, and you cannot see a train. What do you do?","options":["Cross quickly, as you cannot see a train anywhere","Treat it like a stop sign and go after a short stop","Edge forward to see farther down the track past the bend","Stop and wait, as the lights mean a train is near"],"correct":3},{"id":"q-2b-012","fact_id":"s7c-10","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a flashing red light at a railroad crossing differ from one at a street intersection?","options":["Both work like a stop sign: stop, then go when the way looks clear","Railroad: stop, then go when clear. Street: stay stopped until it stops","Railroad: stay stopped until safe. Street: stop, then go when clear","Railroad lights are only advice, while the street light is the law"],"correct":2},{"id":"q-2b-013","fact_id":"signs-001","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A red octagon with white letters stands ahead. What must you do?","options":["Come to a full stop at the limit line, then go when it is safe","Slow to a crawl and go on if the way looks clear","Stop only when other vehicles are close by on the road","Stop beyond the line so you can see the cross traffic better"],"correct":0},{"id":"q-2b-014","fact_id":"signs-001","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"It is 2 a.m. on an empty street. You reach a stop sign and see no cars in any direction. What do you do?","options":["Roll through slowly, since the road is empty","Stop fully, look both ways, then go","Stop past the line for a better view, then go","Stop only if you see headlights from the side"],"correct":1},{"id":"q-2b-015","fact_id":"signs-001","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"What is the main difference between a Stop sign and a Yield sign?","options":["Yield needs a full stop every time; Stop needs only a slowdown","Both need a full stop; Yield is only used on slower roads","Stop needs a full stop; Yield needs slowing and giving way","Stop needs a full stop only when other cars are present"],"correct":2},{"id":"q-2b-016","fact_id":"signs-002","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A red and white triangle pointing downward stands at a junction. What does it tell you?","options":["Stop completely every time before going on","Speed up to merge ahead of the other traffic","You have the right of way and the others must give way","Slow down and give way to others who have the right of way"],"correct":3},{"id":"q-2b-017","fact_id":"signs-002","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You come to a yield sign at a T-junction. A cyclist on the cross road is close enough to be a hazard. What do you do?","options":["Enter first, because bicycles are slow","Slow down, let the cyclist pass, then enter","Stop and honk so the cyclist waits for you","Speed up so you clear the junction before the cyclist arrives"],"correct":1},{"id":"q-2b-018","fact_id":"signs-002","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A walker is crossing the road you want to enter. A yield sign faces you. Who goes first?","options":["You, because yield signs apply only to other vehicles","The walker, but only if a signal tells the walker to cross","Whoever is nearer to the junction when you both arrive","The walker, because you give way to people on foot too"],"correct":3},{"id":"q-2b-019","fact_id":"signs-003","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white bar across a red square faces you at a road entrance. What does it mean?","options":["Do not drive into this road, since traffic comes toward you","Stop here first, then drive in once the road looks clear","Do not park on this road, though you may drive in","Enter, but only at a low speed with your lights on"],"correct":0},{"id":"q-2b-020","fact_id":"signs-003","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are about to turn into the end of a freeway off-ramp and a Do Not Enter sign faces you. What do you do?","options":["Enter slowly in the right-most lane","Stop, check for traffic, then enter","Do not go in; find another route","Do not wait for a gap; enter when the ramp is empty"],"correct":2},{"id":"q-2b-021","fact_id":"signs-003","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"What is the difference between a Do Not Enter sign and a Wrong Way sign?","options":["Do Not Enter is only a warning, while Wrong Way is an order to stop","Wrong Way appears only on freeway ramps, while Do Not Enter is for city streets","Do Not Enter keeps you out; Wrong Way says you are already going against traffic","They mean the same thing, and only the shape and the wording differ"],"correct":2},{"id":"q-2b-022","fact_id":"signs-004","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A red rectangle with the words WRONG WAY faces you. What does it tell you?","options":["Traffic ahead is stopped because of road repairs","You are driving against traffic and must turn around","This lane is kept for buses, taxis and shuttles","Drivers going the wrong way may take the next exit"],"correct":1},{"id":"q-2b-023","fact_id":"signs-004","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see a Wrong Way sign and headlights coming straight at you in your lane. What is your first move?","options":["Slow and stop safely, then turn around when it is safe","Speed up so you can get past all the oncoming cars","Flash your lights and carry on toward the next exit","Stop right there in your lane and wait for the cars to pass"],"correct":0},{"id":"q-2b-024","fact_id":"signs-004","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"After seeing a Wrong Way sign, a driver thinks: 'I will stop, then keep going once it is clear.' What is wrong with that plan?","options":["Nothing, because a Wrong Way sign works just like a Stop sign","Nothing, provided no cars are coming toward you in the other lane","The plan fails only on freeways, where speeds are much higher than in town","Wrong Way means turn around, since you are driving against traffic"],"correct":3},{"id":"q-2b-025","fact_id":"signs-005","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white square sign shows a U-shaped arrow with a red ring and slash. What does it mean?","options":["Do not turn left or right here","U-turns are allowed if no cars are near","U-turns are allowed only from the left lane","Do not make a U-turn here"],"correct":3},{"id":"q-2b-026","fact_id":"signs-005","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You miss your street and reach a break in the median with a No U-Turn sign. Nothing is coming. What do you do?","options":["Turn around right now, since the road is clear","Drive on and turn around at a legal place","Back up to the last side street and turn around there","Turn around only if no police car is in sight"],"correct":1},{"id":"q-2b-027","fact_id":"signs-005","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"At a junction a sign shows a U-shaped arrow crossed out in red. Which move does it ban?","options":["Turning around to go back the way you came","Turning left onto the cross street ahead","Turning right onto the cross street ahead","Making any turn at all at the junction"],"correct":0},{"id":"q-2b-028","fact_id":"signs-006","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white square sign shows a left-turn arrow with a red ring and slash. What does it mean?","options":["Only left turns are allowed from this lane","Turn left only when a green arrow shows","Do not turn left here","Do not turn left here while walkers are crossing"],"correct":2},{"id":"q-2b-029","fact_id":"signs-006","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"Your GPS says to turn left at the next junction, but a No Left Turn sign hangs there. What do you do?","options":["Follow the GPS, since it knows the road rules","Turn left when no cars are close, because the ban is for traffic","Obey the sign and find another way to turn","Make three right turns around the block, then turn left at the same junction"],"correct":2},{"id":"q-2b-030","fact_id":"signs-006","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A No Left Turn sign stands at a four-way junction, and you want to turn right. What is right?","options":["Right turns are still allowed unless a sign bans them","No turns of any kind are allowed at this four-way junction","You may turn right only after coming to a full stop first","You must go straight on through the whole junction"],"correct":0},{"id":"q-2b-031","fact_id":"signs-007","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white square sign shows a right-turn arrow with a red ring and slash. What does it mean?","options":["Do not turn right here when cars come from the left","Turn right only after a full stop","Only right turns are allowed from this lane","Do not turn right here"],"correct":3},{"id":"q-2b-032","fact_id":"signs-007","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"At a red light you want to turn right, which is usually allowed after a stop. A No Right Turn sign is posted. What do you do?","options":["Do not turn on red, but you may turn right on green","Do not turn right here, on red or on green","Stop fully, then turn right on red as usual","Turn right after a stop if no walkers are near"],"correct":1},{"id":"q-2b-033","fact_id":"signs-007","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a No Right Turn sign differ from a No Turn On Red sign?","options":["No Right Turn bans it only on red; No Turn On Red bans it at all times","They mean the same thing, and only the wording on the sign differs","No Turn On Red bans only left turns made from one-way streets","No Right Turn bans it at all times; No Turn On Red bans it only on red"],"correct":3},{"id":"q-2b-034","fact_id":"signs-008","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does the number on a white rectangular Speed Limit sign mean?","options":["The speed you should hold in all kinds of weather","The slowest speed that is allowed on that road","The top legal speed in mph for good conditions","The top speed in kilometers per hour on that road"],"correct":2},{"id":"q-2b-035","fact_id":"signs-008","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A sign says SPEED LIMIT 55. It is raining hard and the road is slick. How fast do you drive?","options":["Exactly 55, because the sign sets the correct speed","Slower than 55, since the limit assumes good conditions","Up to 60, since drivers get a small margin","Well under 30, since rain makes every road dangerous"],"correct":1},{"id":"q-2b-036","fact_id":"signs-008","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about a posted speed limit is right?","options":["It is a maximum that bad weather can lower","It is a target speed you should reach on open roads","It is the legal speed no matter what the weather is","It is a minimum, and driving below it is a violation"],"correct":0},{"id":"q-2b-037","fact_id":"signs-009","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A black rectangle shows a white arrow and the words ONE WAY. What does it mean?","options":["Traffic moves only in the direction of the arrow","Cars follow the arrow, but cyclists may ride the other way","You may drive against the arrow if you go slowly","The arrow only shows where the next turn lane starts"],"correct":0},{"id":"q-2b-038","fact_id":"signs-009","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You parked on a one-way street and now want to go back the way you came. What do you do?","options":["Pull out against the arrow if no cars are in sight","Make a U-turn across the street to face the other way","Go with the arrow and loop back by another street","Back up the whole block against the arrow, slowly"],"correct":2},{"id":"q-2b-039","fact_id":"signs-009","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A One Way sign points right at a corner where you want to turn left onto the cross street. Which statement is right?","options":["Turn left only after a full stop and a look both ways","The sign matters only on freeways, so a left turn is fine","That left turn goes against traffic, so wait for a green arrow","That left turn goes against traffic, so use another street"],"correct":3},{"id":"q-2b-040","fact_id":"signs-010","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A Keep Right sign stands on an island in the road. What does it tell you?","options":["Pass on the left, because the arrow shows a lane shift","Pass the island on its right side","Stay in your lane, since the island is only a warning","Pass on either side, as long as you slow down"],"correct":1},{"id":"q-2b-041","fact_id":"signs-010","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a concrete island in the middle of the road with a Keep Right sign. No one is behind you. What do you do?","options":["Go left of it, since no one is coming","Steer right of the island, but only after stopping for the other lane","Pass it on the side where the road looks wider","Steer to the right of the island and continue"],"correct":3},{"id":"q-2b-042","fact_id":"signs-010","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"You pass an island that carries a Keep Right sign. Which describes your path?","options":["A straight path, with the island staying on your right","A straight path, with the island staying on your left","A straight path, with the island on your left, after a full stop","A pass on either side of the island, as long as you slow down"],"correct":1},{"id":"q-2b-043","fact_id":"signs-011","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white sign shows a red letter P with a slash through it. What does it mean?","options":["You may not stop here even for a moment","Only drivers with a disabled placard may park here","You may not park in this spot","Parking is allowed here, but only outside street-cleaning hours"],"correct":2},{"id":"q-2b-044","fact_id":"signs-011","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You want to wait for a friend by a curb where a red P with a slash is posted. What do you do?","options":["Find a legal space nearby and park there instead","Stop there and leave your hazard lights flashing","Wait a few minutes, since nobody will mind","Park in the driveway of the building next door while you wait"],"correct":0},{"id":"q-2b-045","fact_id":"signs-011","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A driver thinks the No Parking sign also bans driving down that street. Which statement is right?","options":["It bans parking only, so you may still drive along it","It closes the whole street, so nobody may drive along it","It bans parking by trucks and buses only","It is advice only, so drivers need not follow it"],"correct":0},{"id":"q-2b-046","fact_id":"signs-012","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white X-shaped sign reads RAILROAD CROSSING beside the road. What does it ask of you?","options":["Always stop completely, whether or not a train is near","Be ready to stop, and yield to a train that is near","Honk your horn, then cross without stopping","Be ready to stop, but only at night or in poor weather"],"correct":1},{"id":"q-2b-047","fact_id":"signs-012","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a crossing marked only by a crossbuck, with no lights or gate. A train is close. What do you do?","options":["Cross before it arrives, because there are no lights","Stop and wait until the train is a few seconds away, then cross","Wait only if you hear the train blow its horn","Stop and yield, crossing only after the train passes"],"correct":3},{"id":"q-2b-048","fact_id":"signs-012","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a bare crossbuck sign differ from flashing red crossing lights?","options":["The lights are optional, and the sign is the one you must obey","Both need a full stop every time, whether or not a train is near","Lights order a stop; the bare sign asks you to yield to a near train","The sign is for trucks only, and the lights are for cars"],"correct":2},{"id":"q-2b-049","fact_id":"signs-013","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A sign next to a traffic light reads NO TURN ON RED. What does it tell you?","options":["Turn after a full stop when the way is clear","Turn on red only if no walkers are crossing","The light is broken, so treat the corner as a stop sign","Wait for the green light before you turn"],"correct":3},{"id":"q-2b-050","fact_id":"signs-013","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are first at a red light in the right lane, and you plan to turn right. A NO TURN ON RED sign hangs above. No cars are in view. What do you do?","options":["Turn right after a careful stop, since the road is clear","Make the right turn slowly and give way to any walkers","Stay stopped until the light turns green","Stay stopped until the walkers clear, then turn right on red"],"correct":2},{"id":"q-2b-051","fact_id":"signs-013","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about turning right on a red light is correct?","options":["It is never allowed anywhere in California","It is allowed after a full stop, unless a sign bans it","It is allowed without stopping, as long as no one is near","It is allowed only for the car at the front of the line"],"correct":1},{"id":"q-2b-052","fact_id":"signs-014","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A STOP HERE ON RED sign stands by a painted line at a signal. Where does your car stop when the light is red?","options":["Behind the painted line, with your whole car short of it","Past the line, in the crosswalk, for a better view of the signal","Behind the painted line, but only while cross traffic is moving","Right on the painted line, with your front bumper just over it"],"correct":0},{"id":"q-2b-053","fact_id":"signs-014","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are first at a red light. The stop line is a car length back from where you can see the signal best. Where do you stop?","options":["Past the line, where you can see the light better","In the crosswalk, so the signal head is clear in view","Anywhere near the line, within one car length","At the line, even though your view is not perfect"],"correct":3},{"id":"q-2b-054","fact_id":"signs-014","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"You stopped at the line for a red signal and want to drive straight on. When may you go?","options":["When the light turns green","Whenever the cross street looks clear, as at a stop sign","When the light has stayed red for a long time","When the car ahead of you drives off"],"correct":0},{"id":"q-2b-055","fact_id":"signs-033","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white rectangular sign reads DO NOT PASS. What does it tell you?","options":["Passing is allowed only on the right side in this stretch","Slow down and let other vehicles pass you","Passing is banned in this stretch of road","Passing is allowed only for vehicles driving very slowly"],"correct":2},{"id":"q-2b-056","fact_id":"signs-033","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are stuck behind a slow truck on a two-lane road. The road ahead looks clear and a Do Not Pass sign stands on your right. What do you do?","options":["Pass quickly, because the road looks clear","Stay behind the truck until the no-passing zone ends","Stay behind it, then pass at the first long gap whatever the sign says","Use the shoulder to get around it and stay out of the lane"],"correct":1},{"id":"q-2b-057","fact_id":"signs-033","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A Do Not Pass sign stands beside a stretch where the center line is broken. What rule governs passing there?","options":["The broken line decides, so passing is fine when the road is clear","The sign overrides the broken line, so passing is banned","The sign counts only when the vehicle ahead is below the limit","The sign counts only where you cannot see far down the road"],"correct":1},{"id":"q-2b-058","fact_id":"signs-034","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A square white sign shows a bicycle with a red ring and slash. What does it mean?","options":["Bicycles have the right of way here","Watch for bicycles crossing ahead","Bicycles are not allowed here","Bicycles must ride on the sidewalk here"],"correct":2},{"id":"q-2b-059","fact_id":"signs-034","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive past a No Bicycles sign and see a rider ahead. What should you do?","options":["Speed up, since riders are not allowed there","Slow down and follow the rider closely until he leaves the road","Ignore the rider, as the ban removes your duty of care","Still watch for the rider and pass with room to spare"],"correct":3},{"id":"q-2b-060","fact_id":"signs-034","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"What is the difference between a No Bicycles sign and a Bike Lane sign?","options":["No Bicycles bans riders; Bike Lane sets a lane aside for them","Bike Lane bans riders from the road; No Bicycles sets a lane aside","No Bicycles is for riders on sidewalks, and Bike Lane is for riders on the road","Both ban riders from the road, but Bike Lane applies only at night"],"correct":0},{"id":"q-2b-061","fact_id":"signs-035","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A square white sign shows a walking figure with a red ring and slash. What does it mean?","options":["Crossing is allowed at this exact spot","Pedestrians have the right of way on this road","A green light is needed before anyone may cross","People on foot are not allowed here"],"correct":3},{"id":"q-2b-062","fact_id":"signs-035","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive on a road with a No Pedestrians sign and see a person walking at the edge. What do you do?","options":["Drive on as usual, since nobody should be there","Honk to make the walker leave the road","Slow down and pass with care; people may be there","Stop in your lane and wait for the walker to leave"],"correct":2},{"id":"q-2b-063","fact_id":"signs-035","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A driver says: 'The No Pedestrians sign means nobody will ever be on this road.' What is the best reply?","options":["People may still be there, so stay alert for them","That is right, so a high speed is safe on that road","People may still be there, so sound your horn to clear them","Only drivers with a broken-down car may be there, so watch only the shoulder"],"correct":0},{"id":"q-2b-064","fact_id":"signs-044","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"Two solid yellow lines run down the middle of a road. What do they mean?","options":["You may cross them to pass when the road ahead is empty","Do not cross, except to turn left into a driveway or opening","You may cross them only to pass a slow truck or bus","Drivers on the left side of the lines may cross them, others may not"],"correct":1},{"id":"q-2b-065","fact_id":"signs-044","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You want to turn left into your own driveway on a road with double solid yellow lines. Nothing is coming. What do you do?","options":["Never cross them, even to enter your own driveway","Drive on until the lines end, then make a U-turn","Stop on the lines until a gap opens, then cross","Cross the lines into your driveway when it is safe"],"correct":3},{"id":"q-2b-066","fact_id":"signs-044","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a double solid yellow line differ from a solid line paired with a broken line?","options":["Double solid bans passing for both sides; solid-and-broken lets one side pass","Double solid bans passing on one side only; solid-and-broken bans it on both sides","Both ban passing for everyone, since the gaps only mark where the paint is worn","Both allow passing whenever the road ahead is empty of cars"],"correct":0},{"id":"q-2b-067","fact_id":"signs-045","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A single broken yellow line runs down the middle of a two-way road. What does it mean?","options":["Never pass here, because the line only splits the two directions","You may pass when it is clear and the line is on your side","Pass freely, since the dashes mean no oncoming cars","Cross it only to turn, never to pass"],"correct":1},{"id":"q-2b-068","fact_id":"signs-045","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You follow a slow van on a two-way road with a broken yellow center line. A car appears far ahead in the other lane. What do you do?","options":["Pass at once, since the dashes give you priority","Pass if the oncoming car is small enough to look far away","Wait until the oncoming lane is clear, then pass","Wait for the oncoming car to go by, then pass without looking again"],"correct":2},{"id":"q-2b-069","fact_id":"signs-045","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A driver sees a broken yellow line on one road and a broken white line on another. Which statement is right?","options":["Yellow separates opposing traffic; white separates lanes going the same way","White separates opposing traffic; yellow separates lanes going the same way","Yellow marks bike lanes, and white marks two-way roads","Yellow is for city streets, and white is for highways"],"correct":0},{"id":"q-2b-070","fact_id":"signs-046","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A solid yellow line sits beside a broken yellow line in the middle of the road. When may you pass?","options":["Only if the solid line is on your side","Always, when no cars are coming","Never, from either direction","Only if the broken line is on your side"],"correct":3},{"id":"q-2b-071","fact_id":"signs-046","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"On a two-way road the solid yellow line is on your side and the broken line is on the other. A slow car is ahead. What do you do?","options":["Go by if the road is clear, since a broken line is close by","Stay behind the car, but cross the line to peek ahead first","Do not pass, even though the other side may","Overtake if the car ahead drives below the speed limit"],"correct":2},{"id":"q-2b-072","fact_id":"signs-046","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"You are on the solid-line side of a solid-and-broken pair. An oncoming driver is on the broken-line side. Who may pass?","options":["Only you, since the solid line marks the passing lane","Only the oncoming driver, when it is safe","Both of you, whenever the road is clear","Neither of you, because a solid line is present"],"correct":1},{"id":"q-2b-073","fact_id":"signs-047","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A broken white line separates two lanes. What does it mean?","options":["The lanes go opposite ways, so you should avoid crossing it","The lanes go the same way, and you may change lanes when safe","You may change lanes only to pass another vehicle","You may change lanes at any time, even with a car alongside"],"correct":1},{"id":"q-2b-074","fact_id":"signs-047","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive in the middle lane of a three-lane road, and you need the right lane for your exit. A car is alongside you in that lane. What do you do?","options":["Wait for a gap in that lane, check, then move over","Move over now, since the dashes allow lane changes","Wait for the car to pass, then move over without looking again","Cross the lane quickly and signal after the move"],"correct":0},{"id":"q-2b-075","fact_id":"signs-047","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How do a broken white lane line and a solid white lane line differ?","options":["Broken: stay in your lane. Solid: change lanes whenever you wish","Broken marks opposing lanes; solid marks lanes going the same way","Broken: change lanes when safe. Solid: stay put unless you must","There is no difference; both let you change lanes freely"],"correct":2},{"id":"q-2b-076","fact_id":"signs-048","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A solid white line separates two lanes that go your way. What does it ask of you?","options":["Treat the lane on its other side as oncoming traffic","Cross it whenever the road looks clear","Treat the lane beyond it as closed to your car","Do not change lanes unless you have to"],"correct":3},{"id":"q-2b-077","fact_id":"signs-048","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A solid white line runs between your lane and the exit lane, and a car is beside you in that lane. What do you do?","options":["Stay in your lane and take a later exit","Cross the line quickly before the car notices","Stay in your lane until just before the exit, then cross","Signal and move over so the car has to make room"],"correct":0},{"id":"q-2b-078","fact_id":"signs-048","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A solid white line separates two lanes that go your way. Which is a good reason to cross it?","options":["Reaching an exit that you almost missed","Avoiding a hazard that blocks your lane","Getting around a slower car in front of you","Skipping ahead of a long line in your lane"],"correct":1},{"id":"q-2b-079","fact_id":"signs-049","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A solid white line is painted next to the shoulder. What does it show?","options":["The center of a two-way road, which you should keep right of","A lane kept for bicycles and walkers only","The point beyond which parking is allowed","Where the roadway ends, so you stay between the edge lines"],"correct":3},{"id":"q-2b-080","fact_id":"signs-049","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive at night on a country road with no street lights. Your headlights show a white line on the right. How do you use it?","options":["As a warning that you should slow down wherever it appears","As a track to ride on, with your right wheels on top of it","As a guide to keep your car within the road","As a guide to the center of the road, so you can stay left of it"],"correct":2},{"id":"q-2b-081","fact_id":"signs-049","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"What is the difference between a white edge line and a white lane line?","options":["Edge line marks the road's edge; lane line divides same-way lanes","The edge line splits opposing traffic; a lane line marks the shoulder","There is no difference, since both mark the lanes of the road","The edge line may be crossed freely; a lane line may never be crossed"],"correct":0},{"id":"q-2b-082","fact_id":"signs-050","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"Wide white bars are painted across the road ahead. What do they mark?","options":["A stop line for vehicles that has no link to walkers","A place where you may park briefly while you shop","A speed hump that you should cross very slowly","A crosswalk that needs you to stop for people"],"correct":3},{"id":"q-2b-083","fact_id":"signs-050","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A group of walkers enters a marked crosswalk ahead of you. The last one is still near the curb. What do you do?","options":["Stay stopped until the first walkers reach the far curb, then go","Stay stopped until everyone has crossed","Drive on, since most of the group is across","Wave the last walker to wait and drive through"],"correct":1},{"id":"q-2b-084","fact_id":"signs-050","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"At a marked crosswalk with no traffic light, who must you stop for?","options":["Every child and older walker who is crossing there","Every walker who is already past the middle of the road","Every person on foot who is crossing there","Every walker who looks at you or waves first"],"correct":2},{"id":"q-2b-085","fact_id":"signs-051","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A wide white line crosses your lane before an intersection. Where do your front wheels stop?","options":["Right on the line, with the bumper over it","Just past the line, where you can see better","Behind the line, never over it","Halfway across it, to show you have stopped"],"correct":2},{"id":"q-2b-086","fact_id":"signs-051","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are first at a red light, and the stop line is faded but still visible. Where do your front wheels go?","options":["Over the line, since faded paint no longer counts","On the crosswalk, since the paint is hard to see","A full car length short of it, just to be safe","Behind the faded line"],"correct":3},{"id":"q-2b-087","fact_id":"signs-051","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"At a stop sign you see a white stop line, then a crosswalk beyond it. Where do you stop?","options":["At the stop line, which is before the crosswalk","On the crosswalk, since the line is only for trucks","Past the crosswalk, to see the cross street","Between the line and the crosswalk, at the middle"],"correct":0},{"id":"q-2b-088","fact_id":"signs-052","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white diamond is painted in a lane. What does it mean?","options":["The lane is reserved for buses, shuttles and bicycles only","The lane is for vehicles with enough people; see sign for hours","The lane is for police cars and other emergency vehicles only","The lane ends soon, so you must merge out of it early"],"correct":1},{"id":"q-2b-089","fact_id":"signs-052","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive alone, and a diamond is painted in the left lane. A sign shows a two-person minimum and rush hours, and it is rush hour now. What do you do?","options":["Enter it, because a diamond lane is for the fastest cars","Stay out of that lane, since you are alone","Stay out of it unless traffic in the other lanes stops","Move in briefly to pass one slow car, then move back"],"correct":1},{"id":"q-2b-090","fact_id":"signs-052","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Where do you learn the hours for a carpool lane?","options":["From the posted sign, not from the painted diamond","From the diamond, since it is painted to match the posted hours","From other drivers, since cars in the lane show that it is open","From the DMV handbook, which lists one schedule for these lanes"],"correct":0},{"id":"q-2b-091","fact_id":"signs-053","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a red curb mean?","options":["No parking, but a quick stop is fine","Parking for emergency vehicles only; others may stop","Loading and unloading for a short time only","No stopping, no standing, and no parking"],"correct":3},{"id":"q-2b-092","fact_id":"signs-053","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You want to dash into a shop for one minute. The curb in front is red. What do you do?","options":["Pull in for a minute, as long as the engine stays running","Do not park there, but stop for one minute with your hazards on","Find a legal place; do not stop at the red curb","Wait there if you stay inside the car the whole time"],"correct":2},{"id":"q-2b-093","fact_id":"signs-053","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A driver says that red and yellow curbs both let you stop to drop off. Which is right?","options":["Both allow a short stop, but yellow is for trucks only","Yellow allows brief loading; red allows no stop at all","Red allows a short stop; yellow allows no stop","Both ban stopping at all hours of the day"],"correct":1},{"id":"q-2b-094","fact_id":"signs-054","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a yellow curb allow?","options":["Loading or unloading for a short time only","Parking all day for delivery drivers","Overnight parking for people who live nearby","Parking only for drivers with a disabled placard"],"correct":0},{"id":"q-2b-095","fact_id":"signs-054","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You unload boxes at a yellow curb with a posted time limit. You are almost out of time and have more to carry. What do you do?","options":["Stay on, since a yellow curb has no real limit","Move your car one space along the same curb and keep loading","Finish within the posted time, then move your car","Leave the car there and go shopping"],"correct":2},{"id":"q-2b-096","fact_id":"signs-054","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"You want to unload boxes of freight at the curb. Which color suits that job?","options":["White, which allows freight as well as people","Green, which allows loading time for deliveries","Red, if you are quick about it","Yellow, which allows loading or unloading"],"correct":3},{"id":"q-2b-097","fact_id":"signs-055","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A white curb is in front of a building. What may you do there?","options":["Park for as long as you like during the day","Load freight for any length of time","Wait parked for a friend for an hour or more","Stop briefly to drop off or pick up passengers"],"correct":3},{"id":"q-2b-098","fact_id":"signs-055","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You pick up your grandmother at a white curb. She needs a minute to walk out. What do you do?","options":["Park and wait inside the building for her","Stop only for the pick-up and then drive off","Leave the car and go to find her inside","Stop and wait there until she is ready, however long it takes"],"correct":1},{"id":"q-2b-099","fact_id":"signs-055","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"White and green curbs both involve short times. Which statement is right?","options":["White allows short parking; green is only for dropping people off","Both allow parking all day on weekends and holidays","White is for passenger drop-off; green is for short parking","Both are meant for buses, taxis and shuttles only"],"correct":2},{"id":"q-2b-100","fact_id":"signs-056","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a green curb mean?","options":["Park for a short time; check the posted limit","No parking at any time of the day or night, ever","Parking for permit holders and residents only","Loading and unloading only, with no parking at all"],"correct":0},{"id":"q-2b-101","fact_id":"signs-056","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You park at a green curb for an errand. A sign shows a time limit, and your errand will run longer. What do you do?","options":["Stay, since green means free parking all day","Move the car before the limit ends, or park elsewhere","Shuffle forward one car length each hour","Leave it, since the limit applies only to other drivers"],"correct":1},{"id":"q-2b-102","fact_id":"signs-056","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Green and yellow curbs both have time limits. Which statement is right?","options":["Green allows parking; yellow allows only loading or unloading","Yellow allows parking; green allows only loading or unloading","Both allow parking for as long as the posted time","Green is for trucks only; yellow is for cars"],"correct":0},{"id":"q-2b-103","fact_id":"signs-057","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a blue curb mean?","options":["Parking for electric vehicles that are plugged in to charge","Parking for a short time, with a limit posted on a sign","Parking for drivers who have paid at the nearby meter","Parking only for a disabled person with a placard or plate"],"correct":3},{"id":"q-2b-104","fact_id":"signs-057","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see an empty blue space near the door. You have no placard and plan to be quick. What do you do?","options":["Park there for a minute, since it is only a brief stay","Park there, since the space is empty and nobody is waiting","Park elsewhere; blue spaces need a placard or plate","Park elsewhere, but in the striped aisle next to the blue space"],"correct":2},{"id":"q-2b-105","fact_id":"signs-057","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a blue curb differ from a white curb?","options":["Blue is for disabled parking; white is for brief passenger stops","White is for parking by a disabled driver; blue is for passenger stops","Both are for passenger stops, with blue used only at night","Both are for parking all day, with white for visitors"],"correct":0},{"id":"q-2b-106","fact_id":"signs-058","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"You approach a roundabout. Who goes first?","options":["The car that reaches the yield line first","Cars that are entering from your right","Larger vehicles, such as trucks and buses","Traffic that is already inside the circle"],"correct":3},{"id":"q-2b-107","fact_id":"signs-058","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a roundabout, and a car inside is circling toward your entry. What do you do?","options":["Enter first, since you are already at the line","Stop before the yield line and wait until the whole circle is empty","Slow down, yield, then enter when there is a gap","Speed up and enter ahead of the car"],"correct":2},{"id":"q-2b-108","fact_id":"signs-058","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How is entering a roundabout different from entering a four-way stop?","options":["At a roundabout you stop fully, then go in order of arrival","At a roundabout you yield and need not stop if the way is clear","At a roundabout you have the right of way over the cars inside","At a roundabout nobody has to yield, since no signs control it"],"correct":1},{"id":"q-2b-109","fact_id":"signs-059","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A sign shows a bicycle and the words BIKE LANE. What may drivers do in that lane?","options":["Drive in it to pass slow traffic in the next lane","Use it as an extra lane when traffic is heavy","Enter it only to turn or to park where allowed","Never enter it, not even to make a turn"],"correct":2},{"id":"q-2b-110","fact_id":"signs-059","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You want to turn right at the next corner, and a bike lane runs beside your lane. What do you do?","options":["Drive ahead in the bike lane past a line of slow cars","Check for riders, then enter it only to make the turn","Stay out of the bike lane until the corner, then cut across without looking","Stop in the bike lane and wait for riders to pass"],"correct":1},{"id":"q-2b-111","fact_id":"signs-059","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A bus is stopped ahead in your lane. What may you do about the bike lane beside it?","options":["Stay out of it and wait behind the bus","Use it to pass, but only if no rider is in sight","Stay out of it unless the driver behind you honks","Wait a minute, then use it if the bus has not moved"],"correct":0},{"id":"q-2b-112","fact_id":"signs-060","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A sign over a lane reads CARPOOL LANE, with a person count and hours. What does it mean?","options":["Any vehicle may use it at all, but only in the posted hours","Only buses and vans may use the lane during the posted hours","Any vehicle may use it to pass, as long as the driver signals","Only vehicles with enough people may use it in those hours"],"correct":3},{"id":"q-2b-113","fact_id":"signs-060","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive alone. The carpool sign says the rule lasts until 9 a.m., and it is now 9:30 a.m. What is true?","options":["The rule applies all day, whatever the sign says","The posted hours have ended, but you may use the lane only to pass","The rule still applies until the sign is covered or removed","The posted hours have ended, so you may use the lane"],"correct":3},{"id":"q-2b-114","fact_id":"signs-060","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does the carpool-lane sign differ from the diamond painted on that lane?","options":["The sign gives the person count and hours; the diamond marks the lane","The diamond gives the person count; the sign only marks the lane","They give the same facts, and one only repeats the other","The sign is for buses, and the diamond is for cars"],"correct":0},{"id":"q-2b-115","fact_id":"signs-061","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A triangle with a red border and an orange center is on the back of a vehicle. How fast does that vehicle travel?","options":["At 35 mph or less","At 15 mph or less","At 25 mph or less","At 45 mph or less"],"correct":2},{"id":"q-2b-116","fact_id":"signs-061","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You come up behind a farm tractor that shows an orange triangle. The road is busy. What do you do?","options":["Stay close behind and flash your lights so it pulls over","Slow down early and pass only when you have room","Slow down early and pass at the first gap, whatever the oncoming traffic","Honk until the driver moves aside"],"correct":1},{"id":"q-2b-117","fact_id":"signs-061","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A driver thinks the orange triangle means the vehicle has broken down. What does it really mean?","options":["It is stopped, and you may drive around it freely","It travels slowly as normal, so slow down and pass with care","It is an official vehicle that must be given the whole lane","It is a wide load, so keep one full lane away from it"],"correct":1},{"id":"q-2b-118","fact_id":"signs-062","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a lane line splitting into two. What does it tell you?","options":["A lane ends ahead, so you must merge now","Two roads join ahead, and cars merge from the right","A new lane begins on the right, and you may use it","The right lane is for exits only"],"correct":2},{"id":"q-2b-119","fact_id":"signs-062","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are stuck behind a slow truck, and a sign shows a new lane starting on the right ahead. What do you do?","options":["Move into the new lane when it opens, if it is safe","Stay behind the truck, since new lanes are for trucks only","Move over at once, using the shoulder before the lane starts","Speed up to pass the truck on the left before the new lane starts"],"correct":0},{"id":"q-2b-120","fact_id":"signs-062","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does an Added Lane sign differ from a Lane Ends sign?","options":["Added Lane: you must merge. Lane Ends: a lane opens for you","Both tell you to merge soon, and only the picture differs","Added Lane is for exits; Lane Ends is for turns","Added Lane: a lane opens for you. Lane Ends: you must merge"],"correct":3},{"id":"q-2b-121","fact_id":"signs-063","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What is the center lane with yellow left-turn arrows used for?","options":["Left turns from both directions of travel","Passing slow vehicles that are in the lanes beside it","Driving in the opposite direction at rush hour","Stopping for a short time to park or load"],"correct":0},{"id":"q-2b-122","fact_id":"signs-063","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"Traffic crawls in your lane, and the center lane with left-turn arrows is empty. What do you do?","options":["Use the center lane to bypass the whole line of cars","Drive in it for a short stretch, then merge back out","Stay in your lane; the center lane is for left turns","Stay in your lane and use the center lane only to pass a stopped car"],"correct":2},{"id":"q-2b-123","fact_id":"signs-063","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about a two-way left-turn lane is right?","options":["It serves one direction only, and the other side needs its own lane","Drivers from both directions share it to wait for left turns","It is for passing slow vehicles when the road ahead is clear","Only cars turning left from the nearer direction may use it at a time"],"correct":1},{"id":"q-2b-124","fact_id":"signs-064","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A bicycle symbol with two chevrons above it is painted in the middle of a traffic lane. What does it mean?","options":["The lane is for bicycles only, and cars must stay out","A separate bike lane begins on the next block","Riders must stay at the far edge of the lane","Bikes and cars share it; expect riders in the middle"],"correct":3},{"id":"q-2b-125","fact_id":"signs-064","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a cyclist riding in the middle of a lane that has sharrow markings. What do you do?","options":["Honk to make the rider move to the edge","Slow down and pass only when there is room","Slow down, then pass at once while the rider holds their line","Follow very close until the rider leaves the lane"],"correct":1},{"id":"q-2b-126","fact_id":"signs-064","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A bicycle symbol is painted in the middle of your lane, with no line along its side. Which statement is right?","options":["It is a bike lane, so cars may enter it only to turn or park","It is bike-only, so cars must find a different lane","It is a parking lane for bicycles at night","It is a shared lane, so cars may use it but must expect riders"],"correct":3},{"id":"q-2b-127","fact_id":"signs-066","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A square white sign shows a truck with a red slash. What does it tell you?","options":["Trucks must stay in the right lane here","Trucks must slow down on this stretch","Trucks may not use this road","Trucks may use this road only at night"],"correct":2},{"id":"q-2b-128","fact_id":"signs-066","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive a delivery truck, and your GPS sends you down a road with a No Trucks sign. What do you do?","options":["Take another route that trucks may use","Follow the GPS, since it knows the route best","Use the road only to reach the next junction, then turn off","Carry on, if the delivery is only a short one"],"correct":0},{"id":"q-2b-129","fact_id":"signs-066","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a No Trucks sign differ from a Do Not Enter sign?","options":["No Trucks bans trucks only; Do Not Enter bans all vehicles","No Trucks bans all vehicles; Do Not Enter bans trucks only","Both ban only trucks, one by day and one by night","No Trucks is for freeways, and Do Not Enter is for streets"],"correct":0},{"id":"q-3-001","fact_id":"p15_changes-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Only a short list of named cities may run California's speed-camera pilot. Which city is on that list?","options":["Fresno","Long Beach","Bakersfield","Riverside"],"correct":1},{"id":"q-3-002","fact_id":"p15_changes-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"The council of a mid-sized town wants speed cameras on its main street. What does the pilot law allow?","options":["Only cities named in the law may run one","A public vote lets a town run one","School zones qualify a town to run one","A town may run one once it posts warning signs"],"correct":0},{"id":"q-3-003","fact_id":"p15_changes-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A friend says any California city can run speed cameras because Los Angeles does. Which reply is accurate?","options":["Cities above 100,000 people are all covered","Every city is covered once its council votes","Cities with school zones are all covered","Only a short list of named cities is covered"],"correct":3},{"id":"q-3-004","fact_id":"s5-09","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"How far before a turn must your turn signal be on?","options":["50 feet","75 feet","100 feet","200 feet"],"correct":2},{"id":"q-3-005","fact_id":"s5-09","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are about 150 feet from your right turn with a car close behind you. Your signal is off. What do you do?","options":["Turn the signal on now and keep it on","Wait until 50 feet out, then flash it once","Skip it, since your brake lights will show","Give a hand signal when you reach the corner"],"correct":0},{"id":"q-3-006","fact_id":"s5-09","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which pair matches the signal rules for a corner turn and for a freeway lane change?","options":["10 feet before the turn; 1 second before the lane change","100 feet before the turn; 5 seconds before the lane change","5 seconds before the turn; 100 feet before the lane change","200 feet before the turn; 10 seconds before the lane change"],"correct":1},{"id":"q-3-007","fact_id":"s5-10","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What is the minimum time your signal should blink before a freeway lane change?","options":["3 seconds","5 seconds","2 seconds","4 seconds"],"correct":1},{"id":"q-3-008","fact_id":"s5-10","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are in the right lane of a freeway and want to move left to pass a truck. Traffic is light. When should your signal start?","options":["Once your car begins to move over","The moment your wheels touch the line","About five seconds before you move over","Only when a car sits in the next lane"],"correct":2},{"id":"q-3-009","fact_id":"s5-10","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about signaling lane changes is right?","options":["Signal before every lane change, and longer at freeway speed","Signal only for freeway lane changes, not on city streets","Signal for lane changes only when a vehicle is beside you","Signal for 5 seconds on every road, whatever the speed"],"correct":0},{"id":"q-3-010","fact_id":"s5-11","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"Which signaling habit is the safe one?","options":["Signal only when another car is in view","Signal at night, when lights stand out","Signal only at a corner with a stop sign","Signal every time, even if no one is in view"],"correct":3},{"id":"q-3-011","fact_id":"s5-11","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"It is 6 a.m. on a quiet street. You see no car, bike or walker as you start a left turn. What do you do with your signal?","options":["Skip it, since nobody is around to see it","Blink it once, then turn it off at the corner","Use it only if your headlights are on","Use it anyway, since someone may be out of sight"],"correct":3},{"id":"q-3-012","fact_id":"s5-11","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Dana signals every turn. Eli signals only when he sees another car. Who has the safer habit, and why?","options":["Dana, because unseen road users may rely on the signal","Eli, because a signal confuses drivers who are not involved","Both, since signaling is a personal choice","Eli, because a signal needs an audience to matter"],"correct":0},{"id":"q-3-013","fact_id":"s6-19","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a yield line look like on the road?","options":["A solid white bar across the lane","A dashed yellow stripe down the center","A row of solid white triangles across the lane","A pair of yellow stripes along the curb"],"correct":2},{"id":"q-3-014","fact_id":"s6-19","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Approaching a crosswalk, you see a row of solid white triangles across your lane. Where should you be ready to stop or yield?","options":["Past the triangles, in the crosswalk","On top of the triangles, nose over them","Beside the triangles, in the next lane","Behind the triangles, before the crosswalk"],"correct":3},{"id":"q-3-015","fact_id":"s6-19","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which marking is a yield line rather than a crosswalk or a stop line?","options":["Solid white triangles across the lane","Wide white bars running with the traffic","A single solid white bar across the lane","Yellow triangles along the lane edge"],"correct":0},{"id":"q-3-016","fact_id":"s6-20","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How far may you drive in a center left-turn lane while preparing for and making a left turn?","options":["50 feet","100 feet","500 feet","200 feet"],"correct":3},{"id":"q-3-017","fact_id":"s6-20","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"On a four-lane road with a center turn lane, you want to turn left into a shop 600 feet ahead. When may you enter the center lane?","options":["Now, and drive the whole 600 feet in it","Within the last 200 feet before the shop","Whenever you like, if you signal first","Use it to pass slower cars, then turn at the shop"],"correct":1},{"id":"q-3-018","fact_id":"s6-20","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which describes proper use of a center left-turn lane?","options":["Enter only to prepare for or make a left turn, briefly","Enter to pass slow traffic, then pull back when clear","Enter to speed up before joining the flow of traffic","Enter for any reason, as long as you stay under 200 feet"],"correct":0},{"id":"q-3-019","fact_id":"s6_p11_roadway-011","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A school bus has stopped with its red lights flashing. In which case do you not have to stop?","options":["A two-lane road with parked cars along it","The lane right behind the bus, going its way","A divided highway, with the bus on the far roadway","A one-way street, with the bus in the next lane"],"correct":2},{"id":"q-3-020","fact_id":"s6_p11_roadway-011","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are driving east on a divided highway with a wide median. Across the median, a school bus has stopped with red lights flashing. What do you do?","options":["Stop and wait until the bus lights go off","Keep going at a safe speed, watching for kids","Slow to a crawl until you are past the bus","Pull onto the shoulder until the children cross"],"correct":1},{"id":"q-3-021","fact_id":"s6_p11_roadway-011","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A school bus has red lights flashing on the other side of the road. In which case must you still stop?","options":["The bus is on the far roadway of a divided highway","The road has a wide median and two lanes each way","The road has one lane each way and no median","The bus is at least 200 feet away on a wide highway"],"correct":2},{"id":"q-3-022","fact_id":"s6_p11_run2-001","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a school bus stop arm do?","options":["It makes traffic stop while children board or leave","It shows the bus will pull away from the stop soon","It signals that the bus is turning right shortly","It shows the bus is out of service for the day"],"correct":0},{"id":"q-3-023","fact_id":"s6_p11_run2-001","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are stopped behind a school bus whose stop arm is out. A child steps off the curb to cross. When may you drive on?","options":["When the arm is out but the road looks empty","As soon as the first child is across","When the bus driver waves, arm still out","When the arm folds in and the children are clear"],"correct":3},{"id":"q-3-024","fact_id":"s6_p11_run2-001","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A stop arm is out on a bus ahead. A school-zone sign ahead has yellow lights flashing. Which pair is right?","options":["Stop arm: slow down; school-zone yellow: stop and wait until it ends","Stop arm: stop and stay stopped; school-zone yellow: slow, be ready to stop","Both: stop and stay stopped until the lights and arm go off","Both: slow down, then keep moving if no child shows up on the road"],"correct":1},{"id":"q-3-025","fact_id":"s6_p11_run2-002","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What may you do in a school loading zone?","options":["Park for a short visit to the school office","Stand while you wait for a friend to finish a call","Stop just long enough to load or unload passengers","Park if you leave the engine running"],"correct":2},{"id":"q-3-026","fact_id":"s6_p11_run2-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You arrive early to pick up your sister. The curb by the school entrance is a loading zone and no other spot is free. What do you do?","options":["Pull in only long enough for her to get in","Park and walk to the gate to look for her","Wait there with your hazard lights flashing","Leave the car there for a few minutes"],"correct":0},{"id":"q-3-027","fact_id":"s6_p11_run2-002","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement separates stopping from parking at a school loading zone?","options":["Parking is allowed there, but stopping is not","Stopping to load is allowed there; parking is not","Both are allowed there for up to five minutes","Neither is allowed there except for school buses"],"correct":1},{"id":"q-3-028","fact_id":"s6_p11_run2-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which driver habit fits a school zone with children on the sidewalk?","options":["Drive on, since children wait for a gap in traffic","Be ready to yield, since a child may step out","Honk early, so children know a car is coming","Speed up to clear the area before they step out"],"correct":1},{"id":"q-3-029","fact_id":"s6_p11_run2-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"At 3 p.m. near an elementary school you approach a marked crosswalk with a green light. Children on the curb look ready to cross. What do you do?","options":["Keep going, since your light is green","Tap the horn and keep rolling slowly","Stop and let them cross before you go","Edge forward to hurry them along"],"correct":2},{"id":"q-3-030","fact_id":"s6_p11_run2-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How does a school zone differ from any other crosswalk for drivers?","options":["Yield at ordinary crosswalks only; in school zones go first","Yield in school zones only when lights flash","Yield to adults only; children must wait","Yield everywhere; in school zones add extra time"],"correct":3},{"id":"q-3-031","fact_id":"s6_p11_run2-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Where must drivers yield to pedestrians around a school?","options":["In marked crosswalks and nowhere else","On the street in front of the gate","Also in parking lots and drop-off areas","Where a crossing guard is on duty"],"correct":2},{"id":"q-3-032","fact_id":"s6_p11_run2-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You circle the school parking lot to find a space. Children walk between parked cars toward the building. What do you do?","options":["Yield to the children and creep along","Hold your lane, since the lot has no crosswalks","Honk to clear a path","Pass the car ahead to reach a space first"],"correct":0},{"id":"q-3-033","fact_id":"s6_p11_run2-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about walkers at a crosswalk and a school drop-off zone is right?","options":["Walkers go first at the crosswalk, but cars go first in drop-off zones","Walkers go first at the crosswalk and around the school's lots and drop-offs","Walkers go first only at corners that have traffic signals or stop signs","Walkers go first only in the morning, before the first bell rings"],"correct":1},{"id":"q-3-034","fact_id":"s6_p11_run2-005","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What can the line of a bike lane look like?","options":["Yellow, and solid in all places","White, always solid","White, dashed throughout","White, solid or dashed by location"],"correct":3},{"id":"q-3-035","fact_id":"s6_p11_run2-005","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You want to turn right across a bike lane. The line beside it is dashed and a cyclist rides in the lane. What do you do?","options":["Turn first, since cars have priority here","Honk to tell the rider to stop and wait","Check for cyclists and let the rider by","Cross the line first, then slow down"],"correct":2},{"id":"q-3-036","fact_id":"s6_p11_run2-005","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about crossing a bike lane line is right?","options":["Check for cyclists first, whatever the line type","Cyclists have already seen you, so you may cross","A cyclist must yield to a car that is turning","A rider beside a solid line is breaking the law"],"correct":0},{"id":"q-3-037","fact_id":"s6_p11_run3-015","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A school bus driver walks pupils across the road holding a hand-held STOP sign. Which pupils must the driver escort?","options":["Only pupils in kindergarten","Pupils in grades 6 to 8 only","Pupils through grade 8 who cross","Pupils through grade 12 who cross"],"correct":2},{"id":"q-3-038","fact_id":"s6_p11_run3-015","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A school bus ahead is stopped and its driver steps out holding a STOP sign, walking three small children across the road. What do you do?","options":["Drive around the bus on the left side","Inch forward once the first child is across","Honk once to warn the group","Stay stopped until the children are clear"],"correct":3},{"id":"q-3-039","fact_id":"s6_p11_run3-015","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a school bus stop, who holds the hand-held STOP sign while pupils cross, and what must you do?","options":["A bus driver; you stop and stay put until they clear","A crossing guard; you slow down and pass with care","A police officer; you stop only if he tells you to","A parent at the curb; you wait only if she asks you"],"correct":0},{"id":"q-3-040","fact_id":"s7_p11_roadway-001","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What do flashing yellow lights at a school zone mean?","options":["Stop and wait until they go off","Children are crossing, so go around them","Slow down and be ready to stop for children","The school zone limit has ended"],"correct":2},{"id":"q-3-041","fact_id":"s7_p11_roadway-001","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"Yellow lights start flashing on a school-zone post as you approach, and children stand on the sidewalk ahead. What do you do?","options":["Hold your speed, since the lights are only a warning","Ease off and cover your brake, ready to stop","Stop where you are until the lights go off","Speed up to leave the zone before children cross"],"correct":1},{"id":"q-3-042","fact_id":"s7_p11_roadway-001","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which two lights ask for the same response: slow down and be ready to stop?","options":["School-zone yellow flashers and a bus's yellow flashers","School-zone yellow flashers and a bus's red flashers","A bus's yellow flashers and a bus's red flashers","A bus's red flashers and its extended stop arm"],"correct":0},{"id":"q-3-043","fact_id":"s7_p11_roadway-002","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A school bus on an undivided road has its red lights flashing. Who must stop?","options":["Cars behind the bus, but not oncoming cars","Cars from both directions, behind and ahead","Cars facing the bus, but not those behind it","Cars in the bus's own lane, but no others"],"correct":1},{"id":"q-3-044","fact_id":"s7_p11_roadway-002","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are driving toward a school bus on a two-lane street. It stops and red lights begin flashing when you are 200 feet away. What do you do?","options":["Pass quickly before the children cross the street","Pass on the shoulder at walking pace, with care","Stop only if you actually see children by the bus","Stop before the bus and stay until the lights go off"],"correct":3},{"id":"q-3-045","fact_id":"s7_p11_roadway-002","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A bus ahead on a two-lane road shows red flashing lights. An oncoming car drives past it. Which statement is right?","options":["The oncoming driver broke the rule, since both directions must stop","The oncoming driver is fine, since only following traffic must stop","The oncoming driver is fine if the bus is across the center line","The oncoming driver is fine if no child is in sight"],"correct":0},{"id":"q-3-046","fact_id":"s7_p11_roadway-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the speed limit when you pass a school with a posted SCHOOL sign while children are going to or leaving it?","options":["20 mph","30 mph","35 mph","25 mph"],"correct":3},{"id":"q-3-047","fact_id":"s7_p11_roadway-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"It is 8 a.m. on a school day. You pass a school marked with a SCHOOL sign on a street usually driven at 35. Children are walking in. How fast may you go?","options":["25 mph","30 mph","35 mph","As fast as traffic flows"],"correct":0},{"id":"q-3-048","fact_id":"s7_p11_roadway-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"When does the 25 mph limit at a school with a SCHOOL sign apply?","options":["At every hour of the day, whether or not children are around","While children arrive or leave, during school hours or noon recess","Only on days when the school holds a special event, such as a game","Only while the yellow lights on the school sign are flashing at you"],"correct":1},{"id":"q-3-049","fact_id":"s7_p11_roadway-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How low can the limit in a posted school zone go?","options":["5 mph","10 mph","15 mph","20 mph"],"correct":2},{"id":"q-3-050","fact_id":"s7_p11_roadway-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A sign reads 15 mph for the school zone while children are present. The street's normal limit is 25. You are at 25 as kids line up at the crosswalk. What now?","options":["Stay at 25, since that is the street limit","Slow to 15, the posted school limit","Slow to 20, halfway between the two","Slow to 5, since children are present"],"correct":1},{"id":"q-3-051","fact_id":"s7_p11_roadway-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about school-zone speed limits is right?","options":["Every school zone is set at exactly 25 mph","Every school zone is set at exactly 15 mph","No school zone is ever posted below 20 mph","Most are 25 mph, though some are posted at 15"],"correct":3},{"id":"q-3-052","fact_id":"s7_p11_run2-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How should a driver treat a crossing guard's directions near a school?","options":["Follow them every time, whatever else you see","Follow them only when a police officer is near","Follow them only if no traffic light is working","Follow them only when children are in the road"],"correct":0},{"id":"q-3-053","fact_id":"s7_p11_run2-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You have a green light near a school when a crossing guard steps into the road and holds up a hand to stop traffic. What do you do?","options":["Go, because the green light has priority","Slow and go around the guard on the left","Honk twice so the guard steps aside quickly","Stop for the guard, even with a green light"],"correct":3},{"id":"q-3-054","fact_id":"s7_p11_run2-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a school crossing a parent waves you through while the crossing guard holds up a stop sign. Whom do you follow?","options":["The parent, since a wave means go","Neither; the green light decides","The guard, who is trained for the job","The car ahead, since it is in line"],"correct":2},{"id":"q-3-055","fact_id":"s7_p11_run2-003","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What do yellow flashing lights on a school bus warn?","options":["The bus has stopped and children are crossing","The bus will stop soon to let children off","The bus has broken down on the road","The driver is inviting you to pass"],"correct":1},{"id":"q-3-056","fact_id":"s7_p11_run2-003","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A school bus ahead on your road starts flashing yellow lights as it nears a stop. You are following it. What do you do?","options":["Slow down and get ready to stop","Pass now before the red lights start","Speed up to close the gap","Pull to the shoulder and wait"],"correct":0},{"id":"q-3-057","fact_id":"s7_p11_run2-003","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Bus A ahead flashes yellow lights. Bus B on the other side of a two-lane road shows red lights and a stop arm. Which is right?","options":["Stop for A and slow for B","Slow for both","Stop for both","Slow for A and stop for B"],"correct":3},{"id":"q-3-058","fact_id":"s7_p11_run2-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"After leaving a stopped school bus, where do children who must cross the road walk?","options":["Behind the bus, out of the traffic lane","At the side of the bus, next to the traffic","In front of the bus, in the driver's view","Anywhere they find a gap between cars"],"correct":2},{"id":"q-3-059","fact_id":"s7_p11_run2-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You stop for a school bus with red lights. A girl steps off and starts across the road. Where will she walk, and what do you do?","options":["Behind the bus; you may move once she clears the doorway","In front of the bus; you stay stopped until she is clear","In front of the bus; you may pass once she reaches the middle","Behind the bus; you stay stopped until the bus moves"],"correct":1},{"id":"q-3-060","fact_id":"s7_p11_run2-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a stopped bus, a driver scans the road behind the bus for crossing children. What is wrong with that habit?","options":["Children cross in front of the bus, so the scan is misplaced","Children cross only at the next corner, away from the bus","Nothing; the rear is the usual place for children to cross","Children never cross unless the stop arm is also extended"],"correct":0},{"id":"q-3-061","fact_id":"s7_p11_run2-005","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which is the best expectation near a school bus stop in the morning?","options":["Children will wait quietly at the curb until the bus arrives","Most children keep to the crosswalks on their way to the stop","Children check for cars before they step into the road","Children may walk to or from the stop without watching for cars"],"correct":3},{"id":"q-3-062","fact_id":"s7_p11_run2-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"At 7:30 a.m. you pass a corner where children with backpacks stand by a school bus sign. A boy runs toward the corner. What do you do?","options":["Slow down and cover the brake","Hold your speed since the bus isn't there","Honk so he looks up","Speed up to pass before he reaches the curb"],"correct":0},{"id":"q-3-063","fact_id":"s7_p11_run2-005","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A driver says extra care is needed only inside a signed school zone. What is missing from that view?","options":["Nothing is missing, since bus stops lie outside the school's area","Children at a bus stop are still too far from the road","Children walking to and from stops need extra attention too","Only the buses themselves need extra care near the stop"],"correct":2},{"id":"q-3-064","fact_id":"s7_p11_run2-006","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Near a school, which road users should a driver expect?","options":["Cars and buses only, since children use sidewalks","Cars, buses, walkers and cyclists sharing the space","Walkers only, since bikes use other routes","Cars and cyclists only, since walkers stay on sidewalks"],"correct":1},{"id":"q-3-065","fact_id":"s7_p11_run2-006","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You pass a school as a student on a bike wobbles near the lane line beside you. What do you do?","options":["Honk and pass close to get by","Speed up to clear the area","Stay close behind so he sees you","Slow down and leave extra space"],"correct":3},{"id":"q-3-066","fact_id":"s7_p11_run2-006","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A student on a bike enters a school zone. Which statement is right?","options":["The rider should slow near walkers, and you give extra room","The rider should hurry past walkers, and you stay close behind","The rider should use the sidewalk, and you can ignore the lane","The rider should ring a bell, and you may pass without slowing"],"correct":0},{"id":"q-3-067","fact_id":"s7_p11_run2-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which pedestrians need extra crossing time in a school zone?","options":["Runners and other fast walkers","People carrying heavy bags or books","Children and older adults crossing","Groups of three or more at once"],"correct":2},{"id":"q-3-068","fact_id":"s7_p11_run2-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"An older man with a cane is halfway across a school-zone crosswalk as your light turns green. What do you do?","options":["Wait until he is fully across","Edge forward to nudge him along","Go around behind him","Flash your lights to hurry him"],"correct":0},{"id":"q-3-069","fact_id":"s7_p11_run2-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A driver says walkers must cross within one green phase. What does the school zone rule add?","options":["Nothing; walkers must keep up with the light","Walkers may step out anywhere and cars must stop","Walkers get ten seconds, then drivers may go","Children and slow walkers get extra time to cross"],"correct":3},{"id":"q-3-070","fact_id":"s7_p11_run2-008","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A child near the curb of a school street may step out. Which action fits school-zone driving?","options":["Honk to warn the child away","Swerve toward the other lane","Slow down early and stay calm","Flash your high beams repeatedly"],"correct":2},{"id":"q-3-071","fact_id":"s7_p11_run2-008","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A child ahead drifts toward the curb edge on a school street while you drive slowly. What do you do?","options":["Honk to make her look up at your car","Swerve into the next lane to keep clear","Flash your lights as a warning to her","Stay calm and brake smoothly if needed"],"correct":3},{"id":"q-3-072","fact_id":"s7_p11_run2-008","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Two drivers see a child near the curb. Mia honks and swerves wide. Noah slows early and stays smooth. Who drives correctly?","options":["Noah, since sudden moves can scare a child","Mia, since honking warns the child in time","Mia, since swerving gives the child space","Both, since either way avoids the child"],"correct":0},{"id":"q-3-073","fact_id":"s7_p11_run2-009","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How should your driving change in a school zone with children present?","options":["Keep your usual following gap, since the limit is lower","Slow down early and leave extra room to stop","Keep up with traffic to avoid sudden braking","Brake only once a child is in the road"],"correct":1},{"id":"q-3-074","fact_id":"s7_p11_run2-009","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At 3:10 p.m. you follow a minivan along a street beside a school yard. How big should the gap behind the van be?","options":["A short one, so you can pass when a spot opens","The same as on a highway","Longer than usual, so you can stop for a child","No gap rule applies at low speed"],"correct":2},{"id":"q-3-075","fact_id":"s7_p11_run2-009","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which is the better reason to slow down early in a school zone?","options":["Police watch school zones, so tickets are likelier","Tires grip less near schools, so stopping takes longer","Lower limits stop cars by themselves, so no room is needed","Children can appear at once, so you need room to stop"],"correct":3},{"id":"q-3-076","fact_id":"s7_p11_run2-010","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Parents are expected to teach children safe walking and biking. What does that mean for you as a driver?","options":["You can relax near schools, since children are trained","You need to watch only the youngest children","You have no duty if a child breaks a rule","You still watch every child near a school"],"correct":3},{"id":"q-3-077","fact_id":"s7_p11_run2-010","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A mother tells her son to look both ways. As you near the crosswalk by the school, he runs toward the curb ahead of her. What do you do?","options":["Slow down and be ready to stop anyway","Keep your speed, since he was told to look","Honk so his mother has time to grab him","Pass quickly, before he has time to step out"],"correct":0},{"id":"q-3-078","fact_id":"s7_p11_run2-010","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Who is responsible for safety around a school?","options":["Parents, since they teach the children","The school, since it posts signs and guards","Parents teach, but drivers watch for every child","Drivers alone, since parents cannot be everywhere"],"correct":2},{"id":"q-3-079","fact_id":"s7_p11_run2-011","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A ball rolls into the street near a school. What should you expect?","options":["A child may run after it","Only the ball is a hazard","Nothing more, once the ball stops","Other cars will stop for the ball"],"correct":0},{"id":"q-3-080","fact_id":"s7_p11_run2-011","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You pass a playground fence at 20 mph when a red ball bounces into the road ahead. What do you do?","options":["Steer around the ball and keep your speed","Brake and stop, expecting a child to follow","Honk so the child stays back","Flash your headlights and keep rolling"],"correct":1},{"id":"q-3-081","fact_id":"s7_p11_run2-011","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver sees a ball roll into the road, sees no child, and drives on. What is wrong with that?","options":["The driver should have steered around the ball","The driver should have honked to clear the road","The driver should slow only once a child is seen","The driver should have stopped, expecting a child"],"correct":3},{"id":"q-3-082","fact_id":"s7_p11_run2-012","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When is a school zone typically active?","options":["When the morning bell rings and doors open","When school buses are loading or unloading","At arrival and dismissal times and at school events","Only when yellow lights are flashing near the gate"],"correct":2},{"id":"q-3-083","fact_id":"s7_p11_run2-012","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"School ends at 3:00 and it is 2:55. The lot is full of parents, and no yellow lights are flashing. How do you drive?","options":["Normally, since the lights are off","Fast, to beat the dismissal rush","Normally, since the school day is over","Slowly, expecting children and parents"],"correct":3},{"id":"q-3-084","fact_id":"s7_p11_run2-012","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which time is a school zone most likely to be busy, even with no lights flashing?","options":["Tuesday at 11:30 p.m., when the building is dark","A weekday at 3:00 p.m., when school lets out","Sunday at 4 a.m., when the street is empty","Wednesday at 2 a.m., when the lot is locked"],"correct":1},{"id":"q-3-085","fact_id":"s7_p11_run2-013","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A walker is crossing at a marked crosswalk in a school zone. What do you do?","options":["Slow and go if the walker is far from your lane","Stop completely and wait until the walker has cleared","Stop only if the walker is a child","Wave the walker on and go as soon as you pass your lane"],"correct":1},{"id":"q-3-086","fact_id":"s7_p11_run2-013","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You wait at a school crosswalk. A girl has crossed your lane but is still in the crosswalk. The driver behind you honks. What do you do?","options":["Keep waiting until she is clear of the crosswalk","Go now, since she has already passed your lane","Creep forward slowly behind her to ease the line","Go around on the left to clear the crosswalk"],"correct":0},{"id":"q-3-087","fact_id":"s7_p11_run2-013","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"How is a school-zone crosswalk different from any marked crosswalk?","options":["Only school crosswalks require drivers to yield to walkers","Neither requires yielding when no child is in sight","School crosswalks allow a rolling stop at low speed","Both require yielding; school zones add a full stop"],"correct":3},{"id":"q-3-088","fact_id":"s7_p11_run2-014","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"How are school-zone violations treated compared with the same violation on an ordinary street?","options":["The same, since the law has one scale","Smaller, since schools are quiet areas","They can cost more","Treated as parking violations only"],"correct":2},{"id":"q-3-089","fact_id":"s7_p11_run2-014","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"A friend says a ticket costs the same anywhere. What should you tell him about school zones?","options":["Violations can cost more there, so obey every sign","Fines are lower at schools, since speeds are low","A ticket applies only when children are in sight","Signs there are advice and carry no penalty"],"correct":0},{"id":"q-3-090","fact_id":"s7_p11_run2-014","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Which statement about school-zone signs is right?","options":["Crossing guards are the only ones who enforce them","Violations there can cost more than elsewhere","They apply only when children are in sight","They carry smaller fines than other road signs"],"correct":1},{"id":"q-3-091","fact_id":"s7_p11_run3-006","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When do some school buses turn on yellow flashing lights?","options":["Right after the children are all off","As they leave the school lot empty","When the road has no shoulder","Before they stop to let children off"],"correct":3},{"id":"q-3-092","fact_id":"s7_p11_run3-006","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A bus ahead of you starts flashing yellow lights. What may happen next, and what do you do?","options":["It will turn, so stay close behind and follow it","It will speed up, so pull alongside to pass it","It will stop for children, so slow down and be ready","It is out of service, so pass it when the road is clear"],"correct":2},{"id":"q-3-093","fact_id":"s7_p11_run3-006","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A driver treats a bus's yellow flashers as a turn signal and passes. Where is the mistake?","options":["The lights warn of a coming stop, not a turn","There is no mistake; buses use yellow to show turns","The lights mean the bus is out of service","The lights mean the bus is stopped and loading"],"correct":0},{"id":"q-3-094","fact_id":"s7_p11_run3-008","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When does a school bus driver use the red flashing lights?","options":["Whenever the bus is moving slowly along its route","Whenever the bus stops to load or unload pupils","Only when the bus is parked in the school lot","Only on narrow roads where cars cannot pass it"],"correct":1},{"id":"q-3-095","fact_id":"s7_p11_run3-008","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A bus ahead pulls to the curb and its red lights begin flashing. No children are visible yet. What do you do?","options":["Pass slowly, since no child is in sight yet","Slow down and pass on its left side","Stop only after you see a child step out","Stop, since children are boarding or leaving"],"correct":3},{"id":"q-3-096","fact_id":"s7_p11_run3-008","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A friend thinks red lights on a bus are an early warning, so he keeps going until the bus stops. Which statement is right?","options":["Red lights show the bus is already stopped for pupils, so you stop too","Red lights are the early warning; you may keep going until the bus stops","Red lights show a bus out of service, so you may pass","Red lights show the bus is about to turn, so you wait for it"],"correct":0},{"id":"q-3-097","fact_id":"s7_p11_run3-009","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Why are children taught to cross in front of a stopped school bus?","options":["So the bus driver can see them","So they stay clear of the exhaust","So they cross faster","So cars behind the bus can see them"],"correct":0},{"id":"q-3-098","fact_id":"s7_p11_run3-009","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are stopped behind a bus with red lights. You cannot see the front of the bus. What should you assume?","options":["Children are walking behind the bus toward you","No one will cross, since the bus is loading","Children may cross in front of the bus, out of view","The children will wait for the lights to go off"],"correct":2},{"id":"q-3-099","fact_id":"s7_p11_run3-009","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about children crossing at a stopped bus is right?","options":["They cross behind it, where cars can see them","They cross in front, where the driver can see them","They cross beside it, between the bus and traffic","They cross wherever the bus driver points"],"correct":1},{"id":"q-3-100","fact_id":"s7_p11_run3-010","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A school zone posts a limit lower than the street's normal one. Which limit do you follow?","options":["The street's normal limit, because it was set first","The average of the normal and school-zone limits","The lower posted limit while children are present","Whichever lets you keep up with the traffic around"],"correct":2},{"id":"q-3-101","fact_id":"s7_p11_run3-010","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A sign reads 15 mph when children are present. A group of children is on the field by the road. How fast do you go?","options":["15 mph","25 mph","35 mph","Whatever the car ahead does"],"correct":0},{"id":"q-3-102","fact_id":"s7_p11_run3-010","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"On a street marked 25 mph, a school sign adds a 15 mph limit. How does the 15 mph limit differ?","options":["It applies at all hours","It lets you ignore the 25 mph sign","It applies when children are present","It is advice only"],"correct":2},{"id":"q-3-103","fact_id":"s7_p11_run3-011","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How near a school does the 25 mph limit begin while children are crossing?","options":["100 feet","500 feet","1,000 feet","One mile"],"correct":1},{"id":"q-3-104","fact_id":"s7_p11_run3-011","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Children are crossing at a school and you are 400 feet away on a street normally posted at 35. What is the top speed you may drive?","options":["35 mph","30 mph","45 mph","25 mph"],"correct":3},{"id":"q-3-105","fact_id":"s7_p11_run3-011","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"You are 700 feet from a school with children crossing at its gate. Which statement is right?","options":["The 25 mph limit starts only 500 feet from the school","The 25 mph limit already applies at this spot","The limit applies only inside the school grounds","The limit applies only in the school parking lot"],"correct":0},{"id":"q-3-106","fact_id":"signs-065","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A pentagon-shaped sign in fluorescent yellow-green shows two children. What does it tell you?","options":["A railroad crossing is ahead, so slow for the tracks","Pedestrians cross here, so cars must always stop","A school is near, so slow down and watch for children","No parking is allowed near here, so keep moving"],"correct":2},{"id":"q-3-107","fact_id":"signs-065","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"As you drive, a fluorescent yellow-green pentagon sign with two children comes into view. What do you do?","options":["Keep your speed, since nobody is crossing yet","Slow down and watch for children","Stop and wait until the road is clear","Speed up to leave the area quickly"],"correct":1},{"id":"q-3-108","fact_id":"signs-065","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which sign marks a school area, as opposed to a general warning?","options":["A plain yellow diamond with a black symbol","A red octagon with white block letters","A white rectangle with black words and numbers","A yellow-green pentagon with a black symbol"],"correct":3},{"id":"q-4-001","fact_id":"glossary-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Under California law, who counts as a pedestrian when you drive?","options":["A person on foot, or a person using a wheelchair for personal transport","Only a person on foot who is walking inside a marked crosswalk","A person on foot, but not a person using a wheelchair or similar device","A person on foot or a person riding a bicycle along the road"],"correct":0},{"id":"q-4-002","fact_id":"glossary-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait to turn right on green. A man in a motorized wheelchair starts across the street ahead of you. What do you do?","options":["Pass in front of him quickly, ahead of his path","Stay stopped and let him finish crossing in front of you","Wait only until he is past your bumper, then turn behind him","Treat him as a vehicle and take turns at the crossing"],"correct":1},{"id":"q-4-003","fact_id":"glossary-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about a person who uses a wheelchair to get around town is right?","options":["The person is a vehicle driver, so right-of-way goes to whoever arrives first","The person is a pedestrian only when the wheelchair has no motor attached","The person is a pedestrian, so drivers yield as they would to anyone on foot","The person is a pedestrian only on a sidewalk and never on the roadway"],"correct":2},{"id":"q-4-004","fact_id":"glossary-005","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does the term right-of-way settle on the road?","options":["Which road user is to blame when a crash occurs","Which road user goes first and which one must yield","Which lane a road user must pick on a multi-lane street","Which road user may travel faster through a shared space"],"correct":1},{"id":"q-4-005","fact_id":"glossary-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You have a green light. A car on the cross street keeps rolling toward the intersection without slowing. What fits the right-of-way rule?","options":["Hold your speed and trust the light to protect you","Ease off and cover the brake for the other car","Speed up and honk to warn the other driver off","Stop in the intersection and wave the other car through"],"correct":1},{"id":"q-4-006","fact_id":"glossary-005","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of terms is matched correctly?","options":["Yielding is the priority; right-of-way is giving way to it","Right-of-way is the priority; yielding is giving way to it","Right-of-way and yielding both mean going first","Right-of-way covers vehicles; yielding covers pedestrians"],"correct":1},{"id":"q-4-007","fact_id":"glossary-008","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which group does the term vulnerable road users name?","options":["Children and older adults who are crossing a street","People who walk, cycle, or use a wheelchair or similar device","Drivers of older cars that lack modern safety features","People who ride motorcycles, scooters or other engine vehicles"],"correct":1},{"id":"q-4-008","fact_id":"glossary-008","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive past a bus stop where people wait and a cyclist rides near the curb. What is the best approach?","options":["Keep your speed and expect them to stay out of your way","Sound your horn as you pass so everyone knows you are there","Slow down and leave extra room and time around them","Pass them quickly so that you are beyond them sooner"],"correct":2},{"id":"q-4-009","fact_id":"glossary-008","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A person walking and a person cycling both share the road with you. Which statement is right?","options":["Only the person walking is vulnerable; a cyclist is protected like a driver","Both are pedestrians, so both follow the same crosswalk rules","Neither is vulnerable once they use a marked lane or crosswalk","Both are vulnerable road users, but only the person walking is a pedestrian"],"correct":3},{"id":"q-4-010","fact_id":"glossary-009","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does it mean to yield?","options":["Slow down, stop if needed, and let others go first","Stop completely every time, even when the way is clear","Speed up to clear the spot before others arrive","Pull onto the shoulder and wait until the road is empty"],"correct":0},{"id":"q-4-011","fact_id":"glossary-009","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You reach a yield sign where a side road joins yours. A car on the side road is close and coming fast. What do you do?","options":["Stop for three seconds as at a stop sign, then pull out","Hold your speed and merge, because the sign is yours to use","Swing to the far lane quickly to avoid slowing down","Slow down, stop if you must, and go once that car has passed"],"correct":3},{"id":"q-4-012","fact_id":"glossary-009","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How does yielding differ from stopping at a stop sign?","options":["Yield: always a full stop. Stop sign: a rolling pass is fine","Yield and stop sign: both need a full stop, one lasting longer","Yield: stop only if needed. Stop sign: always a full stop","Both signs only ask you to slow down; neither needs a full stop"],"correct":2},{"id":"q-4-013","fact_id":"s6-21","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which painted marking is used on a freeway lane reserved for vehicles with several occupants?","options":["A large arrow symbol with the word Express","A diamond symbol with the words Carpool Lane","A bicycle symbol with the words Shared Lane","A letter P symbol with the words Priority Lane"],"correct":1},{"id":"q-4-014","fact_id":"s6-21","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"On the freeway you see a diamond painted in the far left lane, with the words Carpool Lane. You are driving alone. What do you do?","options":["Read the signs for the occupancy minimum before you enter","Use the lane only if you are about to leave the freeway","Stay out unless you are towing a trailer or a heavy load","Use the lane freely once you are above a set speed"],"correct":0},{"id":"q-4-015","fact_id":"s6-21","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of painted markings is matched correctly?","options":["Diamond: bike lane. Bicycle symbol: carpool lane","Diamond: turn lane. Bicycle symbol: bus lane","Diamond and bicycle symbol: open to every vehicle","Diamond: carpool lane. Bicycle symbol: bike lane"],"correct":3},{"id":"q-4-016","fact_id":"s6-25","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How close to a railroad crossing is a U-turn banned?","options":["Within 50 feet","Within 100 feet","Within 200 feet","Within 15 feet"],"correct":1},{"id":"q-4-017","fact_id":"s6-25","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You realize you are heading the wrong way. A railroad crossing lies 80 feet ahead on your road. What should you do?","options":["Drive on; make the turn farther than 100 feet from the tracks","Cross the tracks, then turn around right after them","Stop and wait for a gap in traffic, then turn there","Make the turn right now; the ban covers only the rails themselves"],"correct":0},{"id":"q-4-018","fact_id":"s6-25","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of rail-crossing distances is right?","options":["No U-turn within 15 feet of a crossing; stop at least 100 feet from the rail","No U-turn within 400 feet of a crossing; stop at least 15 feet from the rail","No U-turn within 100 feet of a crossing; stop at least 100 feet from the rail","No U-turn within 100 feet of a crossing; stop at least 15 feet from the rail"],"correct":3},{"id":"q-4-019","fact_id":"s6-26","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Where may you make a U-turn in a business district?","options":["Anywhere that has no No U-turn sign posted","In mid-block, after checking that no traffic is coming","In mid-block, on a street with several lanes each way","At an intersection, not in the middle of the block"],"correct":3},{"id":"q-4-020","fact_id":"s6-26","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are on a downtown street lined with shops and want to head back the other way. The next intersection is two blocks ahead. What is the legal move?","options":["Turn around where you are now, since the street is empty","Slow down and turn around at the next mid-block crosswalk","Use the center turn lane to loop back the other way","Drive to the intersection and make the turn there"],"correct":3},{"id":"q-4-021","fact_id":"s6-26","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of U-turn rules is right?","options":["Business district: anywhere that is clear; rail crossing: not within 100 feet","Business district: only at an intersection; rail crossing: not within 100 feet","Business district: only at an intersection; rail crossing: not within 15 feet","Business district: never allowed; rail crossing: anywhere except on the tracks"],"correct":1},{"id":"q-4-022","fact_id":"s6-30","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When may a driver enter a marked bike lane?","options":["To overtake slower cars when the traffic lanes are packed","Whenever no cyclist is in view, since the lane is then empty","To get past a long line of cars waiting at a red light","To park, to enter or leave the road, or to turn"],"correct":3},{"id":"q-4-023","fact_id":"s6-30","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You will turn right at the next intersection, and a bike lane runs along the curb. When do you move into it?","options":["As soon as you can, even a full block before the corner","At least 200 feet before the corner, and no closer","Never; turn from the next lane across the bike lane","Within 200 feet of the intersection, after checking"],"correct":3},{"id":"q-4-024","fact_id":"s6-30","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing of bicycle-related numbers is right?","options":["200 feet: how near a corner you may enter a bike lane to turn; 3 feet: least passing gap","200 feet: the least gap when passing a cyclist; 3 feet: how near a corner you may enter a bike lane","200 feet: how far behind a cyclist you must stay; 3 feet: least passing gap","100 feet: how near a corner you may enter a bike lane to turn; 3 feet: least passing gap"],"correct":0},{"id":"q-4-025","fact_id":"s6-32","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which of these cases allows you to pass on the right?","options":["The vehicle ahead is driving below the speed limit","The vehicle ahead is signaling a right turn","The right shoulder is open and clear","The vehicle ahead is turning left or about to"],"correct":3},{"id":"q-4-026","fact_id":"s6-32","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"The car ahead stops in the only lane and signals left to enter a driveway. The pavement to your right is wide and clear. What may you do?","options":["Pass on the right if it is safe, since the car is turning left","Wait behind it, since passing on the right is never allowed","Cross the center line and pass on the left instead","Drive on the dirt shoulder to get around it"],"correct":0},{"id":"q-4-027","fact_id":"s6-32","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about passing is right?","options":["Pass on the right anywhere, as long as you signal first","Pass on the right never, not even on a one-way street","Pass on the left; the right only in a few set cases","Pass on the shoulder when a car ahead signals a left turn"],"correct":2},{"id":"q-4-028","fact_id":"s6_p11_roadway-023","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At what speed should you merge onto a freeway?","options":["At a slow, cautious pace so others can see you","At or near the speed of the traffic already on it","At the speed of the surface street you just left","At any speed, since freeway drivers must make room"],"correct":1},{"id":"q-4-029","fact_id":"s6_p11_roadway-023","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You reach the on-ramp end. Freeway traffic flows at 65 mph and you are at 40. What should you have done on the ramp?","options":["Sped up on the ramp to near 65 to slide into a gap","Slowed down to 40 and waited for traffic to open a gap","Stopped at the ramp end and waited for a clear gap","Kept at 40 and turned on your hazard lights"],"correct":0},{"id":"q-4-030","fact_id":"s6_p11_roadway-023","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of speed rules for joining a road is right?","options":["On a freeway on-ramp, slow down and yield; at a roundabout, match traffic speed","Slow down and yield at both a freeway on-ramp and a roundabout","Match traffic speed at both a freeway on-ramp and a roundabout","On a freeway on-ramp, match traffic speed; at a roundabout, slow down and yield"],"correct":3},{"id":"q-4-031","fact_id":"s6_p11_roadway-024","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"About how much open space on the freeway do you need to merge safely?","options":["About 300 feet","About 100 feet","About 400 feet","About 50 feet"],"correct":0},{"id":"q-4-032","fact_id":"s6_p11_roadway-024","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You look for a gap from the ramp. Which gap suits your car?","options":["A gap about two car lengths long between cars","A gap about 50 feet long between cars","A gap roughly 300 feet long between cars","The first gap you see, whatever its size"],"correct":2},{"id":"q-4-033","fact_id":"s6_p11_roadway-024","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of freeway distances is right?","options":["Merge space about 400 feet; start signaling for an exit about 300 feet ahead","Merge space about 300 feet; start signaling for an exit about 400 feet ahead","Merge space about 100 feet; start signaling for an exit about 400 feet ahead","Merge space and exit signaling both about 300 feet"],"correct":1},{"id":"q-4-034","fact_id":"s6_p11_roadway-025","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"When leaving a freeway, how far ahead should you start signaling?","options":["About 1 second or 50 feet before the exit","About 5 seconds or 400 feet before the exit","About 10 seconds or 800 feet before the exit","Only when you start to move into the exit lane"],"correct":1},{"id":"q-4-035","fact_id":"s6_p11_roadway-025","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"Your exit is ahead on the right and you are in the right lane. When do you turn on your signal?","options":["About 5 seconds before the exit, while still in your lane","As you pass the exit sign, a second before the turn","Only after you start moving into the exit lane","About half a minute before, so everyone knows early"],"correct":0},{"id":"q-4-036","fact_id":"s6_p11_roadway-025","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which freeway rule uses the 5-second figure?","options":["Keep a following distance of 5 seconds behind every vehicle","Start your signal about 5 seconds before an exit","Wait 5 seconds at a metered ramp light before merging","Check mirrors every 5 seconds on the freeway"],"correct":1},{"id":"q-4-037","fact_id":"s6_p11_roadway-026","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Your exit is three lanes to your right. How should you cross the lanes?","options":["All three lanes in one sweep as soon as a long gap opens","One lane at a time, checking and signaling before each move","Slowly across the lane lines, signaling only for the last lane","By braking in your lane until the exit lane comes up beside you"],"correct":1},{"id":"q-4-038","fact_id":"s6_p11_roadway-026","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are in the far left lane of a four-lane freeway. Your exit is on the right in half a mile. What is the best plan?","options":["Move right one lane at a time, signaling and checking","Cut across all the lanes in one move near the exit","Brake in the left lane to make traffic clear a path","Move onto the right shoulder and follow it to the exit"],"correct":0},{"id":"q-4-039","fact_id":"s6_p11_roadway-026","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"You must cross two lanes to reach an exit. Which sequence is right?","options":["Signal, check, change one lane; then signal, check, change the next lane","Signal once for five seconds, then cross both lanes in a single move","Check your mirrors once, then cross both lanes without signaling","Change lanes only when the exit sign appears, in whichever order opens"],"correct":0},{"id":"q-4-040","fact_id":"s6_p11_roadway-028","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Where must you not drive on the left side of the road, for example to pass?","options":["Beside a line of parked cars on a quiet residential street","Within 100 feet of a railroad crossing or of an intersection","Within 25 feet of an intersection or of a railroad crossing","Only on curves, where the road bends out of your sight"],"correct":1},{"id":"q-4-041","fact_id":"s6_p11_roadway-028","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You follow a slow truck on a two-lane road. An intersection is about 70 feet ahead. What do you do?","options":["Stay behind the truck until the intersection is behind you","Pull out now, because the oncoming lane looks clear","Drop back a little, then pass in the intersection when no one is oncoming","Honk, then go around the truck as you cross the intersection"],"correct":0},{"id":"q-4-042","fact_id":"s6_p11_roadway-028","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair of passing limits is right?","options":["Intersection: only when your view is blocked; bridge: always within 100 feet","Intersection: never within 100 feet; bridge: only when your view is blocked","Both places: the ban applies only when an oncoming car is in sight on the road","Both places: the ban applies only where a No Passing sign is posted"],"correct":1},{"id":"q-4-043","fact_id":"s6_p11_roadway-037","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Why should you avoid riding beside a large truck for long?","options":["The truck has big blind spots that can hide your whole car","The truck must slow down whenever a car stays beside it","The truck driver may not change lanes with a car alongside","The truck always gives way to a car that holds its place"],"correct":0},{"id":"q-4-044","fact_id":"s6_p11_roadway-037","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You ride beside a tractor-trailer on the freeway, level with its trailer. You cannot see its mirrors. What do you do?","options":["Pass it promptly, or drop well back, to leave its blind spot","Stay level with the cab, where the driver can see you","Move closer to the trailer so its mirrors show you clearly","Drift to the lane line so the driver sees your front bumper"],"correct":0},{"id":"q-4-045","fact_id":"s6_p11_roadway-037","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement about blind spots is right?","options":["Trucks have about the same blind spots as cars do","Trucks have much bigger blind spots than cars do","Trucks have no blind spots because they sit higher","Trucks have a blind spot only directly behind the trailer"],"correct":1},{"id":"q-4-046","fact_id":"s6_p11_roadway-038","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How should you pass a large truck?","options":["On its left, without lingering beside it","On its right, away from where the driver sits","On whichever side has the faster lane","On its left, staying alongside until the driver waves"],"correct":0},{"id":"q-4-047","fact_id":"s6_p11_roadway-038","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On a three-lane road a long truck in the middle lane is slower than you. The right lane is empty. How do you pass?","options":["Use the empty right lane, which is clear of other cars","Use the left lane, pass promptly, and return when well ahead","Use the right lane, but only until you match its speed","Speed up on the right to get past before it moves over"],"correct":1},{"id":"q-4-048","fact_id":"s6_p11_roadway-038","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair of rules for passing is right?","options":["Truck: pass on the right, no lingering; cyclist: leave at least 3 feet","Truck: pass on the left, no lingering; cyclist: leave at least 1 foot","Truck: pass on either side; cyclist: pass as close as you can","Truck: pass on the left, no lingering; cyclist: leave at least 3 feet"],"correct":3},{"id":"q-4-049","fact_id":"s6_p11_roadway-039","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which of these should you never do around a large truck?","options":["Passing it on the left while the lane ahead is clear","Keeping a long following distance behind it on the freeway","Signaling early before you move into a lane near it","Cutting in close in front of it right after you pass"],"correct":3},{"id":"q-4-050","fact_id":"s6_p11_roadway-039","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"After passing a truck, you want its lane back. The gap between you and its front is about one car length. What do you do?","options":["Cut back in now; trucks always keep room ahead of themselves","Slide in and tap your brakes so the truck slows too","Pull farther ahead and merge only with a long gap behind you","Signal, then merge slowly so the truck driver sees you coming"],"correct":2},{"id":"q-4-051","fact_id":"s6_p11_roadway-039","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement about a slow large truck ahead is right?","options":["Pass it on the right, as with a left-turning car","Pass it on the left; never pass it on the right","Pass it on either side, using both of its mirrors","Stay close behind it until its driver changes lanes"],"correct":1},{"id":"q-4-052","fact_id":"s6_p11_run2-011","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the long space on a freeway on-ramp meant to let you do?","options":["Stop safely if the freeway lanes beside you are full","Pass slower cars before you reach the freeway lanes","Reach the speed of freeway traffic before you merge","Drive at the surface street speed until the ramp ends"],"correct":2},{"id":"q-4-053","fact_id":"s6_p11_run2-011","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You enter an on-ramp at 30 mph while freeway traffic flows at 65. About how much road do you have to catch up?","options":["About 1,000 feet, so you can ease up to speed later","About 100 feet, so you must stop and wait for a gap","Roughly 300 feet, so you can stay slow and merge at its very end","Roughly 300 feet, so you start accelerating right away"],"correct":3},{"id":"q-4-054","fact_id":"s6_p11_run2-011","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about a freeway on-ramp is right?","options":["The ramp spaces cars out; the metered signal gives room to match speed","The ramp and the signal both slow cars down before the freeway","The ramp signal gives you right-of-way over freeway traffic","The ramp gives room to match speed; the meter only spaces cars"],"correct":3},{"id":"q-4-055","fact_id":"s6_p11_run2-012","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How should you handle your speed on a freeway off-ramp?","options":["Stay at freeway speed until the ramp curves, then brake hard","Brake hard the moment you leave the freeway lane","Start easing off early, before you enter the deceleration lane","Slow down only after you are on the surface street"],"correct":2},{"id":"q-4-056","fact_id":"s6_p11_run2-012","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your freeway exit is a quarter mile ahead and cars follow close behind you. What do you do about speed?","options":["Hold your speed until the exit, then brake hard at the gore","Ease off the gas early, before the exit lane begins","Switch on your hazard lights and slow quickly in the lane","Speed up to clear the cars behind before you exit"],"correct":1},{"id":"q-4-057","fact_id":"s6_p11_run2-012","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair of freeway speed rules is right?","options":["Entering: match traffic speed; exiting: ease off early","Entering: stay slow for safety; exiting: match traffic speed","Entering: match traffic speed; exiting: hold speed down the ramp","Entering and exiting: use the posted surface street limit"],"correct":0},{"id":"q-4-058","fact_id":"s6_p11_run2-013","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a metered signal on a freeway on-ramp do?","options":["It controls the flow of cars entering the freeway at busy times","It signals freeway traffic to slow down for merging cars","It shows the freeway speed limit for the lanes ahead","It reserves the ramp for carpool vehicles during commute hours"],"correct":0},{"id":"q-4-059","fact_id":"s6_p11_run2-013","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"At a metered on-ramp the signal is red. You can see no freeway traffic nearby. What do you do?","options":["Go through slowly; ramp signals are only advice","Follow the car ahead through as it goes on red","Wait for the green light and go when it shows","Stop at the signal, then go when the freeway looks clear"],"correct":2},{"id":"q-4-060","fact_id":"s6_p11_run2-013","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"The ramp signal turns green. What does that mean?","options":["You may go, but only after the freeway traffic has cleared away","You may go, and freeway traffic must slow or move over for you","You may go, and skip your mirror and shoulder checks this time","You may go, but you still match speed and look for a gap"],"correct":3},{"id":"q-4-061","fact_id":"s6_p11_run2-014","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How many people does a carpool lane require?","options":["It is the same in every lane; the number is always 2","It varies by car; the number depends on the seats built in","It varies by lane; the posted number is often 2, 3 or 4","It varies by county; each county sets one number"],"correct":2},{"id":"q-4-062","fact_id":"s6_p11_run2-014","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You and two friends drive toward a carpool lane that is posted for 3 or more people. What do you do?","options":["Use the lane; three people meet the posted minimum","Stay out; every carpool lane needs at least four people","Use the lane, but only if the other lanes are slow","Stay out; the driver does not count toward the minimum"],"correct":0},{"id":"q-4-063","fact_id":"s6_p11_run2-014","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"On a carpool lane, what shows the lane's marking, and what shows the people needed?","options":["The signs mark the lane; the diamond says how many people are needed","The diamond does both jobs for every carpool lane","The diamond marks the lane; signs say how many people are needed","The same number applies everywhere, so no sign is needed"],"correct":2},{"id":"q-4-064","fact_id":"s6_p11_run2-015","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"What can happen if you drive in a carpool lane without enough people?","options":["Your clean-air decal is taken away, and no fine follows","You commit a traffic violation and may be fined for it","A fine applies when you also speed or cause a crash","A warning is given first, and a fine comes after a repeat"],"correct":1},{"id":"q-4-065","fact_id":"s6_p11_run2-015","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"You are late and alone, and the carpool lane is clear while the other lanes crawl. What is the consequence of using it?","options":["Only a warning, never a fine, on a first offense","A traffic violation, which can bring a fine","A penalty only if an officer happens to see you","No penalty, because a clear lane harms no other driver"],"correct":1},{"id":"q-4-066","fact_id":"s6_p11_run2-015","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Which pair is matched correctly?","options":["Carpool lane: obey the light during rush hours; ramp meter: too few people means a fine","Carpool lane: no penalty if the lane is empty; ramp meter: advice only","Carpool lane and ramp meter: both count the people in your car","Carpool lane: too few people means a fine; ramp meter: obey the light during rush hours"],"correct":3},{"id":"q-4-067","fact_id":"s6_p11_run2-016","area":"california_specific","type":"recall","difficulty":0.35,"stem":"What happened to the clean-air vehicle decals that let some cars use carpool lanes?","options":["The decals no longer work: the program ended in 2025","The decals still work in every carpool lane at all hours","The decals stay valid for the life of the car once issued","The decals now let any hybrid car use carpool lanes alone"],"correct":0},{"id":"q-4-068","fact_id":"s6_p11_run2-016","area":"california_specific","type":"situation","difficulty":0.5,"stem":"A friend with a 2022 clean-air decal drives alone in a carpool lane. What should you tell him?","options":["He can keep driving alone, since the decal gives lifetime access","He should renew the decal, since renewal keeps the access going","He may drive alone only at off-peak hours with the decal","He should check the current rules, since the program ended in 2025"],"correct":3},{"id":"q-4-069","fact_id":"s6_p11_run2-016","area":"california_specific","type":"confusion","difficulty":0.65,"stem":"Which way of using a carpool lane is still correct after 2025?","options":["Having the posted number of people, per the signs","Using a clean-air decal alone","Using either a decal or enough people, for any car","Using a decal that was issued before 2025"],"correct":0},{"id":"q-4-070","fact_id":"s6_p11_run2-019","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How should you change lanes when merging across several lanes?","options":["One lane at a time, with a clear view and a signal","Two lanes at once, to cut your time among the cars","One lane at a time, but signal only after you start to move","One lane at a time, with a signal, relying on mirrors alone"],"correct":0},{"id":"q-4-071","fact_id":"s6_p11_run2-019","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You merge from a ramp and need to reach the left lane of a three-lane freeway. What is best?","options":["Wait for a long gap and cross all lanes in one swing","Stay in the right lane and pass everyone on the right","Move over lane by lane, signaling and checking each time","Signal once at the ramp and cross each lane unchecked"],"correct":2},{"id":"q-4-072","fact_id":"s6_p11_run2-019","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which order is right for each lane change while merging?","options":["Move over, then signal, then check","Check the mirrors only, and signal while moving","Signal only for the car closest behind you","Signal, check mirrors and blind spot, then move"],"correct":3},{"id":"q-4-073","fact_id":"s6_p11_run2-020","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How much space should you allow when you merge into traffic?","options":["The smallest gap that fits, since drivers will adjust","Enough that nobody must brake hard because you merged","Any gap at all, if you signal long enough beforehand","Space ahead only, as the driver behind watches the gap"],"correct":1},{"id":"q-4-074","fact_id":"s6_p11_run2-020","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A gap opens in the lane beside you, but the car behind that gap is closing fast. What do you do?","options":["Go in now; your signal will tell the driver to slow","Wait for a bigger gap that nobody has to hurry to meet","Slip in and accelerate to ease pressure on that driver","Dart in sharply to hold the gap before it closes"],"correct":1},{"id":"q-4-075","fact_id":"s6_p11_run2-020","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which describes safe spacing after a merge?","options":["Open space both in front of you and behind you","Room ahead only; the driver behind watches the gap","Close to the car ahead, so nobody can cut in","Very little room, because the lane is yours after a signal"],"correct":0},{"id":"q-4-076","fact_id":"s6_p11_run2-021","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"About how many seconds before leaving a freeway should your signal be on?","options":["About 1 second","About 5 seconds","About 3 seconds","About 10 seconds"],"correct":1},{"id":"q-4-077","fact_id":"s6_p11_run2-021","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are in the proper exit lane at freeway speed. When do you switch on your turn signal?","options":["About one second before you start to leave the lane","Only after you have slowed down on the ramp","About five seconds before the exit, while still in your lane","About thirty seconds before, as soon as you see the exit sign"],"correct":2},{"id":"q-4-078","fact_id":"s6_p11_run2-021","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which pair of numbers is right?","options":["Exit signal about 3 seconds before; following distance at least 5 seconds","Exit signal and following distance both about 3 seconds","Exit signal and following distance both about 5 seconds","Exit signal about 5 seconds before; following distance at least 3 seconds"],"correct":3},{"id":"q-4-079","fact_id":"s6_p11_run2-024","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A large truck driver has a poor view to the sides and rear. What should you do?","options":["Pass close beside it so that the driver sees you","Honk once, then change lanes right beside its cab","Keep extra room when passing or merging near it","Stay about one car length behind its rear bumper"],"correct":2},{"id":"q-4-080","fact_id":"s6_p11_run2-024","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You passed a truck and want back in its lane. What do you do?","options":["Cut back right away to leave the blind spot quickly","Slide in as soon as its front bumper is in your mirror","Pull well ahead first, then merge with ample room","Flash your lights to alert the driver, then move over"],"correct":2},{"id":"q-4-081","fact_id":"s6_p11_run2-024","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement about a truck driver's view is right?","options":["The driver sees the sides well in large mirrors, so little space is needed","The driver sees directly behind the truck, so following close is safe","The driver has a limited view to the sides and rear, so stay a car length away","The driver has a limited view to the sides and rear, so give more room"],"correct":3},{"id":"q-4-082","fact_id":"s7-17","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What should you do when you enter a roundabout?","options":["Slow down, yield to the traffic inside, and enter at a safe gap","Keep your speed and take the entry before others reach it","Stop fully at the line and then go ahead of circling cars","Merge in ahead of circling cars after a clear signal"],"correct":0},{"id":"q-4-083","fact_id":"s7-17","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You approach a roundabout, and a car already circling is heading toward your entry. What do you do?","options":["Speed up to enter ahead of it, since you are at the line first","Stop inside the circle to let that car go past you","Slow down and wait to enter until a safe gap opens","Enter beside it and match its pace around the circle"],"correct":2},{"id":"q-4-084","fact_id":"s7-17","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a roundabout entry, who has the right-of-way?","options":["Traffic about to enter from your right","Traffic already in the circle","Whichever vehicle reaches the entry line first","The largest vehicle at the entry"],"correct":1},{"id":"q-4-085","fact_id":"s7-18","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which way do you travel around a roundabout?","options":["Counter-clockwise, without stopping or passing others","Clockwise, using the inside lane whenever you can","Whichever direction is shorter to your exit","Counter-clockwise, passing slower cars on the inside"],"correct":0},{"id":"q-4-086","fact_id":"s7-18","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Inside a roundabout, a car ahead moves slowly. Your exit is the next one. What do you do?","options":["Pass it on the inside to reach your exit sooner","Stay behind it and keep circling to your exit","Stop in the circle until that car clears the exit","Turn left inside the circle and take the shorter way"],"correct":1},{"id":"q-4-087","fact_id":"s7-18","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair describes a roundabout correctly?","options":["Entering: keep your speed; inside: stop to check your exit","Entering: stop completely; inside: pass slow cars on the inside","Entering: yield; inside: stop for each car that enters","Entering: yield for a gap; inside: keep moving, no stopping"],"correct":3},{"id":"q-4-088","fact_id":"s7-20","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How do you pick an entry lane at a multi-lane roundabout?","options":["By the lane with the fewest cars waiting","By the speed you wish to travel in the circle","By the exit you plan to take out of the circle","Always the inner lane, to stay out of others' way"],"correct":2},{"id":"q-4-089","fact_id":"s7-20","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Before entering a two-lane roundabout, you read signs showing which lane leads to which exit. What do you do?","options":["Take the lane that matches your exit and keep to it","Take the emptier lane, then change lanes in the circle","Take the left lane, which moves faster through the circle","Wait until inside the circle to decide on a lane"],"correct":0},{"id":"q-4-090","fact_id":"s7-20","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Two drivers explain how to choose a lane at a multi-lane roundabout. Which explanation is right?","options":["Choose after you enter, and let the cars beside you decide","Choose by vehicle size, with the big vehicles on the outside","Choose whichever lane has the longest gap and go","Choose before you enter, and let your exit decide the lane"],"correct":3},{"id":"q-4-091","fact_id":"s7-21","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Who has the right-of-way at all times, even where a driver would normally go first?","options":["A bus driver pulling out from a stop with passengers aboard","A driver who has already entered the intersection on a green light","A cyclist who rides with the traffic on the same road","A blind pedestrian who carries a white cane or uses a guide dog"],"correct":3},{"id":"q-4-092","fact_id":"s7-21","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You turn right on green. A man with a white cane steps off the curb outside the crosswalk. What do you do?","options":["Stop and wait until he has finished crossing","Slow down and tap your horn to guide him back","Edge forward, since he is outside the crosswalk","Pass behind him slowly while he is still crossing"],"correct":0},{"id":"q-4-093","fact_id":"s7-21","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A driver says a white cane gives right-of-way only in a crosswalk. Which correction is right?","options":["A white cane gives it only at traffic signals","A white cane or a guide dog gives the right-of-way at all times","It applies only when the person raises the cane toward traffic","Only a guide dog gives it; a white cane does not"],"correct":1},{"id":"q-4-094","fact_id":"s7_p11_roadway-005","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Traffic is thick and your lane moves slowly. Which choice is a driving mistake?","options":["Holding your position in one lane at a steady pace","Signaling before a planned lane change","Leaving a gap between you and the car ahead","Weaving in and out of lanes to gain a few places"],"correct":3},{"id":"q-4-095","fact_id":"s7_p11_roadway-005","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your lane is slower than the lane to your left and traffic is heavy. What do you do?","options":["Move to the faster lane, and back again as it slows","Switch lanes whenever the next one is faster, signaling each time","Hold your lane but crawl well below the speed of traffic to be safe","Pick a lane and hold it, keeping a steady pace with traffic"],"correct":3},{"id":"q-4-096","fact_id":"s7_p11_roadway-005","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which of these counts as weaving?","options":["One signaled lane change to prepare for an exit","Moving over one lane to pass a slow truck and staying there","Repeated quick lane changes to gain a few car lengths","Changing lanes once to let merging cars in"],"correct":2},{"id":"q-4-097","fact_id":"s7_p11_roadway-009","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"About how far can a large truck need to stop when it travels at highway speed?","options":["Only about 100 feet, as a car does","Roughly 200 feet, about twice a car","Up to about 400 feet","Nearly 800 feet, two full blocks"],"correct":2},{"id":"q-4-098","fact_id":"s7_p11_roadway-009","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You pass a truck on the freeway and merge back 100 feet ahead of it, then brake for slow traffic. Why is this risky?","options":["The truck stops as fast as a car, so it only startles the driver","A truck stops in about 100 feet, so your gap is enough","The truck can need roughly 400 feet to halt and could run into you","The truck driver sits high, so he brakes sooner than a car driver would"],"correct":2},{"id":"q-4-099","fact_id":"s7_p11_roadway-009","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of distances is right?","options":["400 feet: freeway merge space; 300 feet: a large truck's stopping distance","300 feet: a large truck's stopping distance; 100 feet: freeway merge space","400 feet: both a truck's stopping distance and a merge space","400 feet: a large truck's stopping distance; 300 feet: freeway merge space"],"correct":3},{"id":"q-4-100","fact_id":"s7_p11_run2-018","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"You near a railroad crossing, and for the last 100 feet you cannot see it clearly for 400 feet either way. What speed limit applies?","options":["25 mph","15 mph","35 mph","10 mph"],"correct":1},{"id":"q-4-101","fact_id":"s7_p11_run2-018","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Trees block your view of a rail crossing during the last 100 feet of the approach. The road is posted 45 mph. What speed is the limit?","options":["15 mph until the tracks are clearly in view","The posted 45 mph, because no train is in sight","25 mph, the figure used for school zones","30 mph, about two-thirds of the posted speed"],"correct":0},{"id":"q-4-102","fact_id":"s7_p11_run2-018","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A rail crossing has a blocked-view approach and a stopping rule. Which pair of numbers is right?","options":["Blocked-view approach: 15 mph; stop at least 15 feet from the nearest rail","Blocked-view approach: 15 mph; stop at least 100 feet from the nearest rail","Blocked-view approach: 25 mph; stop at least 15 feet from the nearest rail","Blocked-view approach: 15 mph; stop 5 feet from the nearest rail"],"correct":0},{"id":"q-4-103","fact_id":"s7_p11_run2-019","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A crossing signal or flagger warns of a train. How far from the nearest rail must you stop?","options":["At least 5 feet","At least 10 feet","At least 15 feet","Right at the edge of the rail, ready to go"],"correct":2},{"id":"q-4-104","fact_id":"s7_p11_run2-019","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You approach a crossing with flashing signals. Where do you stop?","options":["As close to the rail as you can get","About 5 feet short of the nearest rail","At least 15 feet short of the nearest rail","Just past the rail, behind the car ahead"],"correct":2},{"id":"q-4-105","fact_id":"s7_p11_run2-019","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which figure tells where to stop when a crossing warns of a train?","options":["15 feet, the least distance from the nearest rail","100 feet, the U-turn ban distance near crossings","400 feet, the sight distance on a blocked approach","3 feet, the gap used when passing a cyclist"],"correct":0},{"id":"q-4-106","fact_id":"s7_p11_run2-024","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the least following distance in good conditions?","options":["At least 1 second","At least 2 seconds","One car length for every 10 mph","At least 3 seconds"],"correct":3},{"id":"q-4-107","fact_id":"s7_p11_run2-024","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Rain is falling hard and you follow a car at 55 mph. What following distance do you keep?","options":["3 seconds, no matter what the weather is","More than 3 seconds, since rain calls for extra room","2 seconds, because the wipers keep your view clear","1 second, since the car ahead is also slowing"],"correct":1},{"id":"q-4-108","fact_id":"s7_p11_run2-024","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"It starts to rain. Which change to your following distance is right?","options":["Add time, because the 3-second gap is a minimum","Cut it, since rain slows everyone down","Keep exactly 3 seconds, since it is a fixed legal number","Add time, but only once the road is flooded"],"correct":0},{"id":"q-4-109","fact_id":"s7b-17","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the lowest speed limit a school zone can have when children are present?","options":["15 mph","5 mph","10 mph","20 mph"],"correct":0},{"id":"q-4-110","fact_id":"s7b-17","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You pass an elementary school as children cross. A school zone sign is posted, and cars behind you honk. What speed do you choose?","options":["The posted school zone limit, as low as 15 mph","The usual 25 mph, since the sign is only advice","The speed of the cars behind you, about 30 mph","The road's regular limit once the children reach the far curb"],"correct":0},{"id":"q-4-111","fact_id":"s7b-17","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about school zone speed limits is right?","options":["School zones are set at 25 mph near the school, and none goes lower than 20","In some areas a school zone can drop to 15 mph with children present","In some areas a school zone can drop to 20 mph with children present","In some areas a school zone can drop to 15 mph, but only at dismissal time"],"correct":1},{"id":"q-4-112","fact_id":"s7b-19","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How do the rights of a motorcycle rider compare with other drivers?","options":["They have fewer rights than car drivers do","They have the same rights and responsibilities","They have extra priority over cars on a narrow road","They have the same rights, but fewer responsibilities"],"correct":1},{"id":"q-4-113","fact_id":"s7b-19","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"At an all-way stop, a motorcycle reaches the line before your car. The rider looks small and slow to start. What do you do?","options":["Wait your turn; the rider goes first, as any driver would","Go first, since your car is the larger vehicle","Go first, since a motorcycle must yield to cars","Wait a few seconds, then go if the rider has not started moving"],"correct":0},{"id":"q-4-114","fact_id":"s7b-19","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about road rights is right?","options":["Motorcycles have the same rights as cars; bicycles have none","Bicycles have the same rights as cars; motorcycles have fewer","Motorcycles and bicycles have the same rights as cars","Neither motorcycles nor bicycles have full rights, due to size"],"correct":2},{"id":"q-4-115","fact_id":"s7b-20","area":"california_specific","type":"recall","difficulty":0.35,"stem":"What is the rule on lane splitting by motorcycles in California?","options":["It is banned on every roadway in the state","It is legal only for police motorcycles","It is legal for motorcycles on California roads","It is legal only when traffic has stopped completely"],"correct":2},{"id":"q-4-116","fact_id":"s7b-20","area":"california_specific","type":"situation","difficulty":0.5,"stem":"You pass a motorcycle on a two-lane road. How much of the lane does it need?","options":["Half the lane, so you pass within the same lane","Only its own width, so passing beside it is fine","The full lane, so you pass in the next lane","None, as riders must move to the shoulder for cars"],"correct":2},{"id":"q-4-117","fact_id":"s7b-20","area":"california_specific","type":"confusion","difficulty":0.65,"stem":"Which statement about motorcycles and lanes is right?","options":["Lane splitting is illegal; sharing a lane with a motorcycle is fine","Lane splitting and lane sharing are both illegal for everyone","Lane splitting and lane sharing are both legal for everyone","Lane splitting is legal; sharing a lane with a motorcycle is not"],"correct":3},{"id":"q-4-118","fact_id":"s7b-21","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"Who must wear a bicycle helmet under California law?","options":["Riders under 16","Riders under 21","Riders under 18","Riders of any age on a public road"],"correct":2},{"id":"q-4-119","fact_id":"s7b-21","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"You see a cyclist about 25 years old with no helmet. How do you pass?","options":["Pass closer, since the rider chose less protection","Skip the 3-foot gap, since adults may choose their gear","Slow and wait, since the rider is breaking the law","Give the usual full space, since helmets do not change it"],"correct":3},{"id":"q-4-120","fact_id":"s7b-21","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"A 17-year-old and a 19-year-old cycle ahead of you. Which statement is right?","options":["Both riders must wear helmets by law","The 17-year-old must wear a helmet; the 19-year-old need not","Neither rider must wear a helmet by law","The 19-year-old must wear a helmet; the 17-year-old need not"],"correct":1},{"id":"q-4-121","fact_id":"s7b-22","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"On the roadway, how do a cyclist's rights compare with a driver's?","options":["A cyclist has the right-of-way over cars at all times","A cyclist has the rights of a pedestrian, not of a driver","A cyclist has the same rights and duties","A cyclist must give way to every motor vehicle"],"correct":2},{"id":"q-4-122","fact_id":"s7b-22","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A cyclist reaches a four-way stop just before you do. Who goes first?","options":["You do, since a car outranks a bicycle","The cyclist waits, since cyclists must yield to cars at a stop","You do, if you signal your turn before the cyclist does","The cyclist, like any other driver in line"],"correct":3},{"id":"q-4-123","fact_id":"s7b-22","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which describes a cyclist on the road?","options":["A cyclist follows pedestrian rules, since a bike has no motor","A cyclist follows the rules for drivers, not those for pedestrians","A cyclist has no road rules at all","A cyclist is a driver, except inside a crosswalk"],"correct":1},{"id":"q-4-124","fact_id":"s8c-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does California's Basic Speed Law require?","options":["Never driving above the posted limit, in any weather or traffic","Driving at the same speed as the cars that surround you","Never driving faster than is safe for conditions, whatever the limit","Driving at the posted limit whenever the road looks clear"],"correct":2},{"id":"q-4-125","fact_id":"s8c-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Fog covers a freeway posted at 65 mph, and you see only about 100 feet ahead. What speed do you choose?","options":["Stay at 65, since the sign allows that speed","Hold 65 mph and switch on your low-beam headlights","Slow well below 65, to a speed that is safe in fog","Copy the speed of the car ahead of you"],"correct":2},{"id":"q-4-126","fact_id":"s8c-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A driver goes 55 in a 65 zone in heavy rain and is cited for speed. Which statement is right?","options":["A ticket under the posted limit is never possible, whatever the weather","The law applies only to speeds above the posted limit","The Basic Speed Law can apply even below the posted limit","The law applies only in fog, never in rain or on wet roads"],"correct":2},{"id":"q-4-127","fact_id":"s8c-002","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"On most highways in California, what is the top legal speed?","options":["65 mph","55 mph","70 mph","75 mph"],"correct":0},{"id":"q-4-128","fact_id":"s8c-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive a typical freeway with no sign for a higher limit. Conditions are perfect. What is the most you may drive?","options":["65 mph, the top legal speed on most highways","70 mph, the speed most cars actually drive there","75 mph, when no other car is anywhere near you","55 mph, the limit that applies on every highway"],"correct":0},{"id":"q-4-129","fact_id":"s8c-002","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of speed limits is right?","options":["Most highways: 55 mph; two-lane undivided highways: 65 mph","Most highways: 65 mph; two-lane undivided: 55 mph unless posted","Most highways and two-lane undivided highways: both 65 mph","Most highways and two-lane undivided highways: both 55 mph"],"correct":1},{"id":"q-4-130","fact_id":"s8c-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What speed limit applies on a two-lane undivided highway unless a sign allows more?","options":["65 mph","45 mph","55 mph","60 mph"],"correct":2},{"id":"q-4-131","fact_id":"s8c-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive a rural two-lane undivided highway with no speed signs. The road is empty and dry. What is the highest legal speed?","options":["65 mph, the same as on other highways","60 mph, halfway between the two limits","70 mph, because the road is empty and dry","55 mph, the default with no higher posting"],"correct":3},{"id":"q-4-132","fact_id":"s8c-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement fits a two-lane undivided highway?","options":["55 mph, and no sign can ever raise it for any reason","65 mph, which signs may lower but never raise","55 mph, raised only by a sign posted after a survey","No set speed; each driver judges the safe speed alone"],"correct":2},{"id":"q-4-133","fact_id":"s8c-010","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How much room must you leave when you pass a bicyclist?","options":["At least 1 foot","At least 2 feet","At least 3 feet","Enough to avoid touching, with no set number"],"correct":2},{"id":"q-4-134","fact_id":"s8c-010","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"On a narrow road you come up behind a cyclist. You cannot keep 3 feet of space while staying in your lane, and a car is coming the other way. What do you do?","options":["Pass with a foot of room, since the lane is narrow","Stay behind until you can pass with at least 3 feet","Pass fast with two feet before the oncoming car arrives","Stay behind and flash your headlights until the cyclist pulls over"],"correct":1},{"id":"q-4-135","fact_id":"s8c-010","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How is the 3-foot gap for passing a cyclist measured?","options":["From the middle of your car to the middle of the bicycle","From the lane line on your side of the road to the rider's body","From any part of your vehicle to any part of the bike or rider","From your car's headlights to the bicycle's front wheel as you pull level"],"correct":2},{"id":"q-4-136","fact_id":"signs-040","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A blue rectangle shows a white H. What does it tell you?","options":["A helicopter landing area for emergency crews only","A medical clinic with no emergency care is near","Parking for hospital staff only","A hospital with emergency care is near"],"correct":3},{"id":"q-4-137","fact_id":"signs-040","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"On a long drive you see a blue rectangle with a white H beside the road. What does the sign tell you?","options":["A hospital with emergency care is near","A hotel with rooms is at the next exit","A highway patrol office is ahead","A helicopter landing pad is ahead"],"correct":0},{"id":"q-4-138","fact_id":"signs-040","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which sign shows that emergency care is near?","options":["The white-on-blue Rest Area sign","The white-on-green Freeway Exit sign","The white-on-brown Recreation Area sign","The white-on-blue Hospital sign"],"correct":3},{"id":"q-4-139","fact_id":"signs-041","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A rectangle with white lettering on a green background stands beside the freeway. What does it tell you?","options":["A hospital with emergency care just off the freeway","A rest area just ahead on the right side of the road","A park or recreation site near the freeway","An exit where you leave the freeway"],"correct":3},{"id":"q-4-140","fact_id":"signs-041","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You need to leave the freeway at the next town. You see a green sign with white lettering for your exit. What do you do?","options":["Slow in your lane to read every word on the sign","Check your lane, signal early, and take the exit","Keep going, treating the green sign as only information","Wait and cut across the lanes just before the gore"],"correct":1},{"id":"q-4-141","fact_id":"signs-041","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which color pair for guide signs is right?","options":["Green: a hospital with emergency care; blue: a freeway exit","Green: a rest area ahead; blue: a park or recreation site near","Green: a park or recreation site; blue: a freeway exit","Green: a freeway exit; blue: a hospital or a rest area"],"correct":3},{"id":"q-4-142","fact_id":"signs-042","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"Which message belongs to the white-on-blue Rest Area sign?","options":["A truck weigh station is ahead for trucks only","A stopping place for travelers is ahead","A hospital with emergency care is near","A park or recreation site is just ahead"],"correct":1},{"id":"q-4-143","fact_id":"signs-042","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"Which statement about the blue Rest Area sign is right?","options":["It marks a place ahead where travelers can pull off and stop","It warns that a truck weigh station is ahead","It marks a hospital where tired drivers may rest and get care","It marks a park where drivers may stop for a picnic and a rest"],"correct":0},{"id":"q-4-144","fact_id":"signs-042","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Two blue rectangles look alike at a distance: the Hospital sign and the Rest Area sign. How do you tell them apart?","options":["By the symbol or wording on each sign, such as an H for a hospital","By which side of the road each sign stands on, left or right","By the size of the letters, since a hospital sign has larger text","By the shade of blue, since a hospital sign is a darker blue"],"correct":0},{"id":"q-4-145","fact_id":"signs-043","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A rectangle with white lettering on a brown background stands beside the road. What does it tell you?","options":["A hospital with emergency care is near","A park or recreation site is near","A freeway exit lies ahead","A rest area is ahead"],"correct":1},{"id":"q-4-146","fact_id":"signs-043","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive with children and see a brown sign with white lettering beside the road. What does it most likely tell you?","options":["A school zone with a lower limit begins","A camping ban applies on the road ahead","A park or recreation site is nearby","A road closed to cars lies ahead"],"correct":2},{"id":"q-4-147","fact_id":"signs-043","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A brown sign and a green sign both stand near an exit. Which statement is right?","options":["Brown shows the freeway exit; green shows a recreation site","Both colors show the same kind of place on the road","Brown shows a park or recreation site; green shows an exit","Brown shows emergency care; green shows a rest area"],"correct":2},{"id":"q-5a-001","fact_id":"glossary-006","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How do you use the three-second rule to judge your following distance?","options":["Count the seconds from when you spot a hazard until your car stops","Count the seconds it takes you to speed up to the posted limit","Count the seconds from when the car ahead passes a spot until you reach it","Count the seconds from when the car ahead brakes until you brake"],"correct":2},{"id":"q-5a-002","fact_id":"glossary-006","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On a dry freeway the truck ahead passes a road sign. You count \\"one-thousand-one, one-thousand-two\\" and then you pass the same sign. What does that tell you?","options":["Your gap is fine, since two seconds is the usual rule","Your gap is too short for the three-second rule, so ease back","Your gap is fine because freeways need less room than streets","Your gap is too short, so brake hard to open it up right away"],"correct":1},{"id":"q-5a-003","fact_id":"glossary-006","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver says the three-second rule means staying three car lengths back. What is wrong with that?","options":["It counts a time gap that spans more road as you go faster","It counts one car length for every ten mph of speed","It counts three seconds of braking after you see a hazard","It counts three seconds of gap only when the road is wet"],"correct":0},{"id":"q-5a-004","fact_id":"p14_gaps-005","area":"environment","type":"recall","difficulty":0.35,"stem":"When is a road usually at its most slippery during a rainstorm?","options":["Right after the rain stops, while the surface dries","After an hour of rain, when the water is deepest","At the height of the storm, when the rain is heaviest","In the first minutes after the rain begins, when oil rises"],"correct":3},{"id":"q-5a-005","fact_id":"p14_gaps-005","area":"environment","type":"situation","difficulty":0.5,"stem":"It has been dry for weeks. Light rain starts just as you leave a parking lot. How should you treat the road?","options":["Drive as usual, since light rain only wets the surface a little","Turn the wipers on and keep your usual following distance","Slow down now, since oil lifts up with the first water","Slow down only if it turns heavy, since light rain rinses off oil"],"correct":2},{"id":"q-5a-006","fact_id":"p14_gaps-005","area":"environment","type":"confusion","difficulty":0.65,"stem":"Why is the first part of a rainstorm so slippery for a car?","options":["Brakes get wet and grab less until they dry out","Oil on the road comes up as the water mixes in","Lane paint and metal covers turn slick before the road does","Water has no time to drain, so tires ride on top of it"],"correct":1},{"id":"q-5a-007","fact_id":"s12-002","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which of these is named among the conditions that can create a driving safety risk and call for DMV assessment?","options":["Being over 65 years old","Vertigo, a spinning kind of dizziness","Needing glasses for distance","Mild seasonal allergies"],"correct":1},{"id":"q-5a-008","fact_id":"s12-002","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your uncle had a stroke last spring and says he feels fine to drive. What does the handbook's guidance mean for him?","options":["He can keep driving, but only on short trips close to home","A stroke can make driving unsafe, so the DMV may assess him","An assessment can only follow a crash, never come before one","A stroke can matter for truckers and bus drivers, but not for ordinary drivers"],"correct":1},{"id":"q-5a-009","fact_id":"s12-002","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"After a doctor reports that a patient has a seizure disorder, who decides whether the patient is safe to keep driving?","options":["The patient's car insurance company","The doctor alone, without any DMV role","The patient's family members","The DMV, through its own assessment"],"correct":3},{"id":"q-5a-010","fact_id":"s12-007","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"You doubt your own driving ability. What step does the handbook suggest?","options":["Limit yourself to short local trips and hope it improves","Ask any passenger to tell you if they feel nervous","Ask a trusted licensed driver to observe you while you drive","Wait for the DMV to send a letter calling you in"],"correct":2},{"id":"q-5a-011","fact_id":"s12-007","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Gwen is 70 and has noticed she hesitates more at busy intersections. She wants an honest opinion. What fits the handbook best?","options":["Rely on her own feeling, since she has driven for many decades","Give up the keys now, with no one watching her drive first","Ride with a trusted licensed driver who watches her closely","Take a week off from driving to see if it passes"],"correct":2},{"id":"q-5a-012","fact_id":"s12-007","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Ravi worries about his driving but has no diagnosed condition. What can he do right now?","options":["Wait for the DMV to order an assessment","Have his doctor file a report to the DMV first","Take the written test again on his own schedule","Ask a trusted licensed driver to observe him driving"],"correct":3},{"id":"q-5a-013","fact_id":"s13-006","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How long is the DMV Mature Driver Improvement Program course?","options":["3 hours","5 hours","12 hours","8 hours"],"correct":3},{"id":"q-5a-014","fact_id":"s13-006","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Pat is 58 and is thinking about the DMV's Mature Driver Improvement Program. Which statement fits?","options":["Pat is too young, since the program starts at 65","Pat is eligible, since the program starts at 55","Pat is eligible, but only with a doctor's note","Pat is too young, since it is for drivers over 70"],"correct":1},{"id":"q-5a-015","fact_id":"s13-006","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of age and length matches the Mature Driver Improvement Program?","options":["Age 65 and older, 8 hours","Age 55 and older, 16 hours","Age 55 and older, 3 hours","Age 55 and older, 8 hours"],"correct":3},{"id":"q-5a-016","fact_id":"s13-008","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which of these is a warning sign that a driver's ability may be shrinking?","options":["Feeling stiff after a long day behind the wheel","Needing reading glasses to make out small print on labels","Finding dents on the car with no idea how they got there","Turning the radio down to focus in heavy traffic"],"correct":2},{"id":"q-5a-017","fact_id":"s13-008","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Walt drove to the pharmacy he has used for ten years and ended up in an unfamiliar part of town. Last month he also had two near misses. What should Walt and his family take from this?","options":["A run of bad luck, since near misses happen to every driver","A pattern of signs that needs a closer look","Normal tiredness that a good night of sleep should fix","A sign that he must stop driving for good, starting this week"],"correct":1},{"id":"q-5a-018","fact_id":"s13-008","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which of these is more likely to be a sign that a driver's ability is slipping?","options":["Needing a moment to adjust the seat in a borrowed car","Stopping to rest after two hours of driving","Getting lost twice on streets near the driver's own home","Choosing to avoid driving during rush hour"],"correct":2},{"id":"q-5a-019","fact_id":"s13-009","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What does the handbook say about dementia and the ability to drive safely over time?","options":["Medical care lets the person keep driving safely for life","Safe driving ends once the person reaches about age 80","Safe driving is lost eventually, whatever treatment is given","Driving only short trips on familiar roads removes the risk"],"correct":2},{"id":"q-5a-020","fact_id":"s13-009","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Lena's father has dementia and takes his medicine faithfully. He asks if that means he can drive as long as he likes. What should Lena tell him?","options":["Treatment will not stop the eventual loss of safe driving","Medicine holds off the decline, so he can drive until a checkup","He is safe so long as someone rides along with him","Driving only near home keeps the risk low enough"],"correct":0},{"id":"q-5a-021","fact_id":"s13-009","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Sam says good treatment means a parent with dementia can drive for many more years. Kim disagrees. Who matches the handbook?","options":["Sam, since good treatment can fully stop the decline","Sam, since the parent can drive until the illness is severe","Kim, but only if the parent also drives at night","Kim, since the condition keeps progressing"],"correct":3},{"id":"q-5a-022","fact_id":"s5-01","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which ability do you rely on to read road signs and spot hazards in changing light?","options":["Clear vision","Good hearing","Good balance","Fast reflexes"],"correct":0},{"id":"q-5a-023","fact_id":"s5-01","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At dusk you notice you cannot read a road sign until you are almost under it. What does this mean for your driving?","options":["Your hearing may be the real problem here, not your eyes","Signs can be hard to read at dusk, so you can ignore it","Your vision may be too weak to catch signs in time","Your dashboard lights may be too bright for you"],"correct":2},{"id":"q-5a-024","fact_id":"s5-01","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair correctly matches a driver's need with the ability behind it?","options":["Reading signs needs hearing; spotting sirens needs vision","Reading signs needs vision; spotting sirens needs reaction time","Reading signs needs vision; noticing sirens needs hearing","Reading signs needs reaction time; noticing sirens needs hearing"],"correct":2},{"id":"q-5a-025","fact_id":"s5-02","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is adequate hearing needed for while driving?","options":["Reading road signs","Judging your gap to the car ahead","Feeling the road surface","Noticing horns and sirens"],"correct":3},{"id":"q-5a-026","fact_id":"s5-02","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A driver with hearing loss in both ears wants to keep driving. Which danger does that raise most directly?","options":["Missing a horn or siren that warns of danger","Misreading a stop sign from far away","Overlooking a car in the blind spot","Misjudging how far away a car is"],"correct":0},{"id":"q-5a-027","fact_id":"s5-02","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver says mirrors can replace good hearing. Which reply fits the handbook?","options":["Yes, mirrors show where every siren is coming from","Yes, if you check the mirrors every few seconds","No for sirens, but mirrors are enough for horns","No, hearing catches horns and sirens that mirrors miss"],"correct":3},{"id":"q-5a-028","fact_id":"s5-03","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How does being tired change your driving ability?","options":["It slows your reactions but leaves your vision sharp","It blurs your vision and slows your reaction time","It makes you miss sounds but not sights","It has no effect until you actually fall asleep"],"correct":1},{"id":"q-5a-029","fact_id":"s5-03","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"After a long night shift, Omar drives home with heavy eyelids. Which risk is higher for him than on a rested day?","options":["Hearing a siren less clearly than usual","Reacting late to a hazard that looks blurry","Brakes that take longer to grab","Finding it harder to steer at the 9 and 3 positions"],"correct":1},{"id":"q-5a-030","fact_id":"s5-03","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A tired driver says, \\"I can see the road fine, so my reactions are not affected.\\" What is wrong with that thinking?","options":["Nothing is wrong, since clear vision is what matters most when driving","Fatigue also dulls hearing, but reactions stay as quick as ever","Fatigue also slows reaction time, so seeing well is not enough","Fatigue matters only after several hours of nonstop driving"],"correct":2},{"id":"q-5a-031","fact_id":"s5-04","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which statement about over-the-counter medicines and driving is right?","options":["They can impair driving, just like prescribed medicines","They are safe to drive on, since stores sell them freely","They can affect driving only when mixed with alcohol","They must never be taken by anyone who drives"],"correct":0},{"id":"q-5a-032","fact_id":"s5-04","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You took a cold tablet from a store shelf, and now you need to drive to work. What should you think?","options":["It is safe, since you needed no prescription to buy it","It can still impair your driving, even without a prescription","Drowsiness comes only from prescribed drugs, so you are fine","It impairs your driving only if you also drink alcohol"],"correct":1},{"id":"q-5a-033","fact_id":"s5-04","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Dev says store-bought remedies are safer to drive on than prescribed ones. What is the right view?","options":["Store-bought kinds are mild, so they are safe to drive on","Neither kind is automatically safe to drive on","Prescribed kinds are safer, since a doctor checked them","Prescribed kinds can impair you, but store-bought kinds never do"],"correct":1},{"id":"q-5a-034","fact_id":"s5-05","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"Who must report patients whose medical conditions affect their driving safety?","options":["Employers","Physicians","Family members","Insurance agents"],"correct":1},{"id":"q-5a-035","fact_id":"s5-05","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"A physician treats a 15-year-old and a 12-year-old, both with conditions that make driving unsafe. Whom must the physician report?","options":["Only the 15-year-old","Only the 12-year-old","Both of them","Neither, since reports start at 16"],"correct":0},{"id":"q-5a-036","fact_id":"s5-05","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Which pair of ages is right: physician reporting starts at one, and the Mature Driver Improvement Program starts at the other?","options":["Reporting at 55; program at 14","Reporting at 16; program at 65","Reporting at 16; program at 55","Reporting at 14; program at 55"],"correct":3},{"id":"q-5a-037","fact_id":"s5-06","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which hand placements does the handbook give for hand-to-hand steering?","options":["Hands at 9 and 3 o'clock, or at 8 and 4 o'clock","Hands at 10 and 2 o'clock, or at 11 and 1 o'clock","One hand at 12 o'clock and the other at 6 o'clock","Hands at 9 and 3 o'clock only, never lower on the wheel"],"correct":0},{"id":"q-5a-038","fact_id":"s5-06","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Maya's seat is low and her arms feel cramped with her hands at 9 and 3. Which other placement is still inside the handbook's guidance?","options":["Hands at 10 and 2 o'clock","Hands at 11 and 1 o'clock","Hands at 7 and 5 o'clock","Hands at 8 and 4 o'clock"],"correct":3},{"id":"q-5a-039","fact_id":"s5-06","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement is true of hand-to-hand steering, as opposed to hand-over-hand steering?","options":["One hand crosses over the other to turn the wheel faster","Your hands stay near 9 and 3 o'clock, or 8 and 4 o'clock","It is the technique to use for parking and skid recovery","Your hands stay at 10 and 2 o'clock and never leave those spots"],"correct":1},{"id":"q-5a-040","fact_id":"s5-07","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"For which tasks is hand-over-hand steering the right technique?","options":["Lane changes, merging, and following a gentle curve","Low-speed turns, parking, and recovering from a skid","Freeway cruising, long gentle curves, and passing","Driving in a straight line on a quiet road"],"correct":1},{"id":"q-5a-041","fact_id":"s5-07","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your car begins to skid on a wet curve and you must steer quickly. Which technique is meant for this moment?","options":["Hand-over-hand steering, crossing one hand over the other","Hand-to-hand steering, with your hands kept at 9 and 3","One-hand steering from the top of the wheel, keeping the other hand free","Small, light corrections with both hands kept still at 8 and 4"],"correct":0},{"id":"q-5a-042","fact_id":"s5-07","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair correctly matches each steering style with where it belongs?","options":["Hand-over-hand for parking and skids; hand-to-hand for normal driving","Hand-over-hand for freeway driving; hand-to-hand for parking and skids","Hand-over-hand for passing; hand-to-hand for tight low-speed turns","Hand-over-hand for gentle curves; hand-to-hand for backing up"],"correct":0},{"id":"q-5a-043","fact_id":"s5-08","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When is steering with one hand acceptable?","options":["Only when you turn while backing up or use a vehicle control","On a straight, empty road where nothing seems to be happening","Any time you feel confident enough about your control of the car","While eating or drinking, if you have a free moment"],"correct":0},{"id":"q-5a-044","fact_id":"s5-08","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On a straight, empty road you want to sip coffee with one hand. What follows the handbook?","options":["Steer with one hand, since the road ahead is empty","Keep both hands on, as you are not backing or using a control","Slow below 25 mph first, and then one hand is fine","One hand works if the coffee lid is fastened on tight"],"correct":1},{"id":"q-5a-045","fact_id":"s5-08","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Lee takes a hand off the wheel to switch on the wipers. Ray takes a hand off to wave at a friend. Whose one-handed steering fits the handbook?","options":["Ray's, since a wave only takes a second","Lee's, since he is operating a vehicle control","Ray's, since a wave is a polite signal to others","Neither, since both hands must stay on the wheel every moment"],"correct":1},{"id":"q-5a-046","fact_id":"s5-12","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Headlights are needed when visibility drops below which distance?","options":["1,000 feet","500 feet","2,000 feet","100 feet"],"correct":0},{"id":"q-5a-047","fact_id":"s5-12","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"The sun has just set and the sky is dim blue. You are on a flat city street, the road is dry, and streetlights are on. What about your headlights?","options":["Turn them on, since dusk is a time for headlights","Wait until the sky is fully dark before switching them on","Rely on the streetlights, which already light your path","Switch on your parking lights until it is darker"],"correct":0},{"id":"q-5a-048","fact_id":"s5-12","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which of these is NOT a situation that calls for headlights?","options":["A mountain road during the middle of a sunny day","A clear, bright noon on a flat road with good visibility","Heavy rain, thick fog or other bad weather conditions","Twilight on a busy city street with traffic around"],"correct":1},{"id":"q-5a-049","fact_id":"s5-13","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Your vehicle has trouble while you drive. What does the handbook say to do?","options":["Stop where you are, right in the lane, to stay visible","Flash your high beams at traffic and keep on driving","Turn on emergency flashers and pull off the road if you can","Slow to a crawl in your lane and keep going to a repair shop"],"correct":2},{"id":"q-5a-050","fact_id":"s5-13","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your car starts to lose power on a two-lane road. Ahead you can see a blind curve, a hill crest and a straight, flat stretch. Where do you stop?","options":["Right where you are, in your lane, with flashers on","On the hill crest, with flashers on, so drivers on both sides see you","Off the road on the flat straight stretch, with flashers on","At the bend in the curve, with flashers on, so others notice you sooner"],"correct":2},{"id":"q-5a-051","fact_id":"s5-13","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which response follows the handbook after your vehicle develops trouble on the road?","options":["Flashers on, then pull off the road if you can","Flashers on, then stop on the nearest hill so you stand out","Turn signal on, then stop right where you are","High beams flashing, then pull over at the nearest curve"],"correct":0},{"id":"q-5a-052","fact_id":"s5-14","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"While you wait for help after vehicle trouble, what should you do?","options":["Stay in your vehicle until help arrives","Get out and stand behind the car so others notice you","Flag down passing drivers to ask for a ride","Walk along the shoulder to the next exit"],"correct":0},{"id":"q-5a-053","fact_id":"s5-14","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your car quits on a rural road. Your phone says a tow truck is 30 minutes away. What is your best move?","options":["Walk back along the road to meet the tow truck","Stay in the car with the flashers on until it arrives","Stand out in the road to wave the tow truck down","Wait outside the car, leaning against the back door"],"correct":1},{"id":"q-5a-054","fact_id":"s5-14","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A friend says to stand behind your car on the shoulder while you wait for a tow. What does the handbook advise instead?","options":["Stay in the vehicle until help arrives","Walk well ahead of the car and wait there","Sit on the guardrail beside the road","Stand next to the driver's door, facing traffic"],"correct":0},{"id":"q-5a-055","fact_id":"s6-22","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"By law, how far before a right turn must your signal already be on?","options":["At least 100 feet","At least 50 feet","At least 75 feet","At least 25 feet"],"correct":0},{"id":"q-5a-056","fact_id":"s6-22","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are cruising at 35 mph and your street is coming up on the right. A passenger asks when to switch on the signal. What do you say?","options":["For the last 25 feet before the corner","For the last 50 feet before the corner","For the last 100 feet before the corner","From the moment your front tires reach the crosswalk line"],"correct":2},{"id":"q-5a-057","fact_id":"s6-22","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for two rules: the turn-signal gap and the following gap?","options":["Signal 100 feet before the turn; follow by a three-second gap","Signal three seconds before the turn; follow by 100 feet","Signal 200 feet before the turn; follow by a three-second gap","Signal 100 feet before the turn; follow by three car lengths"],"correct":0},{"id":"q-5a-058","fact_id":"s6-23","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Before a left turn, your signal has to be flashing for at least which stretch?","options":["The last 100 feet before the turn","The last 30 feet before the turn","The last 75 feet before the turn","The last 50 feet before the turn"],"correct":0},{"id":"q-5a-059","fact_id":"s6-23","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A friend says you can switch on the left signal when you reach the intersection and start turning. What is the problem with that?","options":["There is no problem if no car is behind you","The signal should be on for the last 100 feet before turning","The signal belongs only at intersections with traffic lights","The signal should come on about 25 feet before the turn"],"correct":1},{"id":"q-5a-060","fact_id":"s6-23","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement about signal distance for left turns and right turns is right?","options":["Left turns need 200 feet and right turns need only 100","Both turns need the signal on for the last 100 feet","Right turns need 100 feet and left turns need only 50","Both turns need the signal on for the last 50 feet"],"correct":1},{"id":"q-5a-061","fact_id":"s6-24","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"While you wait for a gap to make a left turn, where should your front wheels point?","options":["Straight ahead, until it is safe to start the turn","Fully turned left, ready to go the moment a gap opens","Turned slightly left, so you start the turn sooner","Turned right, to stay clear of oncoming cars"],"correct":0},{"id":"q-5a-062","fact_id":"s6-24","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You sit in the left-turn lane with your wheels already turned left to save time. What is the best advice?","options":["Keep them as they are, since you will need that angle soon","Straighten them and begin turning only when it is safe","Ease them halfway back, so you are partly ready","Hold them left but keep your foot hard on the brake"],"correct":1},{"id":"q-5a-063","fact_id":"s6-24","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"While you wait to turn left at an intersection, which combination is right for your signal and your front wheels?","options":["Left signal off, wheels pointed left","Left signal on, wheels pointed left","Left signal off, wheels pointed straight ahead","Left signal on, wheels pointed straight ahead"],"correct":3},{"id":"q-5a-064","fact_id":"s6-27","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"On a residential street, how far must you be able to see in each direction before a U-turn?","options":["At least 200 feet","At least 100 feet","At least 150 feet","At least 50 feet"],"correct":0},{"id":"q-5a-065","fact_id":"s6-27","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On a quiet residential street you want to make a U-turn. You can see about 250 feet to the right but only 100 feet to the left, past a bend. What do you do?","options":["Go now, since the view on the right is over 200 feet","Make the turn, as the average of both views tops 200 feet","Wait or pick a spot where you can see 200 feet each way","Wait for the left view to clear to 150 feet, then turn"],"correct":2},{"id":"q-5a-066","fact_id":"s6-27","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair of distances is right: the turn-signal run before a turn, and the clear view needed for a residential U-turn?","options":["Signal 200 feet; U-turn view 100 feet","Signal 100 feet; U-turn view 100 feet","Signal 100 feet; U-turn view 500 feet","Signal 100 feet; U-turn view 200 feet"],"correct":3},{"id":"q-5a-067","fact_id":"s6-31","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"On a two-lane undivided road, how many vehicles lined up behind you require you to use a turnout?","options":["Five or more","Three or more","Ten or more","Two or more"],"correct":0},{"id":"q-5a-068","fact_id":"s6-31","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive a camper slowly up a two-lane undivided mountain road. Six cars are stacked behind you and a turnout is ahead. What should you do?","options":["Pull into the turnout and let the line pass","Stay put, since you are under the speed limit","Speed up beyond the limit to clear the line","Wave them to pass you on the shoulder"],"correct":0},{"id":"q-5a-069","fact_id":"s6-31","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"In which situation must a slow driver pull into a turnout?","options":["A slow driver on a six-lane freeway with five cars behind","A slow driver on a divided highway with a median and six cars behind","A slow driver on a two-lane undivided road with three cars behind","A slow driver on a two-lane undivided road with five cars behind"],"correct":3},{"id":"q-5a-070","fact_id":"s6-33","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which way of passing another vehicle is never allowed?","options":["Driving off the paved part of the road to get around","A pass on the left after checking for oncoming cars","Moving up on the right of a car waiting to turn left","A pass in a clear zone marked by a dashed center line"],"correct":0},{"id":"q-5a-071","fact_id":"s6-33","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A truck ahead is stopped to turn left on a two-lane road with a double yellow center line. A wide dirt shoulder lies to the right. What should you do?","options":["Use the dirt shoulder to go around when the road is clear","Honk to make the truck driver clear the lane for you","Stay on the pavement and wait behind it until it turns","Cross the double yellow line and pass it on the left"],"correct":2},{"id":"q-5a-072","fact_id":"s6-33","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement about the area beside the paved road is right?","options":["Both pulling off for a turnout and passing on the shoulder are allowed","A slow driver may use a turnout, but nobody may pass off the pavement","A slow driver must stay in the lane, but a passer may use a turnout","A passer may use the shoulder, but a slow driver may not use a turnout"],"correct":1},{"id":"q-5a-073","fact_id":"s6_p11_roadway-043","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How do you check your blind spot before you change lanes?","options":["Glance at the rearview mirror and then move over","Rely on your side mirrors, tilted a little outward","Signal early and let the driver beside you make room","Look over your shoulder toward the lane you want"],"correct":3},{"id":"q-5a-074","fact_id":"s6_p11_roadway-043","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You signal to move one lane right on a busy road. Your mirrors look clear. What should you do before you steer over?","options":["Speed up so any hidden car is left behind","Move over, since the mirrors show an empty lane","Turn your head and look over your right shoulder","Flash your headlights and then slide across"],"correct":2},{"id":"q-5a-075","fact_id":"s6_p11_roadway-043","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"For which of these moves does the handbook call for a shoulder check of your blind spots?","options":["Changing lanes, turning, and parking","Changing lanes only, since turns and parking happen at low speed","Changing lanes, turning, and stopping at red lights","Turning and parking, but not changing lanes"],"correct":0},{"id":"q-5a-076","fact_id":"s6_p11_roadway-044","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When winter weather turns cold, which part of the road tends to freeze before the rest?","options":["Tunnel floors","Roads running through town","Bridges and overpasses","Roads at the top of a hill"],"correct":2},{"id":"q-5a-077","fact_id":"s6_p11_roadway-044","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"The air is just above freezing and the road is wet. You are about to cross an overpass. What should you expect?","options":["The overpass is warmer, being closer to the sun","It is just like the road, so drive on as usual","Ice only if snow has fallen within the last hour","Ice may form on the overpass before the road itself"],"correct":3},{"id":"q-5a-078","fact_id":"s6_p11_roadway-044","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"On a cold, wet morning, which freezes first: the regular road or the bridge ahead?","options":["Both freeze at the same moment, since the air is equally cold over each","The bridge, since bridges and overpasses freeze before regular roads","The regular road, since the bridge is the last place to freeze","Neither, until snow actually falls and covers the bridge"],"correct":1},{"id":"q-5a-079","fact_id":"s6_p11_run2-022","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When should you use your fog lights?","options":["Whenever there is rain or drizzle","Any time you are driving after dark","As daytime running lights on bright days","Only when visibility is severely limited"],"correct":3},{"id":"q-5a-080","fact_id":"s6_p11_run2-022","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drove through thick fog with your fog lights on, and now the fog has lifted so you can see far down the road. What do you do?","options":["Leave them on so other drivers see you more easily","Switch to your high beams, now that you can see farther","Turn the fog lights off now that conditions are better","Leave them on, since they sit lower than headlights"],"correct":2},{"id":"q-5a-081","fact_id":"s6_p11_run2-022","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"One driver leaves fog lights on all evening because the sky is cloudy. Another switches them off once the fog clears. Who follows the handbook?","options":["The first, since cloudy skies need extra lights","The first, since fog lights are safest when left on","Neither, since fog lights are meant to stay on all night","The second, since fog lights suit severe fog only"],"correct":3},{"id":"q-5a-082","fact_id":"s6_p11_run2-023","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"Which lights must you use when you drive at night?","options":["Parking lights","Fog lights","Headlights","Hazard flashers"],"correct":2},{"id":"q-5a-083","fact_id":"s6_p11_run2-023","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"On a dim road at night you notice you have been driving with only your parking lights on, thinking it saves the battery. What should you do?","options":["Keep them on as long as you stay under 25 mph on the road","Switch to headlights, as parking lights alone are illegal","Add the fog lights and keep going the same way as before","Keep them on, since the street already has its own lights"],"correct":1},{"id":"q-5a-084","fact_id":"s6_p11_run2-023","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Which statement about lights for night driving is right?","options":["Parking lights alone are enough on a street with streetlights","Headlights are required at night, and only high beams count","Headlights are required at night; parking lights alone are illegal","Fog lights alone are enough on a clear night with little traffic"],"correct":2},{"id":"q-5a-085","fact_id":"s6b-15","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the least extra length a parallel-parking space should have beyond your vehicle?","options":["1 foot","2 feet","3 feet","6 feet"],"correct":2},{"id":"q-5a-086","fact_id":"s6b-15","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your car is 15 feet long. What is the shortest parallel-parking space the handbook says to look for?","options":["15 feet, matching your car's length","17 feet, with two feet to spare","18 feet, with three feet to spare","20 feet, with five feet to spare"],"correct":2},{"id":"q-5a-087","fact_id":"s6b-15","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for parallel parking space and following gap?","options":["Space 3 feet longer; following gap 3 feet","Space 3 seconds longer; following gap 3 feet","Space 3 feet longer; following gap 3 seconds","Space 3 car lengths; following gap 3 seconds"],"correct":2},{"id":"q-5a-088","fact_id":"s6b-16","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When you park where there is no curb, which way should the front wheels point?","options":["Toward the left side of the road","Toward the right side of the road","Straight ahead","Toward the center of the road"],"correct":1},{"id":"q-5a-089","fact_id":"s6b-16","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You park on a quiet country lane with no curb. Which wheel position follows the handbook?","options":["Turned left, toward the middle of the lane, for an easy start","Straight ahead, as you would for any other parking","Turned left only if you face downhill","Turned right, toward the edge of the road"],"correct":3},{"id":"q-5a-090","fact_id":"s6b-16","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for wheel position when parked with no curb, and when waiting to turn left?","options":["No curb: left; waiting to turn left: straight","No curb: straight; waiting to turn left: left","No curb: right; waiting to turn left: straight","No curb: right; waiting to turn left: right"],"correct":2},{"id":"q-5a-091","fact_id":"s7-19","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When should you use your signal in a roundabout?","options":["Just as you first enter the roundabout","Not at all, since a roundabout has no real turns","Only when you exit, never inside the circle itself","Before moving between lanes inside it, and when you exit"],"correct":3},{"id":"q-5a-092","fact_id":"s7-19","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are in the inside lane of a two-lane roundabout. Your exit is coming up on the right, so you must move to the outer lane. What should you do?","options":["Move across with no signal, since everyone is circling","Signal right after you leave the roundabout","Signal to change lanes, and signal again as you exit","Signal at the exit, but skip it for the lane change"],"correct":2},{"id":"q-5a-093","fact_id":"s7-19","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"One driver signals only at the exit of a roundabout. Another also signals when moving between its lanes. Who follows the handbook?","options":["The second, who signals lane moves and the exit","The first, since lane moves in a circle need no signal","The first, since extra signals confuse other drivers","The second, but only when traffic is heavy"],"correct":0},{"id":"q-5a-094","fact_id":"s7-22","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A pedestrian in a crosswalk is crossing slowly. What should you do?","options":["Tap the horn lightly to hurry them along","Stay calm and never honk at or harass them","Steer around behind them as soon as there is room","Flash your high beams to get them moving"],"correct":1},{"id":"q-5a-095","fact_id":"s7-22","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are stopped at a crosswalk while an older man crosses slowly. The driver behind you starts honking. What do you do?","options":["Honk back at the driver behind you","Edge forward so that he walks faster","Wave him back to the curb so traffic can go","Stay calm and wait for him to finish"],"correct":3},{"id":"q-5a-096","fact_id":"s7-22","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Jo stops with her car in the middle of a crosswalk and honks to clear a path. Which statement about her actions is right?","options":["Her honking at the walkers is wrong, but her stop is fine","Her stop on the crosswalk is wrong, but honking is fine","Both her stop there and her honking are wrong","Her stop and honk are fine, since she got there first"],"correct":2},{"id":"q-5a-097","fact_id":"s7-23","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When you must stop at a marked crosswalk, where should your car stop?","options":["Behind the line, leaving the crosswalk clear","With its front wheels on the crosswalk lines","Halfway into the crosswalk, to stay visible","Just past the crosswalk, in the intersection"],"correct":0},{"id":"q-5a-098","fact_id":"s7-23","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your light turns yellow and traffic ahead has stopped. You could roll forward so the car sits partly over the crosswalk. What do you do?","options":["Creep into the crosswalk to be first away","Stop in the middle of it, with flashers on","Close up tight behind the car ahead, even over the crosswalk","Stop behind the line and keep the crosswalk clear"],"correct":3},{"id":"q-5a-099","fact_id":"s7-23","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Two cars wait at a red light. Car A stops with its nose before the crosswalk lines. Car B stops with its nose in the middle of the crosswalk. Which one follows the rule?","options":["Car B, since it is closer to the light and gets away sooner","Car A, since the crosswalk stays open for pedestrians","Car B, since its nose in the crosswalk makes it easier to see","Neither, since cars must stop beyond the crosswalk"],"correct":1},{"id":"q-5a-100","fact_id":"s7_p11_roadway-011","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Road crews are working beside the lane. If you drive over the posted limit there, how does the law treat it?","options":["As allowed, if no worker is in sight at that moment","As a violation when it happens after dark","As presumed to break the basic speed law","As a breach once a crash has followed"],"correct":2},{"id":"q-5a-101","fact_id":"s7_p11_roadway-011","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A highway crew works beside the road. The posted limit is 45 mph, traffic flows at 55, and your lane looks empty. What speed fits the law?","options":["At or under 45 mph; over it is presumed unlawful","Match the speed of the other cars, at 55 mph","Go to 55 mph if no worker is close to the road","Add a small margin and hold at about 50 mph"],"correct":0},{"id":"q-5a-102","fact_id":"s7_p11_roadway-011","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing sorts these rules correctly: not going over the posted limit by a work crew, and slowing 5 to 10 mph on wet roads?","options":["Work crew limit: advice only; wet roads: law","Both are laws, each with a fixed fine","Both are advice, and neither has legal weight","Work crew limit: law; wet roads: safe-driving advice"],"correct":3},{"id":"q-5a-103","fact_id":"s7_p11_roadway-012","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"On wet roads, by how much does the handbook say to reduce your speed?","options":["By half","By 5 to 10 mph","By 1 or 2 mph","By 20 to 25 mph"],"correct":1},{"id":"q-5a-104","fact_id":"s7_p11_roadway-012","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are driving at 60 mph on a freeway in steady rain. About what speed does the handbook's guidance point to?","options":["About 30 mph, which is half of normal","About 65 mph, to leave the rain sooner","About 50 to 55 mph","60 mph, since the rain is not heavy"],"correct":2},{"id":"q-5a-105","fact_id":"s7_p11_roadway-012","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Dev says to cut your speed in half on wet roads, as you would on snow. Mia says to cut it by 5 to 10 mph. Who matches the handbook?","options":["Mia, since half speed is for packed snow","Dev, since wet roads are as bad as snow","Dev, since half speed is safest on any wet surface","Mia, but only when the rain is heavy"],"correct":0},{"id":"q-5a-106","fact_id":"s7_p11_roadway-013","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How should you change your speed when you drive on packed snow?","options":["Cut it by 5 to 10 mph","Cut it to 5 mph","Keep your usual speed and use a low gear","Cut it to half of normal"],"correct":3},{"id":"q-5a-107","fact_id":"s7_p11_roadway-013","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"The usual speed on a road is 40 mph, but it is covered with packed snow. Which speed fits the guidance?","options":["About 5 mph, as on ice","About 20 mph","About 40 mph, with chains on","About 30 to 35 mph, as on a wet road"],"correct":1},{"id":"q-5a-108","fact_id":"s7_p11_roadway-013","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of road surface and speed advice is correct?","options":["Packed snow: 5 mph; ice: half normal speed","Packed snow: 5 to 10 mph less; ice: half normal speed","Packed snow: half normal speed; ice: 5 mph","Packed snow: half normal speed; ice: 5 to 10 mph less"],"correct":2},{"id":"q-5a-109","fact_id":"s7_p11_roadway-014","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What top speed does the handbook give for driving on ice?","options":["5 mph","15 mph","25 mph","Half your normal speed"],"correct":0},{"id":"q-5a-110","fact_id":"s7_p11_roadway-014","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You turn onto a road glazed with ice while your speedometer reads 25 mph. What should you do?","options":["Hold 25 mph, since it is below the usual limit","Slow to about 15 mph and hold it","Brake hard to stop at once","Slow down to about 5 mph"],"correct":3},{"id":"q-5a-111","fact_id":"s7_p11_roadway-014","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing is right: top speed on ice, and top speed when visibility drops under 100 feet?","options":["Ice: 30 mph; low visibility: 5 mph","Ice: 5 mph; low visibility: 30 mph","Ice: 5 mph; low visibility: 5 mph","Ice: 30 mph; low visibility: 30 mph"],"correct":1},{"id":"q-5a-112","fact_id":"s7_p11_roadway-015","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Fog, rain or snow cuts your view to under 100 feet. What speed does the handbook say not to exceed?","options":["15 mph","45 mph","30 mph","55 mph"],"correct":2},{"id":"q-5a-113","fact_id":"s7_p11_roadway-015","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Thick fog limits your view to about 80 feet. The posted limit is 55 mph. What top speed fits the handbook?","options":["30 mph","55 mph, since that is posted","45 mph, a 10 mph cut from the posted limit","5 mph, as on ice"],"correct":0},{"id":"q-5a-114","fact_id":"s7_p11_roadway-015","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing is right: the visibility distance that caps your speed at 30 mph, and the one that calls for headlights?","options":["Speed cap: under 1,000 feet; headlights: under 100 feet","Speed cap: under 100 feet; headlights: under 100 feet","Speed cap: under 1,000 feet; headlights: under 1,000 feet","Speed cap: under 100 feet; headlights: under 1,000 feet"],"correct":3},{"id":"q-5a-115","fact_id":"s7_p11_roadway-016","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which headlight setting does the handbook give for driving in rain?","options":["High beams, so you can see farther ahead","Low beams, which cut glare and reflection","Hazard flashers, so others see you through the rain","Parking lights, to avoid any reflection"],"correct":1},{"id":"q-5a-116","fact_id":"s7_p11_roadway-016","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Rain is falling on a dark country road, and you switch to high beams to see farther. What should you do?","options":["Keep them, since rain hides the other lights","Keep them on, but slow down a little to be safe","Switch to low beams to cut the glare off rain","Switch to parking lights only, to cut glare"],"correct":2},{"id":"q-5a-117","fact_id":"s7_p11_roadway-016","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement is true of high beams in rain and in fog?","options":["In both, high beams cause glare, so use low beams","High beams are best in rain; low beams are best in fog","Low beams are best in rain; high beams are best in fog","In both, high beams help because they reach farther"],"correct":0},{"id":"q-5a-118","fact_id":"s7_p11_roadway-017","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which headlights does the handbook say to use in fog or heavy smoke?","options":["High beams and low beams together","High beams for more reach","No headlights, to cut the glare","Low beams only"],"correct":3},{"id":"q-5a-119","fact_id":"s7_p11_roadway-017","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Smoke from a brush fire drifts across a highway and you can see about 40 feet. Which lights should you use?","options":["High beams, so others see you from far away","Low beams only","Hazard flashers alone","Parking lights, so you are seen without glare"],"correct":1},{"id":"q-5a-120","fact_id":"s7_p11_roadway-017","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Dan switches to high beams in thick fog to see farther. Eva uses low beams. Who is right, and why?","options":["Dan, since high beams cut through fog","Dan, since seeing farther lets him react sooner","Eva, since high beams cause dangerous glare in fog","Eva, but only when other cars are close"],"correct":2},{"id":"q-5a-121","fact_id":"s7_p11_roadway-018","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What should you do when your car starts to hydroplane?","options":["Slow down gradually and avoid sudden braking","Brake hard to stop as fast as possible","Hold your speed steady until the tires grip again","Pump the brakes quickly several times to slow down"],"correct":0},{"id":"q-5a-122","fact_id":"s7_p11_roadway-018","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You hit a wide puddle at speed and the steering feels light as the car floats. What do you do first?","options":["Brake firmly to stop the car right away","Turn the wheel to the right to correct the float","Turn the wheel gently back and forth to find grip","Ease off the gas and slow without slamming brakes"],"correct":3},{"id":"q-5a-123","fact_id":"s7_p11_roadway-018","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Two cars begin to hydroplane. Sam brakes hard. Tia takes her foot off the gas and slows gradually. Who follows the handbook?","options":["Sam, since braking is the fastest way to stop","Tia, since sudden braking can cost you control","Sam, since a hard stop gets you off the water sooner","Tia, but only if she also steers hard to one side"],"correct":1},{"id":"q-5b-001","fact_id":"s7_p11_roadway-019","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How should your following distance change when you drive in thick fog?","options":["Keep the same gap that you use on a clear day","Leave extra room to stop within what you can see","Close the gap and steer by the tail lights ahead","Leave less room, since you are driving slower"],"correct":1},{"id":"q-5b-002","fact_id":"s7_p11_roadway-019","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Fog rolls onto a coastal highway and you can see only a few car lengths ahead. What do you do about the car in front of you?","options":["Stay close so you do not lose sight of its tail lights","Pass it to reach clearer road before the fog thickens","Keep your gap and flash your high beams for more room","Drop back until you could stop within the distance you can see"],"correct":3},{"id":"q-5b-003","fact_id":"s7_p11_roadway-019","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair of habits is right for dense fog?","options":["A bigger gap, with low-beam headlights","A bigger gap, with high-beam headlights","Your usual gap, with low-beam headlights","A smaller gap, with parking lights only"],"correct":0},{"id":"q-5b-004","fact_id":"s7_p11_roadway-020","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A strong crosswind is pushing your car sideways. What is the right response?","options":["Speed up to get through the gusts quickly","Loosen your grip so the car can drift with the wind","Hold the wheel firmly and slow down","Steer hard into the wind and brake sharply"],"correct":2},{"id":"q-5b-005","fact_id":"s7_p11_roadway-020","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On an open stretch of highway, gusts keep shoving your car toward the next lane. What do you do?","options":["Grip lightly so the wheel does not jerk in your hands","Hold your speed and correct with quick one-handed tugs","Ease off the gas and keep both hands firm on the wheel","Brake hard each time a gust hits"],"correct":2},{"id":"q-5b-006","fact_id":"s7_p11_roadway-020","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing suits a very windy day?","options":["Firm grip and a lower speed","Firm grip and cruise control set","Loose grip and steady speed on cruise control","Loose grip and a higher speed to shorten the exposure"],"correct":0},{"id":"q-5b-007","fact_id":"s7_p11_roadway-021","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the rule for cruise control when the wind is very strong?","options":["Keep it on to hold an even speed in the gusts","Use it on straight stretches only","Use it only if you are towing a trailer","Leave it off and control your speed yourself"],"correct":3},{"id":"q-5b-008","fact_id":"s7_p11_roadway-021","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are pulling a camper trailer on a highway under a wind warning. Cruise control is on and holding 60 mph. What should you do?","options":["Leave it on; a steady speed keeps the trailer steady","Turn it off and control your speed with the pedal","Leave it on but keep your hands loose on the wheel","Turn it off and speed up to get through the wind sooner"],"correct":1},{"id":"q-5b-009","fact_id":"s7_p11_roadway-021","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A box-truck driver and a sedan driver both cross a windy bridge. Who should avoid cruise control?","options":["Both of them, with trucks and trailers the biggest concern","Only the sedan driver, since small cars get pushed around more by gusts","Neither, if the road is straight and dry","Only the truck driver, since trucks are taller"],"correct":0},{"id":"q-5b-010","fact_id":"s7_p11_roadway-027","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How far ahead of your car should you keep looking so you can spot hazards early?","options":["Only at the car directly in front of you","About 3 seconds of travel ahead","At least 10 seconds of travel ahead","About 6 seconds of travel ahead"],"correct":2},{"id":"q-5b-011","fact_id":"s7_p11_roadway-027","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive at 45 mph and only watch the bumper ahead. A ladder falls off a truck far up the road and you notice it late. Which habit would have given you more time?","options":["Checking your mirrors more often","Looking about 10 seconds ahead along the road","Fixing your eyes on one point to stay steady","Following the truck more closely to see around it"],"correct":1},{"id":"q-5b-012","fact_id":"s7_p11_roadway-027","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"What does the figure of '10 seconds' describe for a careful driver?","options":["How far down the road to look for hazards","The gap to leave behind the vehicle you follow","The most time you may take your eyes off the road"],"correct":0},{"id":"q-5b-013","fact_id":"s7_p11_run2-021","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A flagger in a work zone signals you. What must you do?","options":["Treat it as a suggestion and use your own judgment","Obey it the way you obey a traffic light","Obey it only if a patrol car is also there","Follow the posted signs, since they outrank a person"],"correct":1},{"id":"q-5b-014","fact_id":"s7_p11_run2-021","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Approaching a road crew, you see a flagger hold up a STOP paddle, yet the road ahead looks empty. What do you do?","options":["Roll through slowly since the lane is clear","Stop only if cars are coming the other way","Slow down and go if no workers are in your lane","Stop and wait until the flagger lets you go"],"correct":3},{"id":"q-5b-015","fact_id":"s7_p11_run2-021","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which of these must you obey with the same force as a red light?","options":["A work zone flagger's stop signal","Another driver flashing headlights to let you go","A tow truck's flashing amber beacon","A pedestrian at the curb waving you on"],"correct":0},{"id":"q-5b-016","fact_id":"s7_p11_run2-023","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the rule on headlights during bright, clear daytime driving in California?","options":["They are required whenever the car is moving, as a safety rule","They are required on freeways only, because of the speeds","They are not required, though they make you easier to see","They are not required, and using them mostly wastes the bulbs"],"correct":2},{"id":"q-5b-017","fact_id":"s7_p11_run2-023","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"It is noon, the sky is clear, and your headlights are off. A passenger says the law requires them. What is accurate?","options":["She is right; a car in motion must show lights","She is right, but only on two-lane roads","She is wrong, though using them would help others see you","She is wrong, and using them in daylight would be a violation"],"correct":2},{"id":"q-5b-018","fact_id":"s7_p11_run2-023","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement about headlights is correct?","options":["Optional on a clear day; needed after dark","Required on a clear day; optional after dark","Optional both day and night","Required both day and night in every weather"],"correct":0},{"id":"q-5b-019","fact_id":"s7b-23","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the least space you must leave between your vehicle and a cyclist when you pass?","options":["3 feet","2 feet","1 foot","4 feet"],"correct":0},{"id":"q-5b-020","fact_id":"s7b-23","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are overtaking a cyclist on a quiet two-lane road. How much room must lie between your side mirror and the rider's elbow?","options":["Enough that you do not touch them","At least 3 feet","About a foot, if you slow down","At least 6 feet"],"correct":1},{"id":"q-5b-021","fact_id":"s7b-23","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"From which parts is the 3-foot passing gap measured?","options":["Any part of your car to any part of the bike or rider","The middle of your car to the middle of the bike or rider","Your tires to the bike's tires","Your front bumper to the rider's back wheel"],"correct":0},{"id":"q-5b-022","fact_id":"s7b-24","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A cyclist rides in your lane and the next lane in your direction is open. How must you pass?","options":["Stay in your lane and pass with extra room","Honk until the rider moves over, then pass","Change lanes first, then pass","Speed up and pass quickly before traffic builds"],"correct":2},{"id":"q-5b-023","fact_id":"s7b-24","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On a three-lane street, a cyclist rides in the right lane ahead of you and the middle lane is clear. What is your move?","options":["Squeeze by in the right lane, 3 feet from the rider","Check mirror, signal, move into the middle lane, then pass","Pass on the shoulder if there is room","Stay behind the rider until the light, then pass in the same lane"],"correct":1},{"id":"q-5b-024","fact_id":"s7b-24","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver leaves four feet while passing a cyclist but stays in the same lane although the next lane is empty. What is the problem?","options":["Nothing; four feet is more than the 3-foot minimum, so the pass was fine","Four feet is too little; the law asks for a full lane width","The driver should have slowed to the rider's speed and followed","Four feet is enough room, but the driver should have changed lanes"],"correct":3},{"id":"q-5b-025","fact_id":"s7b-27","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"At highway speed, how far can a large truck need to stop completely?","options":["About the same as a car, roughly 150 feet","Up to about 400 feet","Up to about 1,000 feet","Up to about 250 feet"],"correct":1},{"id":"q-5b-026","fact_id":"s7b-27","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You pull in about three car lengths ahead of a loaded truck on the freeway, then brake for slowing traffic. What is true about the truck behind you?","options":["Trucks stop faster than cars thanks to bigger brakes","Your brake lights are too low for a truck driver to notice in time","The truck driver sits high and will see you and stop easily","A truck can need up to 400 feet, so it may not stop in time"],"correct":3},{"id":"q-5b-027","fact_id":"s7b-27","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A truck and a car both travel at 55 mph. Which statement is right about stopping?","options":["The truck needs up to 400 feet, far more than the car","The truck needs less, since heavy vehicles grip the road better","Both need the same distance since speed is equal","The truck needs more only when the road is wet"],"correct":0},{"id":"q-5b-028","fact_id":"s7b-28","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What does the term 'No-Zone' mean around a large truck?","options":["Lanes where trucks are not allowed to drive","Stretches of road marked as no-passing","The blind areas around a truck","The gap a truck must leave behind other vehicles"],"correct":2},{"id":"q-5b-029","fact_id":"s7b-28","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are cruising beside a long truck, level with its rear wheels. What should you assume about the driver?","options":["The driver sees you in the big mirrors","The driver will honk if you get too close","The driver cannot see you from the cab","The driver cannot see you, but will slow to let you by"],"correct":2},{"id":"q-5b-030","fact_id":"s7b-28","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing is correct for a large truck?","options":["No-Zone: the blind areas; 400 feet: how far it can need to stop","No-Zone: how far it can need to stop; 400 feet: the size of the blind areas","No-Zone: a no-passing stretch; 400 feet: how far ahead to look","No-Zone and 400 feet both describe its stopping distance"],"correct":0},{"id":"q-5b-031","fact_id":"s7b-29","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How long should you stay beside a large truck when you pass it?","options":["Stay level with its cab until the driver sees you","Ride beside its trailer to save fuel in the draft","About 10 seconds","No longer than you need to get by"],"correct":3},{"id":"q-5b-032","fact_id":"s7b-29","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You have just passed a semi and want its lane back. Which move matches the advice?","options":["Pull in the moment your rear bumper has just cleared its cab","Pull in once there is a wide gap, never right at its bumper","Pull in, then flash your brake lights as a warning","Stay beside it until the trucker signals you through"],"correct":1},{"id":"q-5b-033","fact_id":"s7b-29","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"How does passing a large truck differ from passing a small car?","options":["Spend less time alongside and do not cut in tight in front","Stay alongside longer so that the driver can be sure to see you","No difference; pass it exactly as you would a small car","Pull in close ahead to show you have cleared"],"correct":0},{"id":"q-5b-034","fact_id":"s7c-11","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the closest you may stop to the nearest rail when a train is coming?","options":["5 feet","10 feet","15 feet","25 feet"],"correct":2},{"id":"q-5b-035","fact_id":"s7c-11","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At a crossing the red lights flash and a train is approaching. You are first in line. Where do you stop?","options":["At the tracks' edge so you can go the moment it passes","At least 15 feet from the nearest rail","About 5 feet back from the nearest rail","On the tracks if the gate arm is still up"],"correct":1},{"id":"q-5b-036","fact_id":"s7c-11","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which statement about stopping for a train signal is correct?","options":["Stop within 15 feet of the nearest rail, no farther, to be first across","Stop 15 feet away, then go as soon as the gates rise","Stop 15 feet away only for freight trains","Stop at least 15 feet from the nearest rail and proceed only when safe"],"correct":3},{"id":"q-5b-037","fact_id":"s7c-9","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Trees block your view down the tracks as you approach a crossing. What should you do?","options":["Keep your speed since no signal is flashing","Slow down and be ready to stop","Speed up to clear the tracks before a train appears","Honk to warn any train"],"correct":1},{"id":"q-5b-038","fact_id":"s7c-9","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At dusk on a rural road, you reach an unguarded crossing where brush hides the track in both directions. What do you do?","options":["Stop on the tracks to get a better view","Hold your speed, since the crossing sign shows no train is coming","Drive across in a low gear without slowing","Ease off the gas, look both ways and be ready to stop"],"correct":3},{"id":"q-5b-039","fact_id":"s7c-9","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"At which crossing is slowing and being ready to stop enough, rather than a full stop?","options":["Your view of the tracks is blocked and no signal is active","The gate arm is still up and the lights are flashing","A train horn sounds close by and the train is out of sight","The gate arm is lowered and no train is in sight"],"correct":0},{"id":"q-5b-040","fact_id":"s8-001","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the best way to use your eyes while driving along a busy street?","options":["Lock them on the bumper ahead of you","Glance up from the dashboard every so often","Keep them moving and look well down the road","Fix them on the hood to judge your lane position"],"correct":2},{"id":"q-5b-041","fact_id":"s8-001","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your eyes feel tired from staring at the road. A passenger says to just watch the car in front. What is the better habit?","options":["Watch only the car in front to avoid distractions","Keep looking at one far point without moving your eyes","Sweep your eyes from far ahead to the sides and the mirrors","Look at the road mainly when you hear a horn or a siren nearby"],"correct":2},{"id":"q-5b-042","fact_id":"s8-001","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"The advice says to look about 10 seconds ahead. How should you apply it?","options":["Keep your eyes moving while still reaching that far ahead","Look only at that point and ignore your mirrors and the sides","Look that far ahead only when you are on a freeway","Stare at one point about 10 seconds away"],"correct":0},{"id":"q-5b-043","fact_id":"s8-002","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"By how much should you lower your speed on wet pavement?","options":["Not at all, if you are under the limit","By about 1 to 2 mph","By about half","By about 5 to 10 mph"],"correct":3},{"id":"q-5b-044","fact_id":"s8-002","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are driving at 60 mph when a light rain wets the pavement. What speed is sensible?","options":["60 mph, since it is under the limit","50 to 55 mph, a drop of 5 to 10","58 mph, a slight trim","30 mph, half your speed"],"correct":1},{"id":"q-5b-045","fact_id":"s8-002","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of road surface and speed change is correct?","options":["Wet pavement: 5 to 10 mph less; packed snow: half speed","Wet pavement: half speed; packed snow: 5 to 10 mph less","Wet pavement: 5 to 10 mph less; packed snow: 5 mph at most","Wet pavement and packed snow: both 5 to 10 mph less"],"correct":0},{"id":"q-5b-046","fact_id":"s8-003","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What speed change is advised on packed snow?","options":["Reduce it by 5 to 10 mph","Reduce it by a quarter","Cut it to half your normal speed","Drive no faster than 5 mph"],"correct":2},{"id":"q-5b-047","fact_id":"s8-003","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You usually drive a mountain road at 40 mph, and today it is covered in packed snow. What speed fits?","options":["About 35 mph","About 20 mph","About 5 mph","About 30 mph"],"correct":1},{"id":"q-5b-048","fact_id":"s8-003","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of surface and speed is correct?","options":["Packed snow: 5 mph at most; ice: half speed","Packed snow and ice: both half speed","Packed snow: 5 to 10 mph less; ice: half speed","Packed snow: half speed; ice: 5 mph at most"],"correct":3},{"id":"q-5b-049","fact_id":"s8-004","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the highest speed advised on an iced-over road?","options":["15 mph","5 mph","25 mph","Half your normal speed"],"correct":1},{"id":"q-5b-050","fact_id":"s8-004","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your 35 mph street is glazed with ice, and the car feels like it is sliding. What speed fits?","options":["About 18 mph, half of normal","About 30 mph, with gentle braking","About 15 mph in a low gear","About 5 mph, barely above a walk"],"correct":3},{"id":"q-5b-051","fact_id":"s8-004","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"What separates 'cut 5 to 10 mph' from 'no more than 5 mph'?","options":["The first is for wet pavement and the second is for ice","The first is for ice and the second is for wet pavement","The first is for packed snow and the second is for wet pavement","They mean the same and apply to any slick road"],"correct":0},{"id":"q-5b-052","fact_id":"s8-005","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Heavy rain limits your view to under 100 feet. What is the top speed you should drive?","options":["40 mph","45 mph","30 mph","The posted limit, with lights on"],"correct":2},{"id":"q-5b-053","fact_id":"s8-005","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A heavy snow squall cuts your view to about two car lengths on a 65 mph highway. What is your speed?","options":["About 65 mph with low beams on","About 45 mph with flashers on","About 30 mph, no faster, until the view clears","About 55 mph, just a little slower"],"correct":2},{"id":"q-5b-054","fact_id":"s8-005","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"What sets the 30 mph figure for heavy rain or snow?","options":["How far you can see, about 100 feet or less","The posted speed limit for that road","How wet or slick the road surface is","The time of day or night when you drive"],"correct":0},{"id":"q-5b-055","fact_id":"s8-006","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When are high-beam headlights the right choice at night?","options":["In fog, to see farther through it","Any time it is dark, whatever the traffic","In rain, to light the wet road","On dark roads when no cars come toward you"],"correct":3},{"id":"q-5b-056","fact_id":"s8-006","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At 2 a.m. you drive an unlit country road and see no other headlights. Which setting best lights the road?","options":["Fog lamps alone, since they light the road edge","High beams, since no one is coming toward you","Low beams plus fog lamps, for extra light","Low beams only, to stay safe"],"correct":1},{"id":"q-5b-057","fact_id":"s8-006","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which of these nights is the one where high beams belong?","options":["A dark country road with no one coming","Dense fog on an empty road","Heavy rain on an empty road","A dark road with a car approaching"],"correct":0},{"id":"q-5b-058","fact_id":"s8-007","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"You are on high beams and a car approaches from the other direction. What do you do?","options":["Flash your high beams at it","Keep them on to see better","Switch to low beams until it passes","Turn off your headlights briefly"],"correct":2},{"id":"q-5b-059","fact_id":"s8-007","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On a mountain road with your high beams on, headlights appear around the bend ahead. What do you do?","options":["Stay on high beams until you are side by side","Switch to low beams before the car reaches you","Flash your high beams twice","Dim only if the other driver flashes first"],"correct":1},{"id":"q-5b-060","fact_id":"s8-007","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which sequence of lights is right on a dark road with an oncoming car?","options":["Low beams, then high beams as the car gets close","High beams the whole way, flashing when it is near","Low beams the whole way, high beams when passing it","High beams, then low beams as the car approaches"],"correct":3},{"id":"q-5b-061","fact_id":"s8-008","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which headlights should you use while driving in rain?","options":["High beams, so you see more of the wet road","Low beams, which cause less glare off the rain","Parking lights, so the rain does not reflect","High beams only if the rain is light"],"correct":1},{"id":"q-5b-062","fact_id":"s8-008","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At night in a downpour on an empty highway, you want more light. Which setting do you choose?","options":["High beams, since no one is coming","Fog lamps alone, since they sit low on the car","Fog lamps and high beams together","Low beams, since rain scatters high beams"],"correct":3},{"id":"q-5b-063","fact_id":"s8-008","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Why are high beams a poor choice in rain?","options":["The light reflects off the raindrops back into your eyes","They drain the battery much faster in wet weather","They shine too wide to show where the road edge is","They are too weak to light up wet pavement well"],"correct":0},{"id":"q-5b-064","fact_id":"s8-009","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which headlights should you use in dense fog or heavy smoke?","options":["High beams, to see farther","Parking lights, to avoid glare","Low beams only, so the light does not bounce back","High beams with fog lamps"],"correct":2},{"id":"q-5b-065","fact_id":"s8-009","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"On a freeway, smoke from a nearby fire drifts across the road. You are on high beams. What now?","options":["Keep high beams to cut through the smoke","Turn on your hazard flashers and keep high beams","Switch to low beams to cut the glare","Switch to parking lights to reduce glare"],"correct":2},{"id":"q-5b-066","fact_id":"s8-009","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"What do rain, fog and heavy smoke share when it comes to headlights?","options":["Low beams in all three","High beams in all three","Low beams in rain, high beams in fog and smoke","Parking lights in fog and smoke, low beams in rain"],"correct":0},{"id":"q-5b-067","fact_id":"s8-010","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Your dashboard shows a lights symbol, but only the parking lights are lit. What does night driving need?","options":["Nothing more, since the dash symbol shows your lights work","Parking lights and fog lamps, which are bright enough","Parking lights, if the street has lamps","Headlights, because parking lights alone are not enough"],"correct":3},{"id":"q-5b-068","fact_id":"s8-010","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"It is dusk and the dash shows a lights symbol, but you only turned on the parking lights. What do you do?","options":["Keep driving; the dash says the lights are on","Turn on the headlights now, before it gets darker","Turn on the hazard flashers instead","Wait until full dark to switch on the headlights"],"correct":1},{"id":"q-5b-069","fact_id":"s8-010","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which of these both lights the road and makes your car easy to see at night?","options":["Low-beam headlights","Parking lights","Daytime running lights","Fog lamps alone"],"correct":0},{"id":"q-5b-070","fact_id":"s8-011","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How do you check your blind spots before you change lanes?","options":["Look in the rearview mirror twice","Rely on your lane-change warning light","Look over your left and right shoulders","Lean forward and check the side mirror"],"correct":2},{"id":"q-5b-071","fact_id":"s8-011","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are backing out of a parking space between two large vans. What do you do?","options":["Rely on the rearview mirror and back out slowly","Look over both shoulders before and while you back","Back out quickly so cars can see you","Wait for someone to wave you out"],"correct":1},{"id":"q-5b-072","fact_id":"s8-011","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Why can mirrors alone not replace a shoulder check?","options":["Mirrors flip the picture, so you cannot judge a car's speed","The blind spot only exists behind a trailer","The blind spot is beside the car, but only on the passenger side","The blind spot sits beside the car where mirrors miss it"],"correct":3},{"id":"q-5b-073","fact_id":"s8-012","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Your tires skate on water and the car feels light. What should you do?","options":["Brake hard to stop the slide","Slow down gradually without braking hard","Steer sharply back and forth","Hold your speed steady until the tires grip again"],"correct":1},{"id":"q-5b-074","fact_id":"s8-012","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At 60 mph on a rain-soaked highway, the steering suddenly feels loose. What is your response?","options":["Slam on the brakes to stop the slide right away","Keep your speed and wait for the steering to firm up","Pull the wheel hard to the right to leave the lane","Ease off the gas smoothly and avoid hard braking"],"correct":3},{"id":"q-5b-075","fact_id":"s8-012","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A friend says to stomp the brake at the first sign of trouble, as when a deer jumps out. Why is that wrong when you hydroplane?","options":["Hard braking can lock the wheels and cost you control","The car stops too fast and the driver behind hits you","The car stops faster but the tires wear down quickly","Wet brakes grab unevenly and pull the car to one side"],"correct":0},{"id":"q-5b-076","fact_id":"s8b-001","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Where should the lap part of a seat belt sit on your body?","options":["Across your stomach","High across your lower ribs","Low and snug across your hips","Loose around your waist"],"correct":2},{"id":"q-5b-077","fact_id":"s8b-001","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A passenger in your back seat tucks the shoulder strap behind her back. What is wrong with that?","options":["Nothing, as long as the lap belt is snug","The strap should lie across her neck for a tight fit","The strap must cross her chest to do its job","The strap should lie low across her stomach"],"correct":2},{"id":"q-5b-078","fact_id":"s8b-001","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Who must wear a seat belt in a moving car?","options":["Everyone in the car, adults and children alike","The driver and front-seat passenger, but not the back seat","Anyone riding on a freeway, but not on city streets","Adults, since children use their own seats"],"correct":0},{"id":"q-5b-079","fact_id":"s8b-002","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How far should your breastbone be from the center of the steering wheel?","options":["No more than 10 inches","About 3 inches","About 5 inches","At least 10 inches"],"correct":3},{"id":"q-5b-080","fact_id":"s8b-002","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You sit about 5 inches from the steering wheel to reach the pedals easily. What should you do?","options":["Stay close; the seat belt will hold you back anyway","Move back or tilt the wheel so you are at least 10 inches away","Lean back while driving and only sit close when parking","Switch off the airbag to sit closer"],"correct":1},{"id":"q-5b-081","fact_id":"s8b-002","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"The 10-inch airbag figure is measured between which two points?","options":["The steering wheel center and your breastbone","Your knees and the lower edge of the dashboard","Your chin and the top rim of the steering wheel","Your lap and the bottom edge of the wheel"],"correct":0},{"id":"q-5b-082","fact_id":"s8b-003","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A child must stay rear-facing while all three of these are true. Which set of limits is right?","options":["Under 1 year, under 20 pounds, under 2 feet 6 inches","Under 4 years, under 60 pounds, under 4 feet","Under 2 years, under 40 pounds, under 3 feet 4 inches","Under 2 years, under 60 pounds, under 3 feet 4 inches"],"correct":2},{"id":"q-5b-083","fact_id":"s8b-003","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive your 18-month-old niece, who weighs 24 pounds and is 33 inches tall. Which seat do you use?","options":["A forward-facing seat, since she walks","A rear-facing child seat, since she is still under the limits","A booster seat in the rear","A regular seat belt in the rear"],"correct":1},{"id":"q-5b-084","fact_id":"s8b-003","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which child no longer has to ride rear-facing?","options":["A 14-month-old of 22 pounds and 30 inches","An 18-month-old of 25 pounds and 32 inches","A 23-month-old of 30 pounds and 34 inches","A 20-month-old of 41 pounds and 36 inches"],"correct":3},{"id":"q-5b-085","fact_id":"s8b-004","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Until what age must a child ride in a rear-seat car seat or booster, unless the law allows an exception?","options":["Age 4","Age 8","Age 6","Age 10"],"correct":1},{"id":"q-5b-086","fact_id":"s8b-004","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You offer a ride to a neighbor's 6-year-old who is about 3 feet 10 inches tall. You have no booster. What do you do?","options":["Seat her in the front passenger seat with the seat belt","Seat her in the rear seat with the adult belt pulled snug","Hold her on an adult's lap with the belt around both","Wait until she is in a rear-seat car seat or booster"],"correct":3},{"id":"q-5b-087","fact_id":"s8b-004","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pair of cutoffs is correct for child seats?","options":["Rear-facing until 2; rear-seat restraint until 8","Rear-facing until 4; rear-seat restraint until 12","Rear-facing until 8; rear-seat restraint until 2","Rear-facing until 1; rear-seat restraint until 6"],"correct":0},{"id":"q-5b-088","fact_id":"s8b-005","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which child has reached both marks that allow a regular rear-seat belt?","options":["A 9-year-old who is 4 feet 6 inches","A 7-year-old who is 4 feet 11 inches","A 9-year-old who is 4 feet 10 inches","A 5-year-old who is 3 feet 11 inches"],"correct":2},{"id":"q-5b-089","fact_id":"s8b-005","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive your 10-year-old cousin, who is 4 feet 11 inches tall. What does California law say about his rear-seat restraint?","options":["He must still ride in a car seat with a harness","He must use a booster seat until he turns 12","He may use a regular lap and shoulder belt now","He may use a regular belt only once he weighs 100 pounds"],"correct":2},{"id":"q-5b-090","fact_id":"s8b-005","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"What tells you a child can move to a regular rear-seat belt?","options":["Age 8 or older and a height of 4 feet 9 inches or more","A sixth birthday, whatever the child's height","A weight of at least 80 pounds on the scale","Sitting tall enough to see out of the window"],"correct":0},{"id":"q-5b-091","fact_id":"s8b-007","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Where should a pregnant driver place the lap belt?","options":["Across the middle of the belly","She may leave the lap belt off","Over the upper belly, under the breasts","Low, beneath the abdomen"],"correct":3},{"id":"q-5b-092","fact_id":"s8b-007","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A driver in her seventh month finds the lap belt riding over the top of her belly. What should she do?","options":["Leave it, since the belly gives a snug fit","Move it low beneath the abdomen so it rests on the hips","Put it under her arm to ease the pressure","Loosen it so it does not squeeze"],"correct":1},{"id":"q-5b-093","fact_id":"s8b-007","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which belt position is right for a pregnant driver?","options":["Lap belt low beneath the belly, strap between the breasts","Lap belt across the belly, strap between the breasts","Lap belt low beneath the belly, strap behind her back","Lap belt across the belly, strap over the arm"],"correct":0},{"id":"q-5b-094","fact_id":"s8b-008","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Why must a child stay out of a front seat that has a passenger airbag?","options":["Front seat belts are built too wide for a small child","The front seat has no anchor points for a child seat","A passenger airbag can seriously injure a child","The airbag fires too late to protect a small child"],"correct":2},{"id":"q-5b-095","fact_id":"s8b-008","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive a pickup with a passenger airbag. A 5-year-old begs to sit up front and promises to sit still. What do you do?","options":["Let her sit up front once she is buckled","Seat her in the back seat instead","Let her sit up front in a booster seat instead","Seat her in the back seat, belted loosely so she can lean forward"],"correct":1},{"id":"q-5b-096","fact_id":"s8b-008","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"The 10-inch airbag advice is for drivers. Why can it not be used to seat a child up front?","options":["Children must sit 20 inches from the dashboard instead","A child may sit there if the seat belt is pulled tight enough","It covers drivers older than 16, so a child is not affected","No child belongs in that seat; distance does not fix it"],"correct":3},{"id":"q-5b-097","fact_id":"s8c-004","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A tire blows out while you drive. What should you do?","options":["Brake as hard as possible to stop the car quickly","Hold the wheel firmly, ease off the gas and steer off the road","Steer sharply onto the shoulder as fast as you can","Switch off the engine at once and let the car coast to a stop on its own"],"correct":1},{"id":"q-5b-098","fact_id":"s8c-004","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At 65 mph there is a bang and your car pulls hard to the right. A front tire has blown. What is your first move?","options":["Hit the brakes as hard as you can, right away","Shift into neutral and coast to the shoulder","Pull the wheel to the right toward the shoulder at once","Grip the wheel with both hands and ease off the gas"],"correct":3},{"id":"q-5b-099","fact_id":"s8c-004","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing is correct?","options":["Blowout: ease off and leave the road; off the pavement: brake gently and steer back","Blowout: brake hard at once; wheels off the pavement: speed up to get back on","Blowout: steer back on the road; wheels off the pavement: ease off and pull to the side","Both: brake as hard as you can first, then steer back toward the lane"],"correct":0},{"id":"q-5b-100","fact_id":"s8c-005","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Your right wheels drop off the edge of the pavement. What is the first thing to do?","options":["Jerk the wheel left to get back on at once","Steer back onto the pavement gently, keeping your speed","Take your foot off the gas and brake gently","Brake as hard as you can"],"correct":2},{"id":"q-5b-101","fact_id":"s8c-005","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At highway speed your right-hand wheels slip onto the gravel shoulder. What do you do?","options":["Accelerate to pull back onto the pavement","Pull the wheel hard left to get back on at once","Ease off the gas, brake gently and steer carefully back","Hold your speed and ease the wheel back toward the pavement"],"correct":2},{"id":"q-5b-102","fact_id":"s8c-005","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Why not yank the wheel back at once when your wheels leave the pavement?","options":["A sharp pull can send the car across the road","Steering does nothing once a wheel is off the pavement","The pavement edge is too high to climb back onto","The car only comes back if you go straight until it stops"],"correct":0},{"id":"q-5b-103","fact_id":"s8c-006","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Your car breaks down on a freeway. Where should you steer it?","options":["To the left shoulder, beside the divider","Onto the center median","Stop in your lane with the hazard flashers on","To the right shoulder, away from fast traffic"],"correct":3},{"id":"q-5b-104","fact_id":"s8c-006","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your engine dies in the middle lane of a three-lane freeway. You still have some speed. What do you do?","options":["Stay in the middle lane with the hazard flashers on","Steer toward the right shoulder, signaling and checking","Coast to the left shoulder, since it is just as close","Leave the car and wave down other drivers for help"],"correct":1},{"id":"q-5b-105","fact_id":"s8c-006","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Your car is disabled on the right shoulder and no one is hurt. Which number does the handbook point you to for help?","options":["511","911","411","311"],"correct":0},{"id":"q-5b-106","fact_id":"s8c-007","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How may an adult driver use a cell phone?","options":["Held in your hand, as long as the speaker is switched on","Resting on the passenger seat, tapped when it rings","Only in hands-free mode, such as a dock or voice system","Held in your hand, but only while stopped at a red light"],"correct":2},{"id":"q-5b-107","fact_id":"s8c-007","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your phone rings while you drive and it sits in a dashboard dock. Which choice follows the law?","options":["Pick it up briefly and say you will call back later","Answer through the car's hands-free system, or let it ring","Hold it against your chest and answer using the speaker button","Tilt it in your lap and tap the screen to answer"],"correct":1},{"id":"q-5b-108","fact_id":"s8c-007","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which of these counts as hands-free use?","options":["Phone held in your hand and used on speaker","Phone on the seat beside you, answered with one quick tap of the screen","Phone cradled between your shoulder and your ear","Phone in a dock, called through the car's voice system"],"correct":3},{"id":"q-5b-109","fact_id":"s8c-008","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What is the cell phone rule for a driver under 18?","options":["Hands-free use is allowed, but handheld use is not","No use at all, except a 911 call in an emergency","Only texting is banned; talking on the phone is allowed","Use is allowed whenever a licensed parent rides along"],"correct":1},{"id":"q-5b-110","fact_id":"s8c-008","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A 17-year-old driver sees a serious crash ahead with injured people. May the teen use a phone?","options":["No use at all, even for 911","Text a friend to call for help","Call a parent hands-free, which is allowed","Call 911; that is the one emergency exception"],"correct":3},{"id":"q-5b-111","fact_id":"s8c-008","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A 17-year-old and a 35-year-old both use a hands-free earpiece while driving. Which statement is right?","options":["The 35-year-old is allowed; the 17-year-old is not","Both are allowed, since the phone is hands-free","Neither is allowed, since all drivers are banned","The 17-year-old is allowed; the 35-year-old is not"],"correct":0},{"id":"q-5b-112","fact_id":"s8c-009","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which of these is illegal for every driver, whatever the age?","options":["Listening to spoken directions from a map app","Using a hands-free voice call","Sending, reading or answering text messages","Changing the radio station"],"correct":2},{"id":"q-5b-113","fact_id":"s8c-009","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your phone buzzes with a text while you drive on the highway. What do you do?","options":["Glance at it quickly if the road is straight","Read it but do not reply until you stop","Wait until you have safely stopped, then read it","Type a short reply at a stretch of light traffic"],"correct":2},{"id":"q-5b-114","fact_id":"s8c-009","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"In slow, stop-and-go traffic, which statement about texts is right?","options":["Reading and sending by hand is still illegal","Sending is allowed under 5 mph","Reading is allowed, but sending is not","Texts are allowed for drivers over 25"],"correct":0},{"id":"q-5b-115","fact_id":"s9_p11_run2-002","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What decides whether a legally prescribed medicine can lead to a DUI charge?","options":["Whether a doctor prescribed it","Whether you took it with alcohol","Whether you bought it over the counter","Whether it impairs your driving"],"correct":3},{"id":"q-5b-116","fact_id":"s9_p11_run2-002","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"Your doctor prescribes a strong pain medicine and the label warns it may cause drowsiness. You feel foggy. What do you do?","options":["Go ahead, since a prescribed medicine is legal","Do not drive until you can do so safely","Halve the dose, then drive","Stay on quiet side streets only"],"correct":1},{"id":"q-5b-117","fact_id":"s9_p11_run2-002","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"What does DUI law cover?","options":["Alcohol, plus any drug that impairs driving, prescribed or not","Alcohol and illegal drugs, but not medicines","Alcohol alone, since other drugs fall under other laws","Alcohol, and prescription drugs only when mixed with it"],"correct":0},{"id":"q-5b-118","fact_id":"s9_p11_run2-017","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Drowsy driving hurts reaction time and judgment in a way most like which condition?","options":["Driving with a cold","Driving while hungry","Driving after drinking alcohol","Driving with the sun in your eyes"],"correct":2},{"id":"q-5b-119","fact_id":"s9_p11_run2-017","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You have been awake for 20 hours and plan to drive home. You think you are safe because you had no alcohol. What is a better way to see it?","options":["Tiredness only affects your speed, not your judgment","Your reactions and judgment may be as poor as a drinker's","You are fine if you feel alert","The risk is only at night"],"correct":1},{"id":"q-5b-120","fact_id":"s9_p11_run2-017","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"One driver had two drinks. Another has been awake for 24 hours. Which statement fits?","options":["Only the drinker's reactions and judgment are affected","Only the sleepy driver's reactions and judgment are affected","Both are affected, but only the drinker needs to stop","Both may have slow reactions and poor judgment"],"correct":3},{"id":"q-5b-121","fact_id":"s9_p11_run2-018","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What should a dangerously tired driver do?","options":["Open the window and turn up the radio","Pull over somewhere safe and rest","Speed up to arrive sooner","Stop for coffee at the next exit and then drive on"],"correct":1},{"id":"q-5b-122","fact_id":"s9_p11_run2-018","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"At 2 a.m. on a highway your eyelids keep drooping and the next town is 30 miles away. What do you do?","options":["Crank the radio up loud and keep going to town","Speed up to reach the next town sooner","Pull over for a minute, splash your face, then drive on","Take the next safe exit or rest area and rest"],"correct":3},{"id":"q-5b-123","fact_id":"s9_p11_run2-018","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which fix works for both a drunk driver and a dangerously tired driver?","options":["Not driving until the impairment has passed","Opening the windows for cold fresh air","Slowing down a little and driving on carefully","Drinking several cups of strong black coffee"],"correct":0}]`),i={tag:e,batches:t,blueprint:a,questions:o};export{t as batches,a as blueprint,i as default,o as questions,e as tag};
